{
  "name": "Nexus Operations",
  "description": "A high-performance, metric-centric project management interface for Automation, AI, and Data workflows."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ContextType = 'Automation' | 'AI' | 'Data';

export type Priority = 'Low' | 'Medium' | 'High';

export type Status = 'backlog' | 'todo' | 'inprogress' | 'review' | 'done';

export interface Attachment {
  id: string;
  name: string;
  type: string; // 'image', 'pdf', 'other'
  url: string;
  size?: string;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  context: ContextType;
  status: Status;
  priority: Priority;
  progress: number; // 0-100
  tags: string[];
  attachments: Attachment[];
  dueDate?: string;
  assignee?: string;
  createdAt: string;
}

export interface Metric {
  label: string;
  value: string | number;
  trend: 'up' | 'down' | 'neutral';
  trendValue: string;
}

import React from 'react';
import { LayoutGrid, Cpu, Database, Settings, Activity } from 'lucide-react';
import { ContextType } from '../types';

interface SidebarProps {
  currentContext: ContextType;
  setContext: (ctx: ContextType) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ currentContext, setContext }) => {
  const navItems: { id: ContextType; icon: React.ReactNode; label: string }[] = [
    { id: 'Automation', icon: <Settings size={20} />, label: 'Automation' },
    { id: 'AI', icon: <Cpu size={20} />, label: 'AI Intelligence' },
    { id: 'Data', icon: <Database size={20} />, label: 'Data Ops' },
  ];

  return (
    <aside className="w-64 h-screen bg-nexus-bg border-r border-nexus-border flex flex-col flex-shrink-0 z-20">
      <div className="h-16 flex items-center px-6 border-b border-nexus-border">
        <div className="flex items-center gap-2 text-nexus-text font-bold tracking-tight">
          <div className="w-6 h-6 bg-nexus-cobalt rounded-sm flex items-center justify-center">
             <LayoutGrid size={14} className="text-white" />
          </div>
          <span className="font-mono">NEXUS_OS</span>
        </div>
      </div>

      <div className="flex-1 py-6 px-3 space-y-1">
        <div className="px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">Contexts</div>
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setContext(item.id)}
            className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all duration-200 group ${
              currentContext === item.id
                ? 'bg-nexus-card text-nexus-cobalt border-l-2 border-nexus-cobalt'
                : 'text-nexus-muted hover:text-nexus-text hover:bg-neutral-900'
            }`}
          >
            <span className={`${currentContext === item.id ? 'text-nexus-cobalt' : 'text-nexus-muted group-hover:text-nexus-text'}`}>
              {item.icon}
            </span>
            {item.label}
          </button>
        ))}

        <div className="mt-8 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">System</div>
        <button className="w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium text-nexus-muted hover:text-nexus-text hover:bg-neutral-900 transition-colors">
          <Activity size={20} />
          <span>Monitoring</span>
        </button>
      </div>

      <div className="p-4 border-t border-nexus-border">
        <div className="flex items-center gap-3 px-2">
          <div className="w-8 h-8 rounded bg-gradient-to-br from-nexus-cobalt to-purple-600 flex items-center justify-center text-xs font-bold text-white">
            JD
          </div>
          <div className="flex flex-col">
            <span className="text-xs font-medium text-nexus-text">Jane Doe</span>
            <span className="text-[10px] text-nexus-muted font-mono">Senior Engineer</span>
          </div>
        </div>
      </div>
    </aside>
  );
};

import React, { useMemo } from 'react';
import { Task, ContextType } from '../types';
import { TrendingUp, TrendingDown, Clock, CheckCircle2 } from 'lucide-react';

interface MetricsHeaderProps {
  tasks: Task[];
  context: ContextType;
}

export const MetricsHeader: React.FC<MetricsHeaderProps> = ({ tasks, context }) => {
  const metrics = useMemo(() => {
    const total = tasks.length;
    const done = tasks.filter(t => t.status === 'done').length;
    const inProgress = tasks.filter(t => t.status === 'inprogress').length;

    // Calculate simple completion rate
    const completionRate = total === 0 ? 0 : Math.round((done / total) * 100);

    // Calculate "velocity" (mocked based on progress of active tasks)
    const activeTasks = tasks.filter(t => t.status === 'inprogress' || t.status === 'review');
    const velocity = activeTasks.reduce((acc, curr) => acc + curr.progress, 0) / (activeTasks.length || 1);

    return [
      { label: 'Active Tasks', value: total - done, icon: Clock, color: 'text-nexus-text' },
      { label: 'Completion', value: `${completionRate}%`, icon: CheckCircle2, color: 'text-nexus-cobalt' },
      { label: 'Avg Velocity', value: Math.round(velocity), icon: TrendingUp, color: 'text-nexus-accent' },
    ];
  }, [tasks]);

  return (
    <header className="h-20 border-b border-nexus-border bg-nexus-bg/80 backdrop-blur-md sticky top-0 z-10 flex items-center justify-between px-8">
      <div>
        <h1 className="text-xl font-bold text-nexus-text tracking-tight flex items-center gap-2">
          {context} <span className="text-nexus-muted font-light">Operations</span>
        </h1>
        <p className="text-xs text-nexus-muted font-mono mt-0.5">Updated just now</p>
      </div>

      <div className="flex items-center gap-8">
        {metrics.map((metric, idx) => (
          <div key={idx} className="flex flex-col items-end">
             <div className="flex items-center gap-2">
                <span className="text-[10px] uppercase tracking-wider font-mono text-nexus-muted">{metric.label}</span>
                <metric.icon size={12} className={metric.color} />
             </div>
             <span className={`text-xl font-bold font-mono ${metric.color}`}>{metric.value}</span>
          </div>
        ))}
      </div>
    </header>
  );
};

import React from 'react';
import { Task, Priority } from '../types';
import { Paperclip, MoreHorizontal, AlertCircle } from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
}

const PriorityBadge: React.FC<{ priority: Priority }> = ({ priority }) => {
  const colors = {
    Low: 'bg-neutral-800 text-neutral-400 border-neutral-700',
    Medium: 'bg-blue-900/20 text-blue-400 border-blue-900/30',
    High: 'bg-amber-900/20 text-amber-500 border-amber-900/30',
  };

  return (
    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider font-bold ${colors[priority]}`}>
      {priority}
    </span>
  );
};

export const TaskCard: React.FC<TaskCardProps> = ({ task, onEdit }) => {
  // Determine border color based on priority for quick visual scan
  const borderLeftColor = 
    task.priority === 'High' ? 'border-l-nexus-accent' : 
    task.priority === 'Medium' ? 'border-l-nexus-cobalt' : 'border-l-neutral-600';

  return (
    <div 
      onClick={() => onEdit(task)}
      className={`
        group relative bg-nexus-card border border-nexus-border rounded hover:border-nexus-muted/50 transition-all duration-200 cursor-pointer overflow-hidden
        border-l-[3px] ${borderLeftColor} p-3 mb-3
      `}
    >
      <div className="flex justify-between items-start mb-2">
        <PriorityBadge priority={task.priority} />
        {task.progress === 100 && <div className="h-1.5 w-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
      </div>

      <h3 className="text-sm font-medium text-nexus-text leading-tight mb-2 line-clamp-2 group-hover:text-white transition-colors">
        {task.title}
      </h3>

      <div className="flex items-center gap-2 mb-3 flex-wrap">
        {task.tags.slice(0, 3).map((tag, i) => (
          <span key={i} className="text-[10px] text-nexus-muted font-mono bg-neutral-900 px-1 rounded">
            #{tag}
          </span>
        ))}
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-neutral-800 h-1 rounded-full overflow-hidden mb-3">
        <div 
          className={`h-full transition-all duration-500 ${task.priority === 'High' ? 'bg-nexus-accent' : 'bg-nexus-cobalt'}`} 
          style={{ width: `${task.progress}%` }}
        ></div>
      </div>

      <div className="flex justify-between items-center text-nexus-muted">
        <div className="flex items-center gap-3">
          {task.attachments.length > 0 && (
            <div className="flex items-center gap-1 text-[10px]">
              <Paperclip size={10} />
              <span>{task.attachments.length}</span>
            </div>
          )}
        </div>

        <div className="opacity-0 group-hover:opacity-100 transition-opacity">
            <MoreHorizontal size={14} />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment } from '../types';
import { X, Upload, FileText, Trash2, Save, Calendar, Tag } from 'lucide-react';
import { STATUS_COLUMNS } from '../constants';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentContext: string;
}

export const TaskModal: React.FC<TaskModalProps> = ({ task, isOpen, onClose, onSave, onDelete, currentContext }) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    status: 'todo',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
  });
  const [tagInput, setTagInput] = useState('');

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        status: 'todo',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        context: currentContext as any,
      });
    }
  }, [task, isOpen, currentContext]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', // Simple check
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  const addTag = () => {
    if (tagInput.trim()) {
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
      <div className="w-[600px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-nexus-border">
          <h2 className="text-lg font-bold text-nexus-text font-mono tracking-tight">
            {task ? 'EDIT NODE' : 'NEW ENTRY'}
          </h2>
          <button onClick={onClose} className="text-nexus-muted hover:text-white transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">

          {/* Title */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Title</label>
            <input 
              type="text" 
              value={formData.title} 
              onChange={(e) => setFormData({...formData, title: e.target.value})}
              className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors"
              placeholder="Task name..."
            />
          </div>

          {/* Description */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Description</label>
            <textarea 
              value={formData.description} 
              onChange={(e) => setFormData({...formData, description: e.target.value})}
              rows={4}
              className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none"
              placeholder="Detailed description..."
            />
          </div>

          {/* Row: Status, Priority, Progress */}
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Status</label>
              <select 
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
              >
                {STATUS_COLUMNS.map(col => (
                  <option key={col.id} value={col.id}>{col.label}</option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Priority</label>
              <select 
                value={formData.priority}
                onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                className="w-full bg-neutral-900 border border-neutral-700 rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
              >
                <option value="Low">Low</option>
                <option value="Medium">Medium</option>
                <option value="High">High</option>
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Progress ({formData.progress}%)</label>
              <input 
                type="range" 
                min="0" 
                max="100" 
                value={formData.progress}
                onChange={(e) => setFormData({...formData, progress: parseInt(e.target.value)})}
                className="w-full h-2 bg-neutral-800 rounded-lg appearance-none cursor-pointer accent-nexus-cobalt mt-3"
              />
            </div>
          </div>

          {/* Tags */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Tags</label>
            <div className="flex gap-2 mb-2 flex-wrap">
              {formData.tags?.map((tag, idx) => (
                <span key={idx} className="bg-neutral-800 text-xs px-2 py-1 rounded border border-neutral-700 flex items-center gap-1">
                  #{tag}
                  <button onClick={() => setFormData({...formData, tags: formData.tags?.filter(t => t !== tag)})} className="hover:text-red-400"><X size={10} /></button>
                </span>
              ))}
            </div>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <Tag size={14} className="absolute left-3 top-3 text-nexus-muted" />
                <input 
                  type="text" 
                  value={tagInput}
                  onChange={(e) => setTagInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && addTag()}
                  className="w-full pl-9 bg-neutral-900 border border-neutral-700 rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                  placeholder="Add tag and press Enter"
                />
              </div>
            </div>
          </div>

          {/* Attachments */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold flex justify-between">
              <span>Attachments</span>
              <span className="text-[10px] font-normal lowercase opacity-70">Supports images & pdf</span>
            </label>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {formData.attachments?.map(att => (
                <div key={att.id} className="flex items-center gap-3 p-2 bg-neutral-900 border border-neutral-700 rounded">
                  {att.type === 'image' ? (
                     <img src={att.url} alt="prev" className="w-8 h-8 object-cover rounded" />
                  ) : (
                    <div className="w-8 h-8 bg-neutral-800 flex items-center justify-center rounded"><FileText size={14} /></div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs truncate text-nexus-text">{att.name}</p>
                  </div>
                  <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500"><X size={14} /></button>
                </div>
              ))}
            </div>

            <div className="relative group">
              <input 
                type="file" 
                onChange={handleFileChange} 
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
              />
              <div className="border border-dashed border-neutral-600 rounded p-4 flex items-center justify-center gap-2 text-nexus-muted group-hover:border-nexus-cobalt group-hover:text-nexus-cobalt transition-colors">
                <Upload size={16} />
                <span className="text-sm">Upload File</span>
              </div>
            </div>
          </div>

        </div>

        {/* Footer */}
        <div className="p-6 border-t border-nexus-border flex justify-between bg-neutral-900/50">
          {task ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-4 py-2 text-sm text-red-500 hover:bg-red-900/20 rounded transition-colors"
            >
              <Trash2 size={16} /> Delete
            </button>
          ) : <div></div>}

          <button 
            onClick={() => onSave(formData as Task)}
            className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-700 text-white text-sm font-medium rounded transition-all shadow-lg shadow-blue-900/20"
          >
            <Save size={16} /> Save Changes
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { Task, ContextType, Status } from './types';
import { INITIAL_TASKS, STATUS_COLUMNS } from './constants';
import { Plus } from 'lucide-react';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [currentContext, setCurrentContext] = useState<ContextType>('AI');

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);

  // Filtered Tasks
  const contextTasks = tasks.filter(t => t.context === currentContext);

  const handleCreateTask = () => {
    setSelectedTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task: Task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskData: Task) => {
    if (selectedTask) {
      // Update
      setTasks(prev => prev.map(t => t.id === taskData.id ? taskData : t));
    } else {
      // Create
      const newTask: Task = {
        ...taskData,
        id: `t-${Date.now()}`,
        createdAt: new Date().toISOString(),
        context: currentContext // Ensure context is current
      };
      setTasks(prev => [...prev, newTask]);
    }
    setIsModalOpen(false);
  };

  const handleDeleteTask = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
    setIsModalOpen(false);
  };

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white">
      {/* Sidebar Navigation */}
      <Sidebar 
        currentContext={currentContext} 
        setContext={setCurrentContext} 
      />

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">
        <MetricsHeader tasks={contextTasks} context={currentContext} />

        {/* Kanban Board Area */}
        <main className="flex-1 overflow-x-auto overflow-y-hidden p-6">
           <div className="flex h-full gap-4 min-w-[1000px]">
              {STATUS_COLUMNS.map(col => {
                const colTasks = contextTasks.filter(t => t.status === col.id);

                return (
                  <div key={col.id} className="flex-1 min-w-[280px] flex flex-col h-full">
                    {/* Column Header */}
                    <div className="flex items-center justify-between mb-4 pb-2 border-b border-nexus-border">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                          {col.label}
                        </span>
                        <span className="text-[10px] text-nexus-muted bg-neutral-900 px-1.5 py-0.5 rounded font-mono border border-neutral-800">
                          {colTasks.length}
                        </span>
                      </div>
                      <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                    </div>

                    {/* Column Content */}
                    <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-20">
                      {colTasks.length > 0 ? (
                        colTasks.map(task => (
                          <TaskCard 
                            key={task.id} 
                            task={task} 
                            onEdit={handleEditTask} 
                            onDelete={handleDeleteTask} 
                          />
                        ))
                      ) : (
                        <div className="h-24 border border-dashed border-neutral-800 rounded flex items-center justify-center text-nexus-muted text-xs italic">
                          No active items
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
           </div>
        </main>

        {/* Floating Action Button */}
        <button 
          onClick={handleCreateTask}
          className="absolute bottom-8 right-8 h-14 w-14 bg-nexus-accent hover:bg-amber-400 text-black rounded-full shadow-[0_4px_20px_rgba(234,179,8,0.4)] flex items-center justify-center transition-all duration-300 hover:scale-105 z-30"
        >
          <Plus size={28} strokeWidth={2.5} />
        </button>
      </div>

      {/* Modal */}
      <TaskModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentContext={currentContext}
      />
    </div>
  );
};

export default App;

{
  "name": "Luck - Dashboard de Projetos",
  "description": "Uma interface de gestão de projetos de alta performance centrada em métricas.",
  "requestFramePermissions": []
}

export interface User {
  id: string;
  username: string;
}

export interface Project {
  id: string;
  name: string;
  ownerId: string;
  sharedWith: string[]; // List of usernames
}

export type Priority = 'Low' | 'Medium' | 'High';

export type Status = 'backlog' | 'todo' | 'inprogress' | 'review' | 'done';

export interface Attachment {
  id: string;
  name: string;
  type: string; // 'image', 'pdf', 'other'
  url: string;
  size?: string;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  projectId: string; // Changed from context
  status: Status;
  priority: Priority;
  progress: number; // 0-100
  tags: string[];
  attachments: Attachment[];
  dueDate?: string;
  assignee?: string;
  createdAt: string;
}

