import React, { useState } from 'react';
import { LayoutGrid, ArrowRight } from 'lucide-react';
import { User } from '../types';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!username.trim()) {
      setError('Por favor digite um usuário.');
      return;
    }

    const usersStr = localStorage.getItem('luck_users');
    const users: User[] = usersStr ? JSON.parse(usersStr) : [];

    const existingUser = users.find(u => u.username.toLowerCase() === username.toLowerCase());

    if (isRegister) {
      if (existingUser) {
        setError('Usuário já existe.');
        return;
      }
      const newUser: User = { id: Date.now().toString(), username };
      localStorage.setItem('luck_users', JSON.stringify([...users, newUser]));
      onLogin(newUser);
    } else {
      if (!existingUser) {
        setError('Usuário não encontrado. Crie uma conta.');
        return;
      }
      onLogin(existingUser);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center">
      <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl">
        <div className="flex flex-col items-center mb-8">
          <div className="w-12 h-12 bg-nexus-cobalt rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-blue-900/50">
             <LayoutGrid size={24} className="text-white" />
          </div>
          <h1 className="text-2xl font-bold text-nexus-text font-mono tracking-tight">LUCK OS</h1>
          <p className="text-sm text-nexus-muted mt-2">Plataforma de Gestão Analítica</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="text-xs uppercase font-bold text-nexus-muted mb-1 block">Usuário</label>
            <input 
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors"
              placeholder="Digite seu usuário..."
            />
          </div>

          {error && <p className="text-red-500 text-xs">{error}</p>}

          <button 
            type="submit"
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-3 rounded transition-all flex items-center justify-center gap-2"
          >
            {isRegister ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
          </button>
        </form>

        <div className="mt-6 text-center">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {isRegister ? 'Já tem conta? Entrar' : 'Não tem conta? Registrar'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Project } from '../types';
import { X, Save, Share2, Plus } from 'lucide-react';

interface ProjectModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (name: string) => void;
  onShare: (username: string) => void;
  mode: 'create' | 'share';
  projectToShare?: Project | null;
}

export const ProjectModal: React.FC<ProjectModalProps> = ({ isOpen, onClose, onSave, onShare, mode, projectToShare }) => {
  const [inputVal, setInputVal] = useState('');

  if (!isOpen) return null;

  const handleSubmit = () => {
    if (!inputVal.trim()) return;
    if (mode === 'create') {
      onSave(inputVal);
    } else {
      onShare(inputVal);
    }
    setInputVal('');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[400px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col">
        <div className="flex justify-between items-center p-4 border-b border-nexus-border">
          <h2 className="text-sm font-bold text-nexus-text font-mono tracking-tight uppercase">
            {mode === 'create' ? 'Novo Projeto' : `Compartilhar: ${projectToShare?.name}`}
          </h2>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={18} />
          </button>
        </div>

        <div className="p-6">
          <label className="text-xs uppercase font-bold text-nexus-muted mb-2 block">
            {mode === 'create' ? 'Nome do Projeto' : 'Nome do Usuário para Compartilhar'}
          </label>
          <input 
            type="text"
            value={inputVal}
            onChange={(e) => setInputVal(e.target.value)}
            className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none"
            placeholder={mode === 'create' ? "Ex: Marketing Q3..." : "Ex: joaosilva..."}
            onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
          />
        </div>

        <div className="p-4 border-t border-nexus-border flex justify-end">
          <button 
            onClick={handleSubmit}
            className="flex items-center gap-2 px-4 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
          >
            {mode === 'create' ? <><Plus size={14} /> Criar</> : <><Share2 size={14} /> Compartilhar</>}
          </button>
        </div>
      </div>
    </div>
  );
};

