import React, { useMemo } from 'react';
import { Task, Project } from '../types';
import { TrendingUp, Clock, CheckCircle2 } from 'lucide-react';

interface MetricsHeaderProps {
  tasks: Task[];
  project?: Project;
}

export const MetricsHeader: React.FC<MetricsHeaderProps> = ({ tasks, project }) => {
  const metrics = useMemo(() => {
    const total = tasks.length;
    const done = tasks.filter(t => t.status === 'done').length;

    // Calculate simple completion rate
    const completionRate = total === 0 ? 0 : Math.round((done / total) * 100);

    // Calculate "velocity" (mocked based on progress of active tasks)
    const activeTasks = tasks.filter(t => t.status === 'inprogress' || t.status === 'review');
    const velocity = activeTasks.reduce((acc, curr) => acc + curr.progress, 0) / (activeTasks.length || 1);

    return [
      { label: 'Tarefas Ativas', value: total - done, icon: Clock, color: 'text-nexus-text' },
      { label: 'Conclusão', value: `${completionRate}%`, icon: CheckCircle2, color: 'text-nexus-cobalt' },
      { label: 'Velocidade', value: Math.round(velocity), icon: TrendingUp, color: 'text-nexus-accent' },
    ];
  }, [tasks]);

  return (
    <header className="h-20 border-b border-nexus-border bg-nexus-bg/80 backdrop-blur-md sticky top-0 z-10 flex items-center justify-between px-8">
      <div>
        <h1 className="text-xl font-bold text-nexus-text tracking-tight flex items-center gap-2">
          {project ? project.name : 'Dashboard'} <span className="text-nexus-muted font-light hidden sm:inline-block">Overview</span>
        </h1>
        <p className="text-xs text-nexus-muted font-mono mt-0.5">
           {project ? (project.sharedWith.length > 0 ? `Compartilhado com ${project.sharedWith.length} usuários` : 'Privado') : 'Selecione um projeto'}
        </p>
      </div>

      <div className="flex items-center gap-8">
        {metrics.map((metric, idx) => (
          <div key={idx} className="flex flex-col items-end">
             <div className="flex items-center gap-2">
                <span className="text-[10px] uppercase tracking-wider font-mono text-nexus-muted">{metric.label}</span>
                <metric.icon size={12} className={metric.color} />
             </div>
             <span className={`text-xl font-bold font-mono ${metric.color}`}>{metric.value}</span>
          </div>
        ))}
      </div>
    </header>
  );
};

import React from 'react';
import { Task, Priority } from '../types';
import { Paperclip, MoreHorizontal } from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
}

const PriorityBadge: React.FC<{ priority: Priority }> = ({ priority }) => {
  const colors = {
    Low: 'bg-neutral-200 text-neutral-600 border-neutral-300 dark:bg-neutral-800 dark:text-neutral-400 dark:border-neutral-700',
    Medium: 'bg-blue-100 text-blue-600 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/30',
    High: 'bg-amber-100 text-amber-600 border-amber-200 dark:bg-amber-900/20 dark:text-amber-500 dark:border-amber-900/30',
  };

  return (
    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider font-bold ${colors[priority]}`}>
      {priority === 'Low' ? 'Baixa' : priority === 'Medium' ? 'Média' : 'Alta'}
    </span>
  );
};

export const TaskCard: React.FC<TaskCardProps> = ({ task, onEdit }) => {
  // Determine border color based on priority
  const borderLeftColor = 
    task.priority === 'High' ? 'border-l-nexus-accent' : 
    task.priority === 'Medium' ? 'border-l-nexus-cobalt' : 'border-l-gray-400 dark:border-l-neutral-600';

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('taskId', task.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  return (
    <div 
      draggable
      onDragStart={handleDragStart}
      onClick={() => onEdit(task)}
      className={`
        group relative bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt/50 transition-all duration-200 cursor-grab active:cursor-grabbing overflow-hidden
        border-l-[3px] ${borderLeftColor} p-3 mb-3 shadow-sm hover:shadow-md
      `}
    >
      <div className="flex justify-between items-start mb-2">
        <PriorityBadge priority={task.priority} />
        {task.progress === 100 && <div className="h-1.5 w-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
      </div>

      <h3 className="text-sm font-medium text-nexus-text leading-tight mb-2 line-clamp-2 group-hover:text-nexus-cobalt transition-colors">
        {task.title}
      </h3>

      <div className="flex items-center gap-2 mb-3 flex-wrap">
        {task.tags.slice(0, 3).map((tag, i) => (
          <span key={i} className="text-[10px] text-nexus-muted font-mono bg-nexus-bg border border-nexus-border px-1 rounded">
            #{tag}
          </span>
        ))}
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-nexus-bg h-1 rounded-full overflow-hidden mb-3">
        <div 
          className={`h-full transition-all duration-500 ${task.priority === 'High' ? 'bg-nexus-accent' : 'bg-nexus-cobalt'}`} 
          style={{ width: `${task.progress}%` }}
        ></div>
      </div>

      <div className="flex justify-between items-center text-nexus-muted">
        <div className="flex items-center gap-3">
          {task.attachments.length > 0 && (
            <div className="flex items-center gap-1 text-[10px]">
              <Paperclip size={10} />
              <span>{task.attachments.length}</span>
            </div>
          )}
        </div>

        <div className="opacity-0 group-hover:opacity-100 transition-opacity">
            <MoreHorizontal size={14} />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag } from 'lucide-react';
import { STATUS_COLUMNS } from '../constants';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
}

export const TaskModal: React.FC<TaskModalProps> = ({ task, isOpen, onClose, onSave, onDelete, currentProjectId }) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    status: 'todo',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
  });
  const [tagInput, setTagInput] = useState('');

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        status: 'todo',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        projectId: currentProjectId,
      });
    }
  }, [task, isOpen, currentProjectId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  const addTag = () => {
    if (tagInput.trim()) {
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[600px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-nexus-border">
          <h2 className="text-lg font-bold text-nexus-text font-mono tracking-tight">
            {task ? 'EDITAR TAREFA' : 'NOVA TAREFA'}
          </h2>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">

          {/* Title */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Título</label>
            <input 
              type="text" 
              value={formData.title} 
              onChange={(e) => setFormData({...formData, title: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors"
              placeholder="Nome da tarefa..."
            />
          </div>

          {/* Description */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Descrição</label>
            <textarea 
              value={formData.description} 
              onChange={(e) => setFormData({...formData, description: e.target.value})}
              rows={4}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none"
              placeholder="Detalhes da tarefa..."
            />
          </div>

          {/* Row: Status, Priority, Progress */}
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Status</label>
              <select 
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
              >
                {STATUS_COLUMNS.map(col => (
                  <option key={col.id} value={col.id}>{col.label}</option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Prioridade</label>
              <select 
                value={formData.priority}
                onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
              >
                <option value="Low">Baixa</option>
                <option value="Medium">Média</option>
                <option value="High">Alta</option>
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Progresso ({formData.progress}%)</label>
              <input 
                type="range" 
                min="0" 
                max="100" 
                value={formData.progress}
                onChange={(e) => setFormData({...formData, progress: parseInt(e.target.value)})}
                className="w-full h-2 bg-nexus-bg rounded-lg appearance-none cursor-pointer accent-nexus-cobalt mt-3 border border-nexus-border"
              />
            </div>
          </div>

          {/* Tags */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Tags</label>
            <div className="flex gap-2 mb-2 flex-wrap">
              {formData.tags?.map((tag, idx) => (
                <span key={idx} className="bg-nexus-bg text-nexus-text text-xs px-2 py-1 rounded border border-nexus-border flex items-center gap-1">
                  #{tag}
                  <button onClick={() => setFormData({...formData, tags: formData.tags?.filter(t => t !== tag)})} className="hover:text-red-400"><X size={10} /></button>
                </span>
              ))}
            </div>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <Tag size={14} className="absolute left-3 top-3 text-nexus-muted" />
                <input 
                  type="text" 
                  value={tagInput}
                  onChange={(e) => setTagInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && addTag()}
                  className="w-full pl-9 bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                  placeholder="Adicionar tag e Enter..."
                />
              </div>
            </div>
          </div>

          {/* Attachments */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold flex justify-between">
              <span>Anexos</span>
              <span className="text-[10px] font-normal lowercase opacity-70">Imagens & pdf</span>
            </label>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {formData.attachments?.map(att => (
                <div key={att.id} className="flex items-center gap-3 p-2 bg-nexus-bg border border-nexus-border rounded">
                  {att.type === 'image' ? (
                     <img src={att.url} alt="prev" className="w-8 h-8 object-cover rounded" />
                  ) : (
                    <div className="w-8 h-8 bg-nexus-border flex items-center justify-center rounded text-nexus-text"><FileText size={14} /></div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs truncate text-nexus-text">{att.name}</p>
                  </div>
                  <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500"><X size={14} /></button>
                </div>
              ))}
            </div>

            <div className="relative group">
              <input 
                type="file" 
                onChange={handleFileChange} 
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
              />
              <div className="border border-dashed border-nexus-muted/50 rounded p-4 flex items-center justify-center gap-2 text-nexus-muted group-hover:border-nexus-cobalt group-hover:text-nexus-cobalt transition-colors bg-nexus-bg">
                <Upload size={16} />
                <span className="text-sm">Upload de Arquivo</span>
              </div>
            </div>
          </div>

        </div>

        {/* Footer */}
        <div className="p-6 border-t border-nexus-border flex justify-between bg-nexus-bg/50">
          {task ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-4 py-2 text-sm text-red-500 hover:bg-red-900/20 rounded transition-colors"
            >
              <Trash2 size={16} /> Excluir
            </button>
          ) : <div></div>}

          <button 
            onClick={() => onSave(formData as Task)}
            className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-sm font-medium rounded transition-all shadow-lg shadow-blue-900/20"
          >
            <Save size={16} /> Salvar
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { Task, Status, User, Project } from './types';
import { STATUS_COLUMNS } from './constants';
import { Plus } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);

  // UI State
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Load Data on User Login
  useEffect(() => {
    if (user) {
      const storedProjects = JSON.parse(localStorage.getItem('luck_projects') || '[]');
      const storedTasks = JSON.parse(localStorage.getItem('luck_tasks') || '[]');

      // Filter projects: Owned by me OR Shared with me
      const myProjects = storedProjects.filter((p: Project) => 
        p.ownerId === user.id || p.sharedWith.includes(user.username)
      );

      setProjects(myProjects);
      setTasks(storedTasks);

      if (myProjects.length > 0) {
        setCurrentProjectId(myProjects[0].id);
      } else {
        // Create default project if none
        const defaultProject: Project = { id: `p-${Date.now()}`, name: 'Meu Primeiro Projeto', ownerId: user.id, sharedWith: [] };
        const newProjects = [...storedProjects, defaultProject];
        localStorage.setItem('luck_projects', JSON.stringify(newProjects));
        setProjects([defaultProject]);
        setCurrentProjectId(defaultProject.id);
      }
    }
  }, [user]);

  // Persistence Helper
  const saveProjects = (newProjects: Project[]) => {
    // We only have "my" projects in state, need to merge with others in localstorage
    const allProjects = JSON.parse(localStorage.getItem('luck_projects') || '[]');
    const otherProjects = allProjects.filter((p: Project) => p.ownerId !== user?.id && !p.sharedWith.includes(user?.username || ''));

    // Actually, simplifying: Load all, update the modified ones. 
    // Ideally we would use a real DB. For now, let's just save the full set if we modified "my" list assuming no conflict.
    // Better: Update only the specific project in the full list.

    // For "Create", simple append.
    // For "Share", update specific ID.

    // Re-read to be safe
    const currentStorage = JSON.parse(localStorage.getItem('luck_projects') || '[]');
    // Create map
    const projectMap = new Map(currentStorage.map((p: Project) => [p.id, p]));

    newProjects.forEach(p => projectMap.set(p.id, p));

    localStorage.setItem('luck_projects', JSON.stringify(Array.from(projectMap.values())));
    setProjects(newProjects);
  };

  const saveTasks = (newTasks: Task[]) => {
    localStorage.setItem('luck_tasks', JSON.stringify(newTasks));
    setTasks(newTasks);
  };

  // Handlers
  const handleCreateProject = (name: string) => {
    if (!user) return;
    const newProject: Project = {
      id: `p-${Date.now()}`,
      name,
      ownerId: user.id,
      sharedWith: []
    };
    const updatedProjects = [...projects, newProject];
    saveProjects(updatedProjects);
    setCurrentProjectId(newProject.id);
  };

  const handleShareProject = (username: string) => {
    if (!projectToShare) return;
    const updatedProject = { 
      ...projectToShare, 
      sharedWith: [...projectToShare.sharedWith, username] 
    };
    const updatedProjects = projects.map(p => p.id === updatedProject.id ? updatedProject : p);
    saveProjects(updatedProjects);
  };

  const handleSaveTask = (taskData: Task) => {
    if (selectedTask) {
      // Update
      const updatedTasks = tasks.map(t => t.id === taskData.id ? taskData : t);
      saveTasks(updatedTasks);
    } else {
      // Create
      if (!currentProjectId) return;
      const newTask: Task = {
        ...taskData,
        id: `t-${Date.now()}`,
        createdAt: new Date().toISOString(),
        projectId: currentProjectId
      };
      saveTasks([...tasks, newTask]);
    }
    setIsTaskModalOpen(false);
  };

  const handleDeleteTask = (id: string) => {
    saveTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);
  };

  // Drag and Drop
  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = (e: React.DragEvent, status: Status) => {
    const taskId = e.dataTransfer.getData('taskId');
    const task = tasks.find(t => t.id === taskId);
    if (task && task.status !== status) {
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status } : t);
      saveTasks(updatedTasks);
    }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={setUser} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        user={user}
        onLogout={() => setUser(null)}
        isDark={isDark}
        toggleTheme={toggleTheme}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <MetricsHeader tasks={contextTasks} project={currentProject} />

        <main className="flex-1 overflow-x-auto overflow-y-hidden p-6">
           {currentProjectId ? (
             <div className="flex h-full gap-4 min-w-[1000px]">
                {STATUS_COLUMNS.map(col => {
                  const colTasks = contextTasks.filter(t => t.status === col.id);
                  return (
                    <div 
                      key={col.id} 
                      className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                      onDragOver={onDragOver}
                      onDrop={(e) => onDrop(e, col.id)}
                    >
                      <div className="flex items-center justify-between mb-4 pb-2 border-b border-nexus-border px-1">
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                            {col.label}
                          </span>
                          <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                            {colTasks.length}
                          </span>
                        </div>
                        <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                      </div>

                      <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-20">
                        {colTasks.length > 0 ? (
                          colTasks.map(task => (
                            <TaskCard 
                              key={task.id} 
                              task={task} 
                              onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                              onDelete={handleDeleteTask} 
                            />
                          ))
                        ) : (
                          <div className="h-24 border border-dashed border-nexus-border rounded flex items-center justify-center text-nexus-muted text-xs italic opacity-50">
                            Arraste itens aqui
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">Selecione ou crie um projeto.</div>
           )}
        </main>

        {currentProjectId && (
          <button 
            onClick={() => { setSelectedTask(null); setIsTaskModalOpen(true); }}
            className="absolute bottom-8 right-8 h-14 w-14 bg-nexus-accent hover:bg-amber-400 text-black rounded-full shadow-[0_4px_20px_rgba(234,179,8,0.4)] flex items-center justify-center transition-all duration-300 hover:scale-105 z-30"
          >
            <Plus size={28} strokeWidth={2.5} />
          </button>
        )}
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
      />
    </div>
  );
};

export default App;

export interface User {
  id: string;
  username: string;
}

export interface Project {
  id: string;
  name: string;
  ownerId: string;
  sharedWith: string[]; // List of usernames
}

export type Priority = 'Low' | 'Medium' | 'High';

export type Status = 'backlog' | 'todo' | 'inprogress' | 'review' | 'done';

export interface Attachment {
  id: string;
  name: string;
  type: string; // 'image', 'pdf', 'other'
  url: string;
  size?: string;
}

export interface Tag {
  text: string;
  color: string;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  // Client/Project Specifics (Backlog Intake)
  clientName?: string;
  objective?: string;
  websiteUrl?: string;

  projectId: string; 
  status: Status;
  priority: Priority;
  progress: number; // 0-100
  tags: Tag[]; // Updated from string[]
  attachments: Attachment[];
  dueDate?: string;
  assignee?: string;
  createdAt: string;
}

export interface Metric {
  label: string;
  value: string | number;
  trend: 'up' | 'down' | 'neutral';
  trendValue: string;
}

import React from 'react';
import { Task, Priority } from '../types';
import { Paperclip, MoreHorizontal, Globe } from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
}

const PriorityBadge: React.FC<{ priority: Priority }> = ({ priority }) => {
  const colors = {
    Low: 'bg-neutral-200 text-neutral-600 border-neutral-300 dark:bg-neutral-800 dark:text-neutral-400 dark:border-neutral-700',
    Medium: 'bg-blue-100 text-blue-600 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/30',
    High: 'bg-amber-100 text-amber-600 border-amber-200 dark:bg-amber-900/20 dark:text-amber-500 dark:border-amber-900/30',
  };

  return (
    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider font-bold ${colors[priority]}`}>
      {priority === 'Low' ? 'Baixa' : priority === 'Medium' ? 'Média' : 'Alta'}
    </span>
  );
};

export const TaskCard: React.FC<TaskCardProps> = ({ task, onEdit }) => {
  // Determine border color based on priority
  const borderLeftColor = 
    task.priority === 'High' ? 'border-l-nexus-accent' : 
    task.priority === 'Medium' ? 'border-l-nexus-cobalt' : 'border-l-gray-400 dark:border-l-neutral-600';

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('taskId', task.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  return (
    <div 
      draggable
      onDragStart={handleDragStart}
      onClick={() => onEdit(task)}
      className={`
        group relative bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt/50 transition-all duration-200 cursor-grab active:cursor-grabbing overflow-hidden
        border-l-[3px] ${borderLeftColor} p-3 mb-3 shadow-sm hover:shadow-md
      `}
    >
      <div className="flex justify-between items-start mb-2">
        <PriorityBadge priority={task.priority} />
        {task.progress === 100 && <div className="h-1.5 w-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
      </div>

      <h3 className="text-sm font-medium text-nexus-text leading-tight mb-2 line-clamp-2 group-hover:text-nexus-cobalt transition-colors">
        {task.title}
      </h3>

      {task.clientName && (
        <p className="text-[10px] text-nexus-muted mb-2 font-mono uppercase tracking-wider">
          {task.clientName}
        </p>
      )}

      <div className="flex items-center gap-2 mb-3 flex-wrap">
        {task.tags.slice(0, 4).map((tag, i) => (
          <span 
            key={i} 
            className="text-[10px] px-1.5 py-0.5 rounded font-medium border border-transparent"
            style={{ 
              backgroundColor: `${tag.color}20`, // 20% opacity
              color: tag.color,
              borderColor: `${tag.color}40`
            }}
          >
            #{tag.text}
          </span>
        ))}
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-nexus-bg h-1 rounded-full overflow-hidden mb-3">
        <div 
          className={`h-full transition-all duration-500 ${task.priority === 'High' ? 'bg-nexus-accent' : 'bg-nexus-cobalt'}`} 
          style={{ width: `${task.progress}%` }}
        ></div>
      </div>

      <div className="flex justify-between items-center text-nexus-muted">
        <div className="flex items-center gap-3">
          {task.attachments.length > 0 && (
            <div className="flex items-center gap-1 text-[10px]">
              <Paperclip size={10} />
              <span>{task.attachments.length}</span>
            </div>
          )}
          {task.websiteUrl && (
             <Globe size={10} />
          )}
        </div>

        <div className="opacity-0 group-hover:opacity-100 transition-opacity">
            <MoreHorizontal size={14} />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target } from 'lucide-react';
import { STATUS_COLUMNS } from '../constants';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ task, isOpen, onClose, onSave, onDelete, currentProjectId }) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
  });
  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); // Default Blue

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        projectId: currentProjectId,
      });
    }
  }, [task, isOpen, currentProjectId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  const addTag = () => {
    if (tagInput.trim()) {
      const newTag: Tag = { text: tagInput.trim(), color: selectedTagColor };
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), newTag]
      }));
      setTagInput('');
    }
  };

  const removeTag = (textToRemove: string) => {
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[700px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col max-h-[95vh]">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-nexus-border">
          <div className="flex flex-col">
            <h2 className="text-lg font-bold text-nexus-text font-mono tracking-tight">
              {task ? 'EDITAR ITEM' : 'NOVO ITEM DE PROJETO'}
            </h2>
            <span className="text-xs text-nexus-muted">Preencha os detalhes do backlog ou da tarefa</span>
          </div>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">

          {/* Main Info */}
          <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Título do Projeto / Tarefa</label>
                <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-lg font-medium text-nexus-text focus:border-nexus-cobalt outline-none transition-colors"
                  placeholder="Ex: Redesign E-commerce..."
                />
              </div>

              {/* Client Intake Section - highlighted with subtle bg */}
              <div className="bg-nexus-bg/50 border border-nexus-border rounded-lg p-4 space-y-4">
                  <div className="flex items-center gap-2 mb-2">
                      <Briefcase size={14} className="text-nexus-accent" />
                      <h3 className="text-xs font-bold uppercase text-nexus-accent tracking-wider">Informações do Cliente (Backlog)</h3>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                        <label className="text-xs text-nexus-muted">Nome do Cliente</label>
                        <input 
                            type="text" 
                            value={formData.clientName} 
                            onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-accent outline-none text-sm"
                            placeholder="Nome da empresa ou cliente"
                        />
                      </div>
                      <div className="space-y-1">
                        <label className="text-xs text-nexus-muted">Website / Link</label>
                        <div className="relative">
                            <Globe size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                            <input 
                                type="text" 
                                value={formData.websiteUrl} 
                                onChange={(e) => setFormData({...formData, websiteUrl: e.target.value})}
                                className="w-full pl-8 bg-nexus-card border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-accent outline-none text-sm"
                                placeholder="https://..."
                            />
                        </div>
                      </div>
                  </div>

                  <div className="space-y-1">
                    <label className="text-xs text-nexus-muted">Objetivo Principal</label>
                    <div className="relative">
                        <Target size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                        <input 
                            type="text" 
                            value={formData.objective} 
                            onChange={(e) => setFormData({...formData, objective: e.target.value})}
                            className="w-full pl-8 bg-nexus-card border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-accent outline-none text-sm"
                            placeholder="Qual o objetivo principal deste projeto?"
                        />
                    </div>
                  </div>
              </div>

              <div className="space-y-1">
                <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Detalhes & Observações</label>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={5}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none"
                  placeholder="Descreva todos os detalhes necessários para a execução..."
                />
              </div>
          </div>

          <hr className="border-nexus-border" />

          {/* Settings Row */}
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Status</label>
              <select 
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
              >
                {STATUS_COLUMNS.map(col => (
                  <option key={col.id} value={col.id}>{col.label}</option>
                ))}
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Prioridade</label>
              <select 
                value={formData.priority}
                onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                className="w-full bg-nexus-bg border border-nexus-border rounded p-2 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
              >
                <option value="Low">Baixa</option>
                <option value="Medium">Média</option>
                <option value="High">Alta</option>
              </select>
            </div>

            <div className="space-y-1">
              <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Progresso ({formData.progress}%)</label>
              <input 
                type="range" 
                min="0" 
                max="100" 
                value={formData.progress}
                onChange={(e) => setFormData({...formData, progress: parseInt(e.target.value)})}
                className="w-full h-2 bg-nexus-bg rounded-lg appearance-none cursor-pointer accent-nexus-cobalt mt-3 border border-nexus-border"
              />
            </div>
          </div>

          {/* Tags with Color Picker */}
          <div className="space-y-2">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold">Tags Coloridas</label>
            <div className="flex gap-2 mb-2 flex-wrap">
              {formData.tags?.map((tag, idx) => (
                <span 
                    key={idx} 
                    className="text-xs px-2 py-1 rounded border flex items-center gap-1 font-medium"
                    style={{ backgroundColor: `${tag.color}20`, borderColor: tag.color, color: tag.color }}
                >
                  #{tag.text}
                  <button onClick={() => removeTag(tag.text)} className="hover:opacity-70"><X size={10} /></button>
                </span>
              ))}
            </div>

            <div className="flex gap-3 items-center bg-nexus-bg p-2 rounded border border-nexus-border">
                <div className="relative flex-1">
                    <TagIcon size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                    <input 
                    type="text" 
                    value={tagInput}
                    onChange={(e) => setTagInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && addTag()}
                    className="w-full pl-8 bg-transparent border-none text-nexus-text focus:ring-0 outline-none text-sm h-8"
                    placeholder="Nova tag..."
                    />
                </div>
                <div className="flex gap-1">
                    {TAG_COLORS.map(color => (
                        <button
                            key={color}
                            onClick={() => setSelectedTagColor(color)}
                            className={`w-4 h-4 rounded-full transition-transform hover:scale-110 ${selectedTagColor === color ? 'ring-2 ring-white scale-110' : 'opacity-70'}`}
                            style={{ backgroundColor: color }}
                        />
                    ))}
                </div>
                <button 
                    onClick={addTag} 
                    className="p-1.5 bg-nexus-card hover:bg-nexus-border rounded text-nexus-text transition-colors"
                >
                    <Save size={14} />
                </button>
            </div>
          </div>

          {/* Attachments */}
          <div className="space-y-1">
            <label className="text-xs uppercase tracking-wider text-nexus-muted font-bold flex justify-between">
              <span>Arquivos do Projeto</span>
              <span className="text-[10px] font-normal lowercase opacity-70">PDF, Imagens, Docs</span>
            </label>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {formData.attachments?.map(att => (
                <div key={att.id} className="flex items-center gap-3 p-2 bg-nexus-bg border border-nexus-border rounded">
                  {att.type === 'image' ? (
                     <img src={att.url} alt="prev" className="w-8 h-8 object-cover rounded" />
                  ) : (
                    <div className="w-8 h-8 bg-nexus-border flex items-center justify-center rounded text-nexus-text"><FileText size={14} /></div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs truncate text-nexus-text">{att.name}</p>
                    <a href={att.url} target="_blank" rel="noreferrer" className="text-[10px] text-nexus-cobalt hover:underline">Ver arquivo</a>
                  </div>
                  <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500"><X size={14} /></button>
                </div>
              ))}
            </div>

            <div className="relative group">
              <input 
                type="file" 
                onChange={handleFileChange} 
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
              />
              <div className="border border-dashed border-nexus-muted/50 rounded p-4 flex items-center justify-center gap-2 text-nexus-muted group-hover:border-nexus-cobalt group-hover:text-nexus-cobalt transition-colors bg-nexus-bg">
                <Upload size={16} />
                <span className="text-sm">Arraste ou clique para adicionar arquivos</span>
              </div>
            </div>
          </div>

        </div>

        {/* Footer */}
        <div className="p-6 border-t border-nexus-border flex justify-between bg-nexus-bg/50">
          {task ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-4 py-2 text-sm text-red-500 hover:bg-red-900/20 rounded transition-colors"
            >
              <Trash2 size={16} /> Excluir
            </button>
          ) : <div></div>}

          <button 
            onClick={() => onSave(formData as Task)}
            className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-sm font-medium rounded transition-all shadow-lg shadow-blue-900/20"
          >
            <Save size={16} /> Salvar Alterações
          </button>
        </div>
      </div>
    </div>
  );
};

