import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS } from './constants';
import { Plus } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);

  // UI State
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Load Data on User Login
  useEffect(() => {
    if (user) {
      const storedProjects = JSON.parse(localStorage.getItem('luck_projects') || '[]');
      const storedTasks = JSON.parse(localStorage.getItem('luck_tasks') || '[]');

      // Data Migration: Ensure tags are objects
      const migratedTasks = storedTasks.map((t: any) => {
         if (t.tags && t.tags.length > 0 && typeof t.tags[0] === 'string') {
             return {
                 ...t,
                 tags: t.tags.map((txt: string) => ({ text: txt, color: '#3b82f6' }))
             }
         }
         return t;
      });

      // Filter projects: Owned by me OR Shared with me
      const myProjects = storedProjects.filter((p: Project) => 
        p.ownerId === user.id || p.sharedWith.includes(user.username)
      );

      setProjects(myProjects);
      setTasks(migratedTasks);

      if (myProjects.length > 0) {
        setCurrentProjectId(myProjects[0].id);
      } else {
        // Create default project if none
        const defaultProject: Project = { id: `p-${Date.now()}`, name: 'Meu Primeiro Projeto', ownerId: user.id, sharedWith: [] };
        const newProjects = [...storedProjects, defaultProject];
        localStorage.setItem('luck_projects', JSON.stringify(newProjects));
        setProjects([defaultProject]);
        setCurrentProjectId(defaultProject.id);
      }
    }
  }, [user]);

  // Persistence Helper
  const saveProjects = (newProjects: Project[]) => {
    const currentStorage = JSON.parse(localStorage.getItem('luck_projects') || '[]');
    const projectMap = new Map(currentStorage.map((p: Project) => [p.id, p]));
    newProjects.forEach(p => projectMap.set(p.id, p));
    localStorage.setItem('luck_projects', JSON.stringify(Array.from(projectMap.values())));
    setProjects(newProjects);
  };

  const saveTasks = (newTasks: Task[]) => {
    localStorage.setItem('luck_tasks', JSON.stringify(newTasks));
    setTasks(newTasks);
  };

  // Handlers
  const handleCreateProject = (name: string) => {
    if (!user) return;
    const newProject: Project = {
      id: `p-${Date.now()}`,
      name,
      ownerId: user.id,
      sharedWith: []
    };
    const updatedProjects = [...projects, newProject];
    saveProjects(updatedProjects);
    setCurrentProjectId(newProject.id);
    setCurrentView('board');
  };

  const handleShareProject = (username: string) => {
    if (!projectToShare) return;
    const updatedProject = { 
      ...projectToShare, 
      sharedWith: [...projectToShare.sharedWith, username] 
    };
    const updatedProjects = projects.map(p => p.id === updatedProject.id ? updatedProject : p);
    saveProjects(updatedProjects);
  };

  const handleSaveTask = (taskData: Task) => {
    if (selectedTask) {
      // Update
      const updatedTasks = tasks.map(t => t.id === taskData.id ? taskData : t);
      saveTasks(updatedTasks);
    } else {
      // Create
      if (!currentProjectId) return;
      const newTask: Task = {
        ...taskData,
        id: `t-${Date.now()}`,
        createdAt: new Date().toISOString(),
        projectId: currentProjectId
      };
      saveTasks([...tasks, newTask]);
    }
    setIsTaskModalOpen(false);
  };

  const handleDeleteTask = (id: string) => {
    saveTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);
  };

  // Drag and Drop
  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = (e: React.DragEvent, status: Status) => {
    const taskId = e.dataTransfer.getData('taskId');
    const task = tasks.find(t => t.id === taskId);
    if (task && task.status !== status) {
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status } : t);
      saveTasks(updatedTasks);
    }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={setUser} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        user={user}
        onLogout={() => setUser(null)}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0">

        {/* Only show Metrics Header in Board View */}
        {currentView === 'board' && <MetricsHeader tasks={contextTasks} project={currentProject} />}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard tasks={contextTasks} project={currentProject} />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS.map(col => {
                    const colTasks = contextTasks.filter(t => t.status === col.id);
                    return (
                        <div 
                        key={col.id} 
                        className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                        onDragOver={onDragOver}
                        onDrop={(e) => onDrop(e, col.id)}
                        >
                        <div className="flex items-center justify-between mb-4 pb-2 border-b border-nexus-border px-1 group">
                            <div className="flex items-center gap-2">
                            <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                {col.label}
                            </span>
                            <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                {colTasks.length}
                            </span>
                            </div>

                            {/* Special Quick Add for Backlog */}
                            {col.id === 'backlog' && (
                                <button 
                                    onClick={() => { setSelectedTask(null); setIsTaskModalOpen(true); }}
                                    className="text-nexus-muted hover:text-nexus-accent transition-colors"
                                    title="Adicionar ao Backlog"
                                >
                                    <Plus size={16} />
                                </button>
                            )}
                            {col.id !== 'backlog' && <div className="h-1 w-1 rounded-full bg-nexus-border"></div>}
                        </div>

                        <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar pb-20">
                            {colTasks.length > 0 ? (
                            colTasks.map(task => (
                                <TaskCard 
                                key={task.id} 
                                task={task} 
                                onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                onDelete={handleDeleteTask} 
                                />
                            ))
                            ) : (
                            <div 
                                onClick={() => { if(col.id === 'backlog') { setSelectedTask(null); setIsTaskModalOpen(true); } }}
                                className={`h-24 border border-dashed border-nexus-border rounded flex flex-col items-center justify-center text-nexus-muted text-xs italic opacity-50 transition-all ${col.id === 'backlog' ? 'cursor-pointer hover:bg-nexus-card hover:border-nexus-accent hover:text-nexus-accent' : ''}`}
                            >
                                {col.id === 'backlog' ? <><Plus size={18} className="mb-1"/>Adicionar Item</> : 'Arraste itens aqui'}
                            </div>
                            )}
                        </div>
                        </div>
                    );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">Selecione ou crie um projeto.</div>
           )}
        </main>

        {currentProjectId && currentView === 'board' && (
          <button 
            onClick={() => { setSelectedTask(null); setIsTaskModalOpen(true); }}
            className="absolute bottom-8 right-8 h-14 w-14 bg-nexus-accent hover:bg-amber-400 text-black rounded-full shadow-[0_4px_20px_rgba(234,179,8,0.4)] flex items-center justify-center transition-all duration-300 hover:scale-105 z-30"
          >
            <Plus size={28} strokeWidth={2.5} />
          </button>
        )}
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
      />
    </div>
  );
};

export default App;

export interface User {
  id: string;
  username: string;
}

export interface Project {
  id: string;
  name: string;
  ownerId: string;
  sharedWith: string[]; // List of usernames
}

export type Priority = 'Low' | 'Medium' | 'High';

export type Status = 'backlog' | 'todo' | 'inprogress' | 'review' | 'done';

export interface Attachment {
  id: string;
  name: string;
  type: string; // 'image', 'pdf', 'other'
  url: string;
  size?: string;
}

export interface Tag {
  text: string;
  color: string;
}

export interface ChecklistItem {
  id: string;
  text: string;
  checked: boolean;
}

export interface Task {
  id: string;
  title: string;
  description: string;
  // Client/Project Specifics (Backlog Intake)
  clientName?: string;
  objective?: string;
  websiteUrl?: string;

  projectId: string; 
  status: Status;
  priority: Priority;
  progress: number; // 0-100
  tags: Tag[]; 
  attachments: Attachment[];
  checklist: ChecklistItem[]; // New
  dueDate?: string;
  assignee?: string; // Username of member
  createdAt: string;
}

export interface Metric {
  label: string;
  value: string | number;
  trend: 'up' | 'down' | 'neutral';
  trendValue: string;
}

import React, { useState } from 'react';
import { LayoutGrid, Folder, Plus, Activity, Sun, Moon, LogOut, Share2, GripVertical, User as UserIcon, Users } from 'lucide-react';
import { Project, User } from '../types';

interface SidebarProps {
  projects: Project[];
  currentProjectId: string | null;
  setProjectId: (id: string) => void;
  onNewProject: () => void;
  onShareProject: (project: Project) => void;
  onReorderProjects: (projects: Project[]) => void;
  user: User;
  onLogout: () => void;
  isDark: boolean;
  toggleTheme: () => void;
  currentView: 'board' | 'monitoring';
  setView: (view: 'board' | 'monitoring') => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  projects, 
  currentProjectId, 
  setProjectId, 
  onNewProject,
  onShareProject,
  onReorderProjects,
  user,
  onLogout,
  isDark,
  toggleTheme,
  currentView,
  setView
}) => {
  const [draggedProject, setDraggedProject] = useState<Project | null>(null);

  // Group Projects
  const myProjects = projects.filter(p => p.ownerId === user.id);
  const sharedProjects = projects.filter(p => p.ownerId !== user.id);

  const handleDragStart = (e: React.DragEvent, project: Project) => {
    setDraggedProject(project);
    e.dataTransfer.effectAllowed = 'move';
    // Only allow reordering within "My Projects" for now to simplify
    if (project.ownerId !== user.id) {
       e.preventDefault();
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, targetProject: Project) => {
    e.preventDefault();
    if (!draggedProject || draggedProject.id === targetProject.id) return;

    // Simple reorder logic for "My Projects"
    if (draggedProject.ownerId === user.id && targetProject.ownerId === user.id) {
        const newOrder = [...projects];
        const draggedIdx = newOrder.findIndex(p => p.id === draggedProject.id);
        const targetIdx = newOrder.findIndex(p => p.id === targetProject.id);

        // Remove and insert
        newOrder.splice(draggedIdx, 1);
        newOrder.splice(targetIdx, 0, draggedProject);

        onReorderProjects(newOrder);
    }
    setDraggedProject(null);
  };

  const renderProjectItem = (item: Project, isShared: boolean) => (
    <div 
        key={item.id} 
        className={`group relative flex items-center ${!isShared ? 'cursor-grab active:cursor-grabbing' : ''}`}
        draggable={!isShared}
        onDragStart={(e) => handleDragStart(e, item)}
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, item)}
    >
      {!isShared && (
        <div className="absolute left-1 opacity-0 group-hover:opacity-100 text-nexus-muted cursor-grab">
            <GripVertical size={12} />
        </div>
      )}
      <button
        onClick={() => { setProjectId(item.id); setView('board'); }}
        className={`flex-1 flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all duration-200 ml-2 ${
          currentProjectId === item.id && currentView === 'board'
            ? 'bg-nexus-card text-nexus-cobalt border-l-2 border-nexus-cobalt shadow-sm'
            : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
        }`}
      >
        <Folder size={16} className={`${currentProjectId === item.id && currentView === 'board' ? 'text-nexus-cobalt' : 'text-nexus-muted'}`} />
        <span className="truncate max-w-[140px]">{item.name}</span>
        {isShared && (
            <span className="text-[9px] bg-nexus-border px-1 rounded text-nexus-muted ml-auto">
                Shared
            </span>
        )}
      </button>
      {item.ownerId === user.id && (
        <button 
          onClick={(e) => { e.stopPropagation(); onShareProject(item); }}
          className="absolute right-2 opacity-0 group-hover:opacity-100 p-1 text-nexus-muted hover:text-nexus-text"
          title="Compartilhar Projeto"
        >
          <Share2 size={12} />
        </button>
      )}
    </div>
  );

  return (
    <aside className="w-64 h-screen bg-nexus-bg border-r border-nexus-border flex flex-col flex-shrink-0 z-20 transition-colors duration-300">
      <div className="h-16 flex items-center px-6 border-b border-nexus-border">
        <div 
            onClick={() => setView('board')}
            className="flex items-center gap-2 text-nexus-text font-bold tracking-tight cursor-pointer hover:opacity-80 transition-opacity"
        >
          <div className="w-6 h-6 bg-nexus-cobalt rounded-sm flex items-center justify-center">
             <LayoutGrid size={14} className="text-white" />
          </div>
          <span className="font-mono">LUCK_OS</span>
        </div>
      </div>

      <div className="flex-1 py-6 px-3 space-y-4 overflow-y-auto">

        {/* New Project Button */}
        <button 
            onClick={onNewProject} 
            className="w-full flex items-center justify-center gap-2 py-2 border border-dashed border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors"
        >
            <Plus size={14} /> Novo Projeto
        </button>

        {/* My Projects Section */}
        <div>
            <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                <UserIcon size={12} />
                <span>Meus Projetos</span>
            </div>
            <div className="space-y-0.5">
                {myProjects.length > 0 ? (
                    myProjects.map(p => renderProjectItem(p, false))
                ) : (
                    <div className="px-5 py-2 text-xs text-nexus-muted italic opacity-50">Vazio</div>
                )}
            </div>
        </div>

        {/* Shared Projects Section */}
        {sharedProjects.length > 0 && (
            <div>
                <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                    <Users size={12} />
                    <span>Compartilhados</span>
                </div>
                <div className="space-y-0.5">
                    {sharedProjects.map(p => renderProjectItem(p, true))}
                </div>
            </div>
        )}

        <div className="pt-4 mt-4 border-t border-nexus-border/50">
            <div className="px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">SISTEMA</div>
            <button 
                onClick={() => setView('monitoring')}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${
                    currentView === 'monitoring' 
                    ? 'bg-nexus-card text-nexus-accent border-l-2 border-nexus-accent' 
                    : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
                }`}
            >
            <Activity size={18} />
            <span>Monitoramento</span>
            </button>
        </div>
      </div>

      <div className="p-4 border-t border-nexus-border space-y-4">
        <div className="flex items-center justify-between px-2">
           <span className="text-xs text-nexus-muted font-medium">Tema</span>
           <button 
             onClick={toggleTheme}
             className="p-2 rounded-full bg-nexus-card hover:bg-nexus-hover text-nexus-text border border-nexus-border transition-colors"
           >
             {isDark ? <Sun size={14} /> : <Moon size={14} />}
           </button>
        </div>

        <div className="flex items-center gap-3 px-2 pt-2 border-t border-nexus-border">
          <div className="w-8 h-8 rounded bg-gradient-to-br from-nexus-cobalt to-purple-600 flex items-center justify-center text-xs font-bold text-white uppercase">
            {user.username.substring(0, 2)}
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            <span className="text-xs font-medium text-nexus-text truncate">{user.username}</span>
            <span className="text-[10px] text-nexus-muted font-mono">Online</span>
          </div>
          <button onClick={onLogout} className="text-nexus-muted hover:text-red-500 transition-colors">
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </aside>
  );
};

import React from 'react';
import { Task, Priority } from '../types';
import { Paperclip, MoreHorizontal, Globe, CheckSquare, UserCircle } from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
}

const PriorityBadge: React.FC<{ priority: Priority }> = ({ priority }) => {
  const colors = {
    Low: 'bg-neutral-200 text-neutral-600 border-neutral-300 dark:bg-neutral-800 dark:text-neutral-400 dark:border-neutral-700',
    Medium: 'bg-blue-100 text-blue-600 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/30',
    High: 'bg-amber-100 text-amber-600 border-amber-200 dark:bg-amber-900/20 dark:text-amber-500 dark:border-amber-900/30',
  };

  return (
    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider font-bold ${colors[priority]}`}>
      {priority === 'Low' ? 'Baixa' : priority === 'Medium' ? 'Média' : 'Alta'}
    </span>
  );
};

export const TaskCard: React.FC<TaskCardProps> = ({ task, onEdit }) => {
  // Determine border color based on priority
  const borderLeftColor = 
    task.priority === 'High' ? 'border-l-nexus-accent' : 
    task.priority === 'Medium' ? 'border-l-nexus-cobalt' : 'border-l-gray-400 dark:border-l-neutral-600';

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('taskId', task.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const checklistTotal = task.checklist ? task.checklist.length : 0;
  const checklistDone = task.checklist ? task.checklist.filter(i => i.checked).length : 0;

  return (
    <div 
      draggable
      onDragStart={handleDragStart}
      onClick={() => onEdit(task)}
      className={`
        group relative bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt/50 transition-all duration-200 cursor-grab active:cursor-grabbing overflow-hidden
        border-l-[3px] ${borderLeftColor} p-3 mb-3 shadow-sm hover:shadow-md
      `}
    >
      <div className="flex justify-between items-start mb-2">
        <PriorityBadge priority={task.priority} />
        {task.progress === 100 && <div className="h-1.5 w-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
      </div>

      <h3 className="text-sm font-medium text-nexus-text leading-tight mb-2 line-clamp-2 group-hover:text-nexus-cobalt transition-colors">
        {task.title}
      </h3>

      {task.clientName && (
        <p className="text-[10px] text-nexus-muted mb-2 font-mono uppercase tracking-wider">
          {task.clientName}
        </p>
      )}

      {task.tags && task.tags.length > 0 && (
        <div className="flex items-center gap-2 mb-3 flex-wrap">
            {task.tags.slice(0, 4).map((tag, i) => (
            <span 
                key={i} 
                className="text-[10px] px-1.5 py-0.5 rounded font-medium border border-transparent"
                style={{ 
                backgroundColor: `${tag.color}20`, // 20% opacity
                color: tag.color,
                borderColor: `${tag.color}40`
                }}
            >
                #{tag.text}
            </span>
            ))}
        </div>
      )}

      {/* Progress Bar */}
      {task.progress > 0 && (
        <div className="w-full bg-nexus-bg h-1 rounded-full overflow-hidden mb-3">
            <div 
            className={`h-full transition-all duration-500 ${task.priority === 'High' ? 'bg-nexus-accent' : 'bg-nexus-cobalt'}`} 
            style={{ width: `${task.progress}%` }}
            ></div>
        </div>
      )}

      <div className="flex justify-between items-center text-nexus-muted">
        <div className="flex items-center gap-3 text-[10px]">
          {task.attachments && task.attachments.length > 0 && (
            <div className="flex items-center gap-1">
              <Paperclip size={10} />
              <span>{task.attachments.length}</span>
            </div>
          )}
          {checklistTotal > 0 && (
             <div className={`flex items-center gap-1 ${checklistDone === checklistTotal ? 'text-green-500' : ''}`}>
               <CheckSquare size={10} />
               <span>{checklistDone}/{checklistTotal}</span>
             </div>
          )}
          {task.websiteUrl && (
             <Globe size={10} />
          )}
        </div>

        {task.assignee ? (
             <div className="flex items-center gap-1 bg-nexus-bg border border-nexus-border px-1.5 py-0.5 rounded-full" title={`Responsável: ${task.assignee}`}>
                <div className="w-3 h-3 rounded-full bg-nexus-cobalt flex items-center justify-center text-[8px] text-white">
                    {task.assignee.substring(0,1).toUpperCase()}
                </div>
                <span className="text-[9px] max-w-[50px] truncate">{task.assignee}</span>
             </div>
        ) : (
            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                <MoreHorizontal size={14} />
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag, ChecklistItem } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target, Calendar, CheckSquare, User, Plus } from 'lucide-react';
import { STATUS_COLUMNS } from '../constants';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ task, isOpen, onClose, onSave, onDelete, currentProjectId }) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
    checklist: [],
    dueDate: '',
    assignee: ''
  });

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); 
  const [checklistInput, setChecklistInput] = useState('');

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        dueDate: '',
        assignee: '',
        projectId: currentProjectId,
      });
    }
  }, [task, isOpen, currentProjectId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  const addTag = () => {
    if (tagInput.trim()) {
      const newTag: Tag = { text: tagInput.trim(), color: selectedTagColor };
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), newTag]
      }));
      setTagInput('');
    }
  };

  const removeTag = (textToRemove: string) => {
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  const addChecklistItem = () => {
      if (checklistInput.trim()) {
          const newItem: ChecklistItem = {
              id: Date.now().toString(),
              text: checklistInput.trim(),
              checked: false
          };
          setFormData(prev => ({
              ...prev,
              checklist: [...(prev.checklist || []), newItem]
          }));
          setChecklistInput('');
      }
  };

  const toggleChecklistItem = (id: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
          )
      }));
  };

  const deleteChecklistItem = (id: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[800px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col max-h-[95vh] text-nexus-text">

        {/* Header */}
        <div className="flex justify-between items-start p-6 border-b border-nexus-border bg-nexus-bg/50">
          <div className="flex-1 mr-4">
             <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-transparent border-none text-xl font-bold text-nexus-text focus:ring-0 outline-none p-0 placeholder-nexus-muted"
                  placeholder="Nome do Cartão..."
            />
            <div className="text-xs text-nexus-muted mt-1 flex gap-2">
                <span>em lista <strong>{STATUS_COLUMNS.find(c => c.id === formData.status)?.label}</strong></span>
            </div>
          </div>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Content - Two Column Layout */}
        <div className="flex-1 overflow-y-auto p-6 flex gap-6 custom-scrollbar">

          {/* LEFT COLUMN (Main Content) */}
          <div className="flex-1 space-y-6">

              {/* Description */}
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-sm font-bold text-nexus-text">
                    <FileText size={16} />
                    <h3>Descrição</h3>
                </div>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={4}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none"
                  placeholder="Adicionar descrição detalhada..."
                />
              </div>

              {/* Checklist */}
              <div className="space-y-2">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text">
                      <CheckSquare size={16} />
                      <h3>Checklist</h3>
                  </div>

                  {/* Progress Bar */}
                  {formData.checklist && formData.checklist.length > 0 && (
                      <div className="flex items-center gap-2 mb-2">
                          <span className="text-xs text-nexus-muted">
                              {Math.round((formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100)}%
                          </span>
                          <div className="flex-1 h-1.5 bg-nexus-bg rounded-full overflow-hidden">
                              <div 
                                className="h-full bg-nexus-cobalt transition-all" 
                                style={{ width: `${(formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100}%` }}
                              ></div>
                          </div>
                      </div>
                  )}

                  <div className="space-y-2">
                      {formData.checklist?.map(item => (
                          <div key={item.id} className="flex items-center gap-2 group">
                              <input 
                                type="checkbox" 
                                checked={item.checked} 
                                onChange={() => toggleChecklistItem(item.id)}
                                className="w-4 h-4 rounded border-nexus-border bg-nexus-bg checked:bg-nexus-cobalt"
                              />
                              <span className={`flex-1 text-sm ${item.checked ? 'line-through text-nexus-muted' : ''}`}>{item.text}</span>
                              <button onClick={() => deleteChecklistItem(item.id)} className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-red-500">
                                  <X size={14} />
                              </button>
                          </div>
                      ))}
                      <div className="flex gap-2">
                          <input 
                            type="text" 
                            value={checklistInput}
                            onChange={(e) => setChecklistInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && addChecklistItem()}
                            className="flex-1 bg-nexus-bg border border-nexus-border rounded px-3 py-1.5 text-sm outline-none focus:border-nexus-cobalt"
                            placeholder="Adicionar item..."
                          />
                          <button onClick={addChecklistItem} className="bg-nexus-bg hover:bg-nexus-border border border-nexus-border rounded px-3 py-1 text-xs">Adicionar</button>
                      </div>
                  </div>
              </div>

               {/* Attachments */}
               <div className="space-y-2">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text">
                      <FileText size={16} />
                      <h3>Anexos</h3>
                  </div>
                  <div className="grid grid-cols-2 gap-3 mb-2">
                    {formData.attachments?.map(att => (
                        <div key={att.id} className="flex items-center gap-3 p-2 bg-nexus-bg border border-nexus-border rounded">
                        {att.type === 'image' ? (
                            <img src={att.url} alt="prev" className="w-8 h-8 object-cover rounded" />
                        ) : (
                            <div className="w-8 h-8 bg-nexus-border flex items-center justify-center rounded text-nexus-text"><FileText size={14} /></div>
                        )}
                        <div className="flex-1 min-w-0">
                            <p className="text-xs truncate text-nexus-text">{att.name}</p>
                            <a href={att.url} target="_blank" rel="noreferrer" className="text-[10px] text-nexus-cobalt hover:underline">Abrir</a>
                        </div>
                        <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500"><X size={14} /></button>
                        </div>
                    ))}
                  </div>
                   <div className="relative group">
                    <input 
                        type="file" 
                        onChange={handleFileChange} 
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                    />
                    <button className="text-sm text-nexus-muted bg-nexus-bg hover:bg-nexus-border px-3 py-2 rounded w-full border border-nexus-border border-dashed transition-colors">
                        Adicionar anexo
                    </button>
                   </div>
               </div>

               {/* Client Info (Collapsible or Block) */}
               {formData.status === 'backlog' && (
                   <div className="bg-nexus-bg/30 border border-nexus-border rounded p-4 space-y-3">
                       <h4 className="text-xs font-bold uppercase text-nexus-muted tracking-wider flex items-center gap-2">
                           <Briefcase size={12} /> Dados do Cliente (Backlog)
                       </h4>
                       <div className="grid grid-cols-2 gap-3">
                           <input 
                                type="text" 
                                value={formData.clientName} 
                                onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                                className="bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                                placeholder="Nome do Cliente"
                            />
                            <input 
                                type="text" 
                                value={formData.websiteUrl} 
                                onChange={(e) => setFormData({...formData, websiteUrl: e.target.value})}
                                className="bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                                placeholder="Website URL"
                            />
                       </div>
                       <input 
                            type="text" 
                            value={formData.objective} 
                            onChange={(e) => setFormData({...formData, objective: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                            placeholder="Objetivo Principal"
                        />
                   </div>
               )}

          </div>

          {/* RIGHT COLUMN (Sidebar Actions - Trello Style) */}
          <div className="w-48 space-y-4">
              <div className="text-xs font-bold text-nexus-muted uppercase mb-2">Adicionar ao cartão</div>

              {/* Members */}
              <div className="space-y-1">
                  <div className="relative">
                      <User size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                      <input 
                        type="text" 
                        value={formData.assignee}
                        onChange={(e) => setFormData({...formData, assignee: e.target.value})}
                        className="w-full bg-nexus-bg hover:bg-nexus-border border border-transparent rounded pl-7 py-1.5 text-sm text-left transition-colors cursor-pointer outline-none focus:border-nexus-cobalt placeholder-nexus-text"
                        placeholder="Membros"
