              {/* Labels */}
              <div className="space-y-2">
                   <div className="flex items-center gap-2 text-sm text-nexus-text bg-nexus-bg px-2 py-1.5 rounded cursor-default">
                       <TagIcon size={14} /> Etiquetas
                   </div>
                   <div className="flex flex-wrap gap-1 px-1">
                        {formData.tags?.map(tag => (
                             <div key={tag.text} className="w-full h-6 rounded flex items-center px-2 text-xs font-medium text-white relative group" style={{ backgroundColor: tag.color }}>
                                 {tag.text}
                                 <button onClick={() => removeTag(tag.text)} className="absolute right-1 opacity-0 group-hover:opacity-100"><X size={12}/></button>
