                        ))}
                   </div>
                   <div className="p-2 bg-nexus-bg border border-nexus-border rounded">
                        <input 
                            type="text" 
                            value={tagInput} 
                            onChange={(e) => setTagInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && addTag()}
                            className="w-full bg-transparent border-b border-nexus-border text-xs outline-none mb-2 pb-1"
                            placeholder="Nome da etiqueta..."
                        />
                        <div className="flex gap-1 flex-wrap">
                            {TAG_COLORS.map(c => (
                                <button 
                                    key={c}
                                    onClick={() => setSelectedTagColor(c)}
                                    className={`w-4 h-4 rounded-full ${selectedTagColor === c ? 'ring-2 ring-white' : ''}`}
                                    style={{ backgroundColor: c }}
                                />
                            ))}
                        </div>
                        <button onClick={addTag} className="w-full mt-2 text-xs bg-nexus-card hover:bg-nexus-border py-1 rounded">Adicionar</button>
                   </div>
              </div>

              {/* Dates */}
              <div className="space-y-1">
                  <div className="relative">
                      <Calendar size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                      <input 
                        type="date"
                        value={formData.dueDate}
                        onChange={(e) => setFormData({...formData, dueDate: e.target.value})}
                        className="w-full bg-nexus-bg hover:bg-nexus-border border border-transparent rounded pl-7 py-1.5 text-sm text-left transition-colors cursor-pointer outline-none focus:border-nexus-cobalt text-nexus-muted" 
                      />
                  </div>
              </div>

               {/* Meta Actions */}
               <div className="text-xs font-bold text-nexus-muted uppercase mt-6 mb-2">Ações</div>
               <div className="space-y-2">
                    <select 
                        value={formData.status} 
                        onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded px-2 py-1.5 text-xs outline-none"
                    >
                        {STATUS_COLUMNS.map(c => <option key={c.id} value={c.id}>Mover para: {c.label}</option>)}
                    </select>

                    <select 
                        value={formData.priority} 
                        onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded px-2 py-1.5 text-xs outline-none"
                    >
                        <option value="Low">Prioridade: Baixa</option>
                        <option value="Medium">Prioridade: Média</option>
                        <option value="High">Prioridade: Alta</option>
                    </select>

                    <div className="pt-4">
                        <label className="text-xs text-nexus-muted block mb-1">Progresso Manual</label>
                         <input 
                            type="range" 
                            min="0" 
                            max="100" 
                            value={formData.progress}
                            onChange={(e) => setFormData({...formData, progress: parseInt(e.target.value)})}
                            className="w-full h-1 bg-nexus-bg rounded-lg appearance-none cursor-pointer accent-nexus-cobalt"
                        />
                    </div>
               </div>

          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-nexus-border flex justify-between bg-nexus-bg/50">
          {task ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-3 py-1.5 text-xs text-red-500 hover:bg-red-900/20 rounded transition-colors"
            >
              <Trash2 size={14} /> Excluir
            </button>
          ) : <div></div>}

          <button 
            onClick={() => onSave(formData as Task)}
            className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-sm font-medium rounded transition-all shadow-lg shadow-blue-900/20"
          >
            <Save size={16} /> Salvar
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS } from './constants';
import { Plus, X } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);

  // UI State
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // Load Data on User Login
  useEffect(() => {
    if (user) {
      const storedProjects = JSON.parse(localStorage.getItem('luck_projects') || '[]');
      const storedTasks = JSON.parse(localStorage.getItem('luck_tasks') || '[]');

      // Data Migration: Ensure tags are objects
      const migratedTasks = storedTasks.map((t: any) => {
         if (t.tags && t.tags.length > 0 && typeof t.tags[0] === 'string') {
             return {
                 ...t,
                 tags: t.tags.map((txt: string) => ({ text: txt, color: '#3b82f6' }))
             }
         }
         return t;
      });

      // Filter projects: Owned by me OR Shared with me
      const myProjects = storedProjects.filter((p: Project) => 
        p.ownerId === user.id || p.sharedWith.includes(user.username)
      );

      setProjects(myProjects);
      setTasks(migratedTasks);

      if (myProjects.length > 0) {
        setCurrentProjectId(myProjects[0].id);
      } else {
        // Create default project if none
        const defaultProject: Project = { id: `p-${Date.now()}`, name: 'Meu Primeiro Projeto', ownerId: user.id, sharedWith: [] };
        const newProjects = [...storedProjects, defaultProject];
        localStorage.setItem('luck_projects', JSON.stringify(newProjects));
        setProjects([defaultProject]);
        setCurrentProjectId(defaultProject.id);
      }
    }
  }, [user]);

  // Persistence Helper
  const saveProjects = (newProjects: Project[]) => {
    const currentStorage = JSON.parse(localStorage.getItem('luck_projects') || '[]');
    const projectMap = new Map(currentStorage.map((p: Project) => [p.id, p]));
    newProjects.forEach(p => projectMap.set(p.id, p));
    localStorage.setItem('luck_projects', JSON.stringify(Array.from(projectMap.values())));
    setProjects(newProjects);
  };

  const saveTasks = (newTasks: Task[]) => {
    localStorage.setItem('luck_tasks', JSON.stringify(newTasks));
    setTasks(newTasks);
  };

  // Handlers
  const handleCreateProject = (name: string) => {
    if (!user) return;
    const newProject: Project = {
      id: `p-${Date.now()}`,
      name,
      ownerId: user.id,
      sharedWith: []
    };
    const updatedProjects = [...projects, newProject];
    saveProjects(updatedProjects);
    setCurrentProjectId(newProject.id);
    setCurrentView('board');
  };

  const handleShareProject = (username: string) => {
    if (!projectToShare) return;
    const updatedProject = { 
      ...projectToShare, 
      sharedWith: [...projectToShare.sharedWith, username] 
    };
    const updatedProjects = projects.map(p => p.id === updatedProject.id ? updatedProject : p);
    saveProjects(updatedProjects);
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     // Recombine with shared projects that aren't in the reordered list (if logic was split)
     // Since sidebar passes mostly "my projects" for reorder, we need to be careful.
     // For simplicity in Sidebar logic, we filtered only "my projects" for reordering.
     // We need to fetch current full list and swap the order of "my projects".

     // However, `saveProjects` merges by ID. So if `reorderedProjects` contains the correct new order of *all* visible projects, we are good.
     // In sidebar we spliced the specific list. Let's just save the result.
     // Note: If we save [A, B] and then merge into storage [B, A, C], the storage order isn't guaranteed by the map unless we fully replace.
     // For a true reorder feature, we need an 'order' field or save the array as is.
     // Simplest fix for now: Overwrite the local storage array for "my projects" segment.

     // Just save the new list as the state, and update local storage by putting these first.
     setProjects(reorderedProjects);

     // Update storage: remove old instances of these projects and append new order? 
     // Or just Map update (which doesn't preserve order). 
     // We need to save the array order.

     const allStorageProjects: Project[] = JSON.parse(localStorage.getItem('luck_projects') || '[]');
     const others = allStorageProjects.filter(p => !reorderedProjects.find(rp => rp.id === p.id));
     localStorage.setItem('luck_projects', JSON.stringify([...reorderedProjects, ...others]));
  }

  const handleSaveTask = (taskData: Task) => {
    if (selectedTask) {
      // Update
      const updatedTasks = tasks.map(t => t.id === taskData.id ? taskData : t);
      saveTasks(updatedTasks);
    } else {
      // Create
      if (!currentProjectId) return;
      const newTask: Task = {
        ...taskData,
        id: `t-${Date.now()}`,
        createdAt: new Date().toISOString(),
        projectId: currentProjectId
      };
      saveTasks([...tasks, newTask]);
    }
    setIsTaskModalOpen(false);
  };

  const handleQuickAdd = () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newTask: Task = {
        id: `t-${Date.now()}`,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString()
      };

      saveTasks([...tasks, newTask]);
      setQuickAddTitle('');
      setQuickAddColumn(null); // Close quick add
  };

  const handleDeleteTask = (id: string) => {
    saveTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);
  };

  // Drag and Drop
  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = (e: React.DragEvent, status: Status) => {
    const taskId = e.dataTransfer.getData('taskId');
    const task = tasks.find(t => t.id === taskId);
    if (task && task.status !== status) {
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status } : t);
      saveTasks(updatedTasks);
    }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={setUser} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={() => setUser(null)}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0">

        {/* Only show Metrics Header in Board View */}
        {currentView === 'board' && <MetricsHeader tasks={contextTasks} project={currentProject} />}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard tasks={contextTasks} project={currentProject} />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS.map(col => {
                    const colTasks = contextTasks.filter(t => t.status === col.id);
                    return (
                        <div 
                        key={col.id} 
                        className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                        onDragOver={onDragOver}
                        onDrop={(e) => onDrop(e, col.id)}
                        >
                        <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                            <div className="flex items-center gap-2">
                            <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                {col.label}
                            </span>
                            <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                {colTasks.length}
                            </span>
                            </div>
                            <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                        </div>

                        <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                            {colTasks.map(task => (
                                <TaskCard 
                                key={task.id} 
                                task={task} 
                                onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                onDelete={handleDeleteTask} 
                                />
                            ))}

                            {/* Quick Add Section */}
                            {quickAddColumn === col.id ? (
                                <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                    <textarea
                                        autoFocus 
                                        value={quickAddTitle}
                                        onChange={(e) => setQuickAddTitle(e.target.value)}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' && !e.shiftKey) {
                                                e.preventDefault();
                                                handleQuickAdd();
                                            }
                                        }}
                                        placeholder="Insira um título para o cartão..."
                                        className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                    />
                                    <div className="flex items-center gap-2">
                                        <button 
                                            onClick={handleQuickAdd}
                                            className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                        >
                                            Adicionar Cartão
                                        </button>
                                        <button 
                                            onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                            className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                        >
                                            <X size={16} />
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setQuickAddColumn(col.id)}
                                    className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                >
                                    <Plus size={14} /> Adicionar cartão
                                </button>
                            )}
                        </div>
                        </div>
                    );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">Selecione ou crie um projeto.</div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
      />
    </div>
  );
};

export default App;

