                       <TagIcon size={14} /> Etiquetas
                   </div>

                   {/* Selected Tags */}
                   <div className="flex flex-wrap gap-1 px-1 mb-2">
                        {formData.tags?.map(tag => (
                             <div key={tag.text} className="w-full h-6 rounded flex items-center px-2 text-xs font-medium text-white relative group" style={{ backgroundColor: tag.color }}>
                                 {tag.text}
                                 <button onClick={() => removeTag(tag.text)} className="absolute right-1 opacity-0 group-hover:opacity-100"><X size={12}/></button>
                             </div>
                        ))}
                   </div>

                   {/* Preset Tags List */}
                   <div className="p-2 bg-nexus-bg border border-nexus-border rounded max-h-48 overflow-y-auto custom-scrollbar">
                        <div className="text-[10px] text-nexus-muted uppercase mb-1">Sugestões</div>
                        <div className="space-y-1 mb-3">
                            {PRESET_TAGS.map(preset => (
                                <button 
                                    key={preset.text}
                                    onClick={() => addTag(preset.text, preset.color)}
                                    className="w-full text-left px-2 py-1 rounded text-xs text-white hover:opacity-80 transition-opacity flex items-center justify-between"
                                    style={{ backgroundColor: preset.color }}
                                >
                                    {preset.text}
                                    {formData.tags?.find(t => t.text === preset.text) && <div className="w-1.5 h-1.5 rounded-full bg-white"></div>}
                                </button>
                            ))}
                        </div>

                        <div className="text-[10px] text-nexus-muted uppercase mb-1">Criar Nova</div>
                        <input 
                            type="text" 
                            value={tagInput} 
                            onChange={(e) => setTagInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && addTag(tagInput, selectedTagColor)}
                            className="w-full bg-transparent border-b border-nexus-border text-xs outline-none mb-2 pb-1"
                            placeholder="Nome..."
                        />
                        <div className="flex gap-1 flex-wrap mb-2">
                            {TAG_COLORS.map(c => (
                                <button 
                                    key={c}
                                    onClick={() => setSelectedTagColor(c)}
                                    className={`w-4 h-4 rounded-full ${selectedTagColor === c ? 'ring-2 ring-white' : ''}`}
                                    style={{ backgroundColor: c }}
                                />
                            ))}
                        </div>
                        <button onClick={() => addTag(tagInput, selectedTagColor)} className="w-full mt-1 text-xs bg-nexus-card hover:bg-nexus-border py-1 rounded border border-nexus-border">Adicionar</button>
                   </div>
              </div>

              {/* Dates */}
              <div className="space-y-1">
                  <div className="relative">
                      <Calendar size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                      <input 
                        type="date"
                        value={formData.dueDate}
                        onChange={(e) => setFormData({...formData, dueDate: e.target.value})}
                        className="w-full bg-nexus-bg hover:bg-nexus-border border border-transparent rounded pl-7 py-1.5 text-sm text-left transition-colors cursor-pointer outline-none focus:border-nexus-cobalt text-nexus-muted" 
                      />
                  </div>
              </div>

               {/* Meta Actions */}
               <div className="text-xs font-bold text-nexus-muted uppercase mt-6 mb-2">Ações</div>
               <div className="space-y-2">
                    <select 
                        value={formData.status} 
                        onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded px-2 py-1.5 text-xs outline-none"
                    >
                        {STATUS_COLUMNS.map(c => <option key={c.id} value={c.id}>Mover para: {c.label}</option>)}
                    </select>

                    <select 
                        value={formData.priority} 
                        onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded px-2 py-1.5 text-xs outline-none"
                    >
                        <option value="Low">Prioridade: Baixa</option>
                        <option value="Medium">Prioridade: Média</option>
                        <option value="High">Prioridade: Alta</option>
                    </select>
               </div>

               <div className="mt-4 p-3 bg-nexus-bg/50 rounded border border-nexus-border">
                   <div className="text-xs text-nexus-muted mb-1">Progresso (Automático)</div>
                   <div className="flex items-center gap-2">
                       <div className="flex-1 h-2 bg-nexus-card rounded-full overflow-hidden border border-nexus-border">
                            <div className="h-full bg-nexus-cobalt" style={{ width: `${formData.progress}%` }}></div>
                       </div>
                       <span className="text-xs font-mono font-bold text-nexus-cobalt">{formData.progress}%</span>
                   </div>
                   <div className="text-[10px] text-nexus-muted mt-1 italic">
                       Baseado nos itens do checklist
                   </div>
               </div>

          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-nexus-border flex justify-between bg-nexus-bg/50">
          {task ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-3 py-1.5 text-xs text-red-500 hover:bg-red-900/20 rounded transition-colors"
            >
              <Trash2 size={14} /> Excluir
            </button>
          ) : <div></div>}

          <button 
            onClick={() => onSave(formData as Task)}
            className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-sm font-medium rounded transition-all shadow-lg shadow-blue-900/20"
          >
            <Save size={16} /> Salvar
          </button>
        </div>
      </div>
    </div>
  );
};

export interface User {
  id: string;
  username: string;
}

export interface Project {
  id: string;
  name: string;
  ownerId: string;
  sharedWith: string[]; // List of usernames
}

export type Priority = 'Low' | 'Medium' | 'High';

export type Status = 'backlog' | 'todo' | 'inprogress' | 'review' | 'done';

export interface Attachment {
  id: string;
  name: string;
  type: string; // 'image', 'pdf', 'other'
  url: string;
  size?: string;
}

export interface Tag {
  text: string;
  color: string;
}

export interface ChecklistItem {
  id: string;
  text: string;
  checked: boolean;
  dueDate?: string; // ISO String for specific date/time
}

export interface Task {
  id: string;
  title: string;
  description: string;
  // Client/Project Specifics (Backlog Intake)
  clientName?: string;
  clientSegment?: string; // New field for segment
  objective?: string;
  websiteUrl?: string;

  projectId: string; 
  status: Status;
  priority: Priority;
  progress: number; // 0-100
  tags: Tag[]; 
  attachments: Attachment[];
  checklist: ChecklistItem[]; 
  dueDate?: string;
  assignee?: string; // Username of member
  createdAt: string;
}

export interface Metric {
  label: string;
  value: string | number;
  trend: 'up' | 'down' | 'neutral';
  trendValue: string;
}

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS, PRESET_TAGS } from './constants';
import { Plus, X } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);

  // UI State
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session on mount
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
      const usersStr = localStorage.getItem('luck_users');
      const users: User[] = usersStr ? JSON.parse(usersStr) : [];
      const foundUser = users.find(u => u.username === activeUsername);
      if (foundUser) {
        setUser(foundUser);
      }
    }
  }, []);

  // Load Data when User changes
  useEffect(() => {
    if (user) {
      const storedProjects = JSON.parse(localStorage.getItem('luck_projects') || '[]');
      const storedTasks = JSON.parse(localStorage.getItem('luck_tasks') || '[]');
      const storedTags = JSON.parse(localStorage.getItem('luck_tags') || 'null');

      // Initialize tags if null
      if (!storedTags) {
        localStorage.setItem('luck_tags', JSON.stringify(PRESET_TAGS));
        setSystemTags(PRESET_TAGS);
      } else {
        setSystemTags(storedTags);
      }

      // Data Migration: Ensure tags are objects
      const migratedTasks = storedTasks.map((t: any) => {
         if (t.tags && t.tags.length > 0 && typeof t.tags[0] === 'string') {
             return {
                 ...t,
                 tags: t.tags.map((txt: string) => ({ text: txt, color: '#3b82f6' }))
             }
         }
         return t;
      });

      // Filter projects: Owned by me OR Shared with me
      const myProjects = storedProjects.filter((p: Project) => 
        p.ownerId === user.id || p.sharedWith.includes(user.username)
      );

      setProjects(myProjects);
      setTasks(migratedTasks);

      if (myProjects.length > 0) {
        // Only switch project if current is null or invalid
        if (!currentProjectId || !myProjects.find((p: Project) => p.id === currentProjectId)) {
            setCurrentProjectId(myProjects[0].id);
        }
      } else {
        // Create default project if none
        const defaultProject: Project = { id: `p-${Date.now()}`, name: 'Meu Primeiro Projeto', ownerId: user.id, sharedWith: [] };
        const newProjects = [...storedProjects, defaultProject];
        localStorage.setItem('luck_projects', JSON.stringify(newProjects));
        setProjects([defaultProject]);
        setCurrentProjectId(defaultProject.id);
      }
    }
  }, [user]);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
  };

  // Persistence Helper
  const saveProjects = (newProjects: Project[]) => {
    const currentStorage = JSON.parse(localStorage.getItem('luck_projects') || '[]');
    const projectMap = new Map(currentStorage.map((p: Project) => [p.id, p]));
    newProjects.forEach(p => projectMap.set(p.id, p));
    localStorage.setItem('luck_projects', JSON.stringify(Array.from(projectMap.values())));
    setProjects(newProjects);
  };

  const saveTasks = (newTasks: Task[]) => {
    localStorage.setItem('luck_tasks', JSON.stringify(newTasks));
    setTasks(newTasks);
  };

  const handleManageTags = (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      if (action === 'add') {
          // Avoid duplicates
          if (!newTags.find(t => t.text === tag.text)) {
              newTags.push(tag);
          }
      } else if (action === 'edit' && oldText) {
          newTags = newTags.map(t => t.text === oldText ? tag : t);
          // Update tasks that have this tag (optional, but good for consistency)
          const updatedTasks = tasks.map(t => ({
              ...t,
              tags: t.tags.map(tt => tt.text === oldText ? tag : tt)
          }));
          saveTasks(updatedTasks);
      } else if (action === 'delete') {
          newTags = newTags.filter(t => t.text !== tag.text);
      }

      setSystemTags(newTags);
      localStorage.setItem('luck_tags', JSON.stringify(newTags));
  };

  // Handlers
  const handleCreateProject = (name: string) => {
    if (!user) return;
    const newProject: Project = {
      id: `p-${Date.now()}`,
      name,
      ownerId: user.id,
      sharedWith: []
    };
    const updatedProjects = [...projects, newProject];
    saveProjects(updatedProjects);
    setCurrentProjectId(newProject.id);
    setCurrentView('board');
  };

  const handleShareProject = (username: string) => {
    if (!projectToShare) return;
    const updatedProject = { 
      ...projectToShare, 
      sharedWith: [...projectToShare.sharedWith, username] 
    };
    const updatedProjects = projects.map(p => p.id === updatedProject.id ? updatedProject : p);
    saveProjects(updatedProjects);
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
     const allStorageProjects: Project[] = JSON.parse(localStorage.getItem('luck_projects') || '[]');
     const others = allStorageProjects.filter(p => !reorderedProjects.find(rp => rp.id === p.id));
     localStorage.setItem('luck_projects', JSON.stringify([...reorderedProjects, ...others]));
  }

  const handleSaveTask = (taskData: Task) => {
    if (selectedTask) {
      // Update
      const updatedTasks = tasks.map(t => t.id === taskData.id ? taskData : t);
      saveTasks(updatedTasks);
    } else {
      // Create
      if (!currentProjectId) return;
      const newTask: Task = {
        ...taskData,
        id: `t-${Date.now()}`,
        createdAt: new Date().toISOString(),
        projectId: currentProjectId
      };
      saveTasks([...tasks, newTask]);
    }
    setIsTaskModalOpen(false);
  };

  const handleQuickAdd = () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newTask: Task = {
        id: `t-${Date.now()}`,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString()
      };

      saveTasks([...tasks, newTask]);
      setQuickAddTitle('');
      setQuickAddColumn(null); // Close quick add
  };

  const handleDeleteTask = (id: string) => {
    saveTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);
  };

  // Drag and Drop
  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = (e: React.DragEvent, status: Status) => {
    const taskId = e.dataTransfer.getData('taskId');
    const task = tasks.find(t => t.id === taskId);
    if (task && task.status !== status) {
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status } : t);
      saveTasks(updatedTasks);
    }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0">

        {/* Only show Metrics Header in Board View */}
        {currentView === 'board' && <MetricsHeader tasks={contextTasks} project={currentProject} />}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard tasks={contextTasks} project={currentProject} />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS.map(col => {
                    const colTasks = contextTasks.filter(t => t.status === col.id);
                    return (
                        <div 
                        key={col.id} 
                        className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                        onDragOver={onDragOver}
                        onDrop={(e) => onDrop(e, col.id)}
                        >
                        <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                            <div className="flex items-center gap-2">
                            <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                {col.label}
                            </span>
                            <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                {colTasks.length}
                            </span>
                            </div>
                            <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                        </div>

                        <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                            {colTasks.map(task => (
                                <TaskCard 
                                key={task.id} 
                                task={task} 
                                onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                onDelete={handleDeleteTask} 
                                />
                            ))}

                            {/* Quick Add Section */}
                            {quickAddColumn === col.id ? (
                                <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                    <textarea
                                        autoFocus 
                                        value={quickAddTitle}
                                        onChange={(e) => setQuickAddTitle(e.target.value)}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' && !e.shiftKey) {
                                                e.preventDefault();
                                                handleQuickAdd();
                                            }
                                        }}
                                        placeholder="Insira um título para o cartão..."
                                        className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                    />
                                    <div className="flex items-center gap-2">
                                        <button 
                                            onClick={handleQuickAdd}
                                            className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                        >
                                            Adicionar Cartão
                                        </button>
                                        <button 
                                            onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                            className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                        >
                                            <X size={16} />
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setQuickAddColumn(col.id)}
                                    className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                >
                                    <Plus size={14} /> Adicionar cartão
                                </button>
                            )}
                        </div>
                        </div>
                    );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">Selecione ou crie um projeto.</div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag, ChecklistItem } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target, Calendar, CheckSquare, User, Edit2 } from 'lucide-react';
import { STATUS_COLUMNS, PRESET_SEGMENTS } from '../constants';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
  availableTags: Tag[];
  onManageTags: (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => void;
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ 
    task, 
    isOpen, 
    onClose, 
    onSave, 
    onDelete, 
    currentProjectId,
    availableTags,
    onManageTags
}) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    clientSegment: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
    checklist: [],
    dueDate: '',
    assignee: ''
  });

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); 
  const [checklistInput, setChecklistInput] = useState('');

  // State for editing tags mode
  const [editingTag, setEditingTag] = useState<string | null>(null);

  // Auto-calculate progress whenever checklist changes
  useEffect(() => {
    if (formData.checklist) {
        const total = formData.checklist.length;
        const checked = formData.checklist.filter(i => i.checked).length;
        const newProgress = total === 0 ? 0 : Math.round((checked / total) * 100);

        if (newProgress !== formData.progress) {
            setFormData(prev => ({ ...prev, progress: newProgress }));
        }
    }
  }, [formData.checklist]);

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        clientSegment: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        dueDate: '',
        assignee: '',
        projectId: currentProjectId,
      });
    }
  }, [task, isOpen, currentProjectId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  const addTagToTask = (tag: Tag) => {
      if (!formData.tags?.find(t => t.text === tag.text)) {
          setFormData(prev => ({
              ...prev,
              tags: [...(prev.tags || []), tag]
          }));
      }
  };

  const createNewTag = () => {
      const tagName = tagInput.trim();
      if (tagName) {
          const newTag = { text: tagName, color: selectedTagColor };
          // Add to global list
          onManageTags('add', newTag);
          // Add to this task
          addTagToTask(newTag);
          setTagInput('');
      }
  };

  const removeTagFromTask = (textToRemove: string) => {
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  const addChecklistItem = () => {
      if (checklistInput.trim()) {
          const newItem: ChecklistItem = {
              id: Date.now().toString(),
              text: checklistInput.trim(),
              checked: false,
              dueDate: ''
          };
          setFormData(prev => ({
              ...prev,
              checklist: [...(prev.checklist || []), newItem]
          }));
          setChecklistInput('');
      }
  };

  const toggleChecklistItem = (id: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
          )
      }));
  };

  const updateChecklistItemText = (id: string, newText: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, text: newText } : item
          )
      }));
  };

  const updateChecklistItemDate = (id: string, date: string) => {
    setFormData(prev => ({
        ...prev,
        checklist: prev.checklist?.map(item => 
          item.id === id ? { ...item, dueDate: date } : item
        )
    }));
  };

  const deleteChecklistItem = (id: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[900px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col max-h-[95vh] text-nexus-text">

        {/* Header */}
        <div className="flex justify-between items-start p-6 border-b border-nexus-border bg-nexus-bg/50">
          <div className="flex-1 mr-4">
             <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-transparent border-none text-xl font-bold text-nexus-text focus:ring-0 outline-none p-0 placeholder-nexus-muted"
                  placeholder="Nome do Cartão..."
            />
            <div className="text-xs text-nexus-muted mt-1 flex gap-2">
                <span>em lista <strong>{STATUS_COLUMNS.find(c => c.id === formData.status)?.label}</strong></span>
            </div>
          </div>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Content - Two Column Layout */}
        <div className="flex-1 overflow-y-auto p-6 flex gap-6 custom-scrollbar">

          {/* LEFT COLUMN (Main Content) */}
          <div className="flex-1 space-y-6">

              {/* Description */}
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-sm font-bold text-nexus-text">
                    <FileText size={16} />
                    <h3>Descrição</h3>
                </div>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={4}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none"
                  placeholder="Adicionar descrição detalhada..."
                />
              </div>

              {/* Checklist */}
              <div className="space-y-2">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text">
                      <CheckSquare size={16} />
                      <h3>Checklist</h3>
                  </div>

                  {/* Progress Bar */}
                  {formData.checklist && formData.checklist.length > 0 && (
                      <div className="flex items-center gap-2 mb-2">
                          <span className="text-xs text-nexus-muted">
                              {Math.round((formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100)}%
                          </span>
                          <div className="flex-1 h-1.5 bg-nexus-bg rounded-full overflow-hidden">
                              <div 
                                className="h-full bg-nexus-cobalt transition-all" 
                                style={{ width: `${(formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100}%` }}
                              ></div>
                          </div>
                      </div>
                  )}

                  <div className="space-y-2">
                      {formData.checklist?.map(item => (
                          <div key={item.id} className="flex flex-col gap-1 border-b border-nexus-border/50 pb-2 mb-2 last:border-0 last:mb-0 last:pb-0">
                             <div className="flex items-center gap-2 group">
                                <input 
                                    type="checkbox" 
                                    checked={item.checked} 
                                    onChange={() => toggleChecklistItem(item.id)}
                                    className="w-4 h-4 rounded border-nexus-border bg-nexus-bg checked:bg-nexus-cobalt cursor-pointer"
                                />
                                <input 
                                    type="text"
                                    value={item.text}
                                    onChange={(e) => updateChecklistItemText(item.id, e.target.value)}
                                    className={`flex-1 text-sm bg-transparent outline-none border-b border-transparent focus:border-nexus-cobalt ${item.checked ? 'line-through text-nexus-muted' : ''}`}
                                />
                                <button onClick={() => deleteChecklistItem(item.id)} className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-red-500">
                                    <X size={14} />
                                </button>
                             </div>

                             {/* Date for checklist item */}
                             <div className="pl-6">
                                <input 
                                    type="datetime-local" 
                                    value={item.dueDate || ''}
                                    onChange={(e) => updateChecklistItemDate(item.id, e.target.value)}
                                    className="text-[10px] bg-transparent text-nexus-muted border border-nexus-border rounded px-1.5 py-0.5 outline-none focus:border-nexus-cobalt"
                                />
                             </div>
                          </div>
                      ))}
                      <div className="flex gap-2 mt-2">
                          <input 
                            type="text" 
                            value={checklistInput}
                            onChange={(e) => setChecklistInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && addChecklistItem()}
                            className="flex-1 bg-nexus-bg border border-nexus-border rounded px-3 py-1.5 text-sm outline-none focus:border-nexus-cobalt"
                            placeholder="Adicionar item..."
                          />
                          <button onClick={addChecklistItem} className="bg-nexus-bg hover:bg-nexus-border border border-nexus-border rounded px-3 py-1 text-xs">Adicionar</button>
                      </div>
                  </div>
              </div>

               {/* Attachments */}
               <div className="space-y-2">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text">
                      <FileText size={16} />
                      <h3>Anexos</h3>
                  </div>
                  <div className="grid grid-cols-2 gap-3 mb-2">
                    {formData.attachments?.map(att => (
                        <div key={att.id} className="flex items-center gap-3 p-2 bg-nexus-bg border border-nexus-border rounded">
                        {att.type === 'image' ? (
                            <img src={att.url} alt="prev" className="w-8 h-8 object-cover rounded" />
                        ) : (
                            <div className="w-8 h-8 bg-nexus-border flex items-center justify-center rounded text-nexus-text"><FileText size={14} /></div>
                        )}
                        <div className="flex-1 min-w-0">
                            <p className="text-xs truncate text-nexus-text">{att.name}</p>
                            <a href={att.url} target="_blank" rel="noreferrer" className="text-[10px] text-nexus-cobalt hover:underline">Abrir</a>
                        </div>
                        <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500"><X size={14} /></button>
                        </div>
                    ))}
                  </div>
                   <div className="relative group">
                    <input 
                        type="file" 
                        onChange={handleFileChange} 
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                    />
                    <button className="text-sm text-nexus-muted bg-nexus-bg hover:bg-nexus-border px-3 py-2 rounded w-full border border-nexus-border border-dashed transition-colors">
                        Adicionar anexo
                    </button>
                   </div>
               </div>

               {/* Client Info (Collapsible or Block) */}
               {formData.status === 'backlog' && (
                   <div className="bg-nexus-bg/30 border border-nexus-border rounded p-4 space-y-3">
                       <h4 className="text-xs font-bold uppercase text-nexus-muted tracking-wider flex items-center gap-2">
                           <Briefcase size={12} /> Dados do Cliente (Backlog)
                       </h4>
                       <div className="grid grid-cols-2 gap-3">
                           <input 
                                type="text" 
                                value={formData.clientName} 
                                onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                                className="bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                                placeholder="Nome do Cliente"
                            />

                            {/* Segment Input with Datalist */}
                            <div className="relative">
                                <input 
                                    list="segment-options"
                                    type="text" 
                                    value={formData.clientSegment} 
                                    onChange={(e) => setFormData({...formData, clientSegment: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                                    placeholder="Segmento (ex: Automotivo)"
                                />
                                <datalist id="segment-options">
                                    {PRESET_SEGMENTS.map(seg => (
                                        <option key={seg} value={seg} />
                                    ))}
                                </datalist>
                            </div>
                       </div>

                       <input 
                            type="text" 
                            value={formData.websiteUrl} 
                            onChange={(e) => setFormData({...formData, websiteUrl: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                            placeholder="Website URL"
                        />

                       <input 
                            type="text" 
                            value={formData.objective} 
                            onChange={(e) => setFormData({...formData, objective: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt"
                            placeholder="Objetivo Principal"
                        />
                   </div>
               )}

          </div>

          {/* RIGHT COLUMN (Sidebar Actions - Trello Style) */}
          <div className="w-64 space-y-4">
              <div className="text-xs font-bold text-nexus-muted uppercase mb-2">Adicionar ao cartão</div>

              {/* Members */}
              <div className="space-y-1">
                  <div className="relative">
                      <User size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                      <input 
                        type="text" 
                        value={formData.assignee}
                        onChange={(e) => setFormData({...formData, assignee: e.target.value})}
                        className="w-full bg-nexus-bg hover:bg-nexus-border border border-transparent rounded pl-7 py-1.5 text-sm text-left transition-colors cursor-pointer outline-none focus:border-nexus-cobalt placeholder-nexus-text"
                        placeholder="Membros"
                      />
                  </div>
              </div>

              {/* Labels / Tags */}
              <div className="space-y-2">
                   <div className="flex items-center gap-2 text-sm text-nexus-text bg-nexus-bg px-2 py-1.5 rounded cursor-default">
                       <TagIcon size={14} /> Etiquetas
                   </div>

                   {/* Selected Tags on this task */}
                   <div className="flex flex-wrap gap-1 px-1 mb-2">
                        {formData.tags?.map(tag => (
                             <div key={tag.text} className="w-full h-6 rounded flex items-center px-2 text-xs font-medium text-white relative group" style={{ backgroundColor: tag.color }}>
                                 {tag.text}
                                 <button onClick={() => removeTagFromTask(tag.text)} className="absolute right-1 opacity-0 group-hover:opacity-100"><X size={12}/></button>
                             </div>
                        ))}
                   </div>

                   {/* Available Tags List (Manageable) */}
                   <div className="p-2 bg-nexus-bg border border-nexus-border rounded max-h-48 overflow-y-auto custom-scrollbar">
                        <div className="text-[10px] text-nexus-muted uppercase mb-1">Sugestões</div>
                        <div className="space-y-1 mb-3">
                            {availableTags.map(tag => (
                                <div key={tag.text} className="flex items-center gap-1 group">
                                    <button 
                                        onClick={() => addTagToTask(tag)}
                                        className="flex-1 text-left px-2 py-1 rounded text-xs text-white hover:opacity-80 transition-opacity flex items-center justify-between"
                                        style={{ backgroundColor: tag.color }}
                                    >
                                        {tag.text}
                                        {formData.tags?.find(t => t.text === tag.text) && <div className="w-1.5 h-1.5 rounded-full bg-white"></div>}
                                    </button>

                                    {/* Edit/Delete Controls for Global List */}
                                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button 
                                            onClick={() => { setTagInput(tag.text); setSelectedTagColor(tag.color); setEditingTag(tag.text); }}
                                            className="p-1 text-nexus-muted hover:text-nexus-cobalt" title="Editar"
                                        >
                                            <Edit2 size={12} />
                                        </button>
                                        <button 
                                            onClick={() => onManageTags('delete', tag)}
                                            className="p-1 text-nexus-muted hover:text-red-500" title="Excluir"
                                        >
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="text-[10px] text-nexus-muted uppercase mb-1">{editingTag ? 'Editar Etiqueta' : 'Criar Nova'}</div>
                        <div className="flex gap-1 mb-1">
                             <input 
                                type="text" 
                                value={tagInput} 
                                onChange={(e) => setTagInput(e.target.value)}
                                className="flex-1 bg-transparent border-b border-nexus-border text-xs outline-none pb-1"
                                placeholder="Nome..."
                            />
                            {editingTag && (
                                <button onClick={() => { setEditingTag(null); setTagInput(''); }} className="text-nexus-muted hover:text-nexus-text">
                                    <X size={12} />
                                </button>
                            )}
                        </div>

                        <div className="flex gap-1 flex-wrap mb-2">
                            {TAG_COLORS.map(c => (
                                <button 
                                    key={c}
                                    onClick={() => setSelectedTagColor(c)}
                                    className={`w-4 h-4 rounded-full ${selectedTagColor === c ? 'ring-2 ring-white' : ''}`}
                                    style={{ backgroundColor: c }}
                                />
                            ))}
                        </div>

                        <button 
                            onClick={() => {
                                if (editingTag) {
                                    onManageTags('edit', { text: tagInput, color: selectedTagColor }, editingTag);
                                    setEditingTag(null);
                                    setTagInput('');
                                } else {
                                    createNewTag();
                                }
                            }} 
                            className="w-full mt-1 text-xs bg-nexus-card hover:bg-nexus-border py-1 rounded border border-nexus-border"
                        >
                            {editingTag ? 'Salvar Edição' : 'Adicionar'}
                        </button>
                   </div>
              </div>

              {/* Dates */}
              <div className="space-y-1">
                  <div className="relative">
                      <Calendar size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                      <input 
                        type="date"
                        value={formData.dueDate}
                        onChange={(e) => setFormData({...formData, dueDate: e.target.value})}
                        className="w-full bg-nexus-bg hover:bg-nexus-border border border-transparent rounded pl-7 py-1.5 text-sm text-left transition-colors cursor-pointer outline-none focus:border-nexus-cobalt text-nexus-muted" 
                      />
                  </div>
              </div>

               {/* Meta Actions */}
               <div className="text-xs font-bold text-nexus-muted uppercase mt-6 mb-2">Ações</div>
               <div className="space-y-2">
                    <select 
                        value={formData.status} 
                        onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded px-2 py-1.5 text-xs outline-none"
                    >
                        {STATUS_COLUMNS.map(c => <option key={c.id} value={c.id}>Mover para: {c.label}</option>)}
                    </select>

                    <select 
                        value={formData.priority} 
                        onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded px-2 py-1.5 text-xs outline-none"
                    >
                        <option value="Low">Prioridade: Baixa</option>
                        <option value="Medium">Prioridade: Média</option>
                        <option value="High">Prioridade: Alta</option>
                    </select>
               </div>

               <div className="mt-4 p-3 bg-nexus-bg/50 rounded border border-nexus-border">
                   <div className="text-xs text-nexus-muted mb-1">Progresso (Automático)</div>
                   <div className="flex items-center gap-2">
                       <div className="flex-1 h-2 bg-nexus-card rounded-full overflow-hidden border border-nexus-border">
                            <div className="h-full bg-nexus-cobalt" style={{ width: `${formData.progress}%` }}></div>
                       </div>
                       <span className="text-xs font-mono font-bold text-nexus-cobalt">{formData.progress}%</span>
                   </div>
                   <div className="text-[10px] text-nexus-muted mt-1 italic">
                       Baseado nos itens do checklist
                   </div>
               </div>

          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-nexus-border flex justify-between bg-nexus-bg/50">
          {task ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-3 py-1.5 text-xs text-red-500 hover:bg-red-900/20 rounded transition-colors"
            >
              <Trash2 size={14} /> Excluir
            </button>
          ) : <div></div>}

          <button 
            onClick={() => onSave(formData as Task)}
            className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-sm font-medium rounded transition-all shadow-lg shadow-blue-900/20"
          >
            <Save size={16} /> Salvar
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Task, Priority } from '../types';
import { Paperclip, MoreHorizontal, Globe, CheckSquare, UserCircle } from 'lucide-react';

interface TaskCardProps {
  task: Task;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
}

const PriorityBadge: React.FC<{ priority: Priority }> = ({ priority }) => {
  const colors = {
    Low: 'bg-neutral-200 text-neutral-600 border-neutral-300 dark:bg-neutral-800 dark:text-neutral-400 dark:border-neutral-700',
    Medium: 'bg-blue-100 text-blue-600 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/30',
    High: 'bg-amber-100 text-amber-600 border-amber-200 dark:bg-amber-900/20 dark:text-amber-500 dark:border-amber-900/30',
  };

  return (
    <span className={`text-[9px] px-1.5 py-0.5 rounded border uppercase tracking-wider font-bold ${colors[priority]}`}>
      {priority === 'Low' ? 'Baixa' : priority === 'Medium' ? 'Média' : 'Alta'}
    </span>
  );
};

export const TaskCard: React.FC<TaskCardProps> = ({ task, onEdit }) => {
  // Determine border color based on priority
  const borderLeftColor = 
    task.priority === 'High' ? 'border-l-nexus-accent' : 
    task.priority === 'Medium' ? 'border-l-nexus-cobalt' : 'border-l-gray-400 dark:border-l-neutral-600';

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('taskId', task.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const checklistTotal = task.checklist ? task.checklist.length : 0;
  const checklistDone = task.checklist ? task.checklist.filter(i => i.checked).length : 0;

  return (
    <div 
      draggable
      onDragStart={handleDragStart}
      onClick={() => onEdit(task)}
      className={`
        group relative bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt/50 transition-all duration-200 cursor-grab active:cursor-grabbing overflow-hidden
        border-l-[3px] ${borderLeftColor} p-3 mb-3 shadow-sm hover:shadow-md
      `}
    >
      <div className="flex justify-between items-start mb-2">
        <PriorityBadge priority={task.priority} />
        {checklistTotal > 0 && checklistDone === checklistTotal && <div className="h-1.5 w-1.5 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]"></div>}
      </div>

      <h3 className="text-sm font-medium text-nexus-text leading-tight mb-2 line-clamp-2 group-hover:text-nexus-cobalt transition-colors">
        {task.title}
      </h3>

      {(task.clientName || task.clientSegment) && (
        <div className="flex flex-col mb-2">
            {task.clientName && (
                <p className="text-[10px] text-nexus-muted font-mono uppercase tracking-wider">
                {task.clientName}
                </p>
            )}
            {task.clientSegment && (
                <p className="text-[9px] text-nexus-cobalt font-medium">
                {task.clientSegment}
                </p>
            )}
        </div>
      )}

      {task.tags && task.tags.length > 0 && (
        <div className="flex items-center gap-2 mb-3 flex-wrap">
            {task.tags.slice(0, 4).map((tag, i) => (
            <span 
                key={i} 
                className="text-[10px] px-1.5 py-0.5 rounded font-medium border border-transparent"
                style={{ 
                backgroundColor: `${tag.color}20`, // 20% opacity
                color: tag.color,
                borderColor: `${tag.color}40`
                }}
            >
                #{tag.text}
            </span>
            ))}
        </div>
      )}

      {/* Progress Bar - Only if greater than 0 */}
      {task.progress > 0 && (
        <div className="w-full bg-nexus-bg h-1 rounded-full overflow-hidden mb-3">
            <div 
            className={`h-full transition-all duration-500 ${task.priority === 'High' ? 'bg-nexus-accent' : 'bg-nexus-cobalt'}`} 
            style={{ width: `${task.progress}%` }}
            ></div>
        </div>
      )}

      <div className="flex justify-between items-center text-nexus-muted mt-2">
        <div className="flex items-center gap-3 text-[10px]">
          {task.attachments && task.attachments.length > 0 && (
            <div className="flex items-center gap-1">
              <Paperclip size={10} />
              <span>{task.attachments.length}</span>
            </div>
          )}
          {checklistTotal > 0 && (
             <div className={`flex items-center gap-1 ${checklistDone === checklistTotal ? 'text-green-500' : ''}`}>
               <CheckSquare size={10} />
               <span>{checklistDone}/{checklistTotal}</span>
             </div>
          )}
          {task.websiteUrl && (
             <Globe size={10} />
          )}
        </div>

        {task.assignee ? (
             <div className="flex items-center gap-1.5 bg-nexus-bg border border-nexus-border pl-1 pr-2 py-0.5 rounded-full max-w-[120px]" title={`Responsável: ${task.assignee}`}>
                <div className="w-4 h-4 rounded-full bg-nexus-cobalt flex items-center justify-center text-[9px] text-white font-bold flex-shrink-0">
                    {task.assignee.substring(0,1).toUpperCase()}
                </div>
                <span className="text-[10px] font-medium text-nexus-text truncate">{task.assignee}</span>
             </div>
        ) : (
            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                <MoreHorizontal size={14} />
            </div>
        )}
      </div>
    </div>
  );
};

import { createClient } from '@supabase/supabase-js';

// Substitua estas variáveis pelas credenciais do seu projeto Supabase
// Você encontra isso em Project Settings -> API
const SUPABASE_URL = 'SUA_URL_SUPABASE_AQUI';
const SUPABASE_ANON_KEY = 'SUA_KEY_ANON_AQUI';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

import React, { useState } from 'react';
import { LayoutGrid, ArrowRight, Loader2 } from 'lucide-react';
import { User } from '../types';
import { supabase } from '../supabaseClient';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!username.trim()) {
      setError('Por favor digite um usuário.');
      setLoading(false);
      return;
    }

    try {
      // Check if user exists
      const { data: existingUser, error: fetchError } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', username)
        .single();

      if (fetchError && fetchError.code !== 'PGRST116') { // PGRST116 is "not found"
         throw fetchError;
      }

      if (isRegister) {
        if (existingUser) {
          setError('Usuário já existe. Tente fazer login.');
          setLoading(false);
          return;
        }

        // Create new user
        const { error: insertError } = await supabase
          .from('profiles')
          .insert([{ username }]);

        if (insertError) throw insertError;

        onLogin({ id: username, username }); // Using username as ID for simplicity in this flow
      } else {
        if (!existingUser) {
          setError('Usuário não encontrado. Crie uma conta.');
          setLoading(false);
          return;
        }
        onLogin({ id: existingUser.username, username: existingUser.username });
      }

    } catch (err: any) {
      console.error(err);
      setError('Erro ao conectar com o banco de dados. Verifique as credenciais no código.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center">
      <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl">
        <div className="flex flex-col items-center mb-8">
          <div className="w-12 h-12 bg-nexus-cobalt rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-blue-900/50">
             <LayoutGrid size={24} className="text-white" />
          </div>
          <h1 className="text-2xl font-bold text-nexus-text font-mono tracking-tight">LUCK OS</h1>
          <p className="text-xs text-nexus-muted mt-2 uppercase tracking-widest text-center">Dashboard de Acompanhamento de Projetos</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="text-xs uppercase font-bold text-nexus-muted mb-1 block">Usuário</label>
            <input 
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors"
              placeholder="Digite seu usuário..."
              disabled={loading}
            />
          </div>

          {error && <p className="text-red-500 text-xs">{error}</p>}

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-3 rounded transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : (
                <>
                    {isRegister ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
                </>
            )}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {isRegister ? 'Já tem conta? Entrar' : 'Não tem conta? Registrar'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS, PRESET_TAGS } from './constants';
import { Plus, X, Loader2 } from 'lucide-react';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
       setUser({ id: activeUsername, username: activeUsername });
    }
  }, []);

  // 2. Fetch Data from Supabase when user is logged in
  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  const fetchData = async () => {
      if (!user) return;
      setIsLoading(true);
      try {
          // A. Fetch Tags
          const { data: tagsData } = await supabase.from('tags').select('*');
          if (tagsData && tagsData.length > 0) {
              setSystemTags(tagsData);
          } else {
              // Initialize default tags if empty
              const { error } = await supabase.from('tags').insert(PRESET_TAGS);
              if (!error) setSystemTags(PRESET_TAGS);
              else setSystemTags(PRESET_TAGS); 
          }

          // B. Fetch Projects (Owned or Shared)
          const { data: allProjects } = await supabase.from('projects').select('*');

          if (allProjects) {
            const myProjects = allProjects.filter((p: any) => 
                p.owner_id === user.id || 
                (Array.isArray(p.shared_with) && p.shared_with.includes(user.username))
            ).map((p: any) => ({
                id: p.id,
                name: p.name,
                ownerId: p.owner_id,
                sharedWith: p.shared_with || []
            }));

            setProjects(myProjects);

            if (myProjects.length > 0) {
                 // Select first project if none selected
                 let activeProject = currentProjectId;
                 if (!activeProject || !myProjects.find(p => p.id === activeProject)) {
                     activeProject = myProjects[0].id;
                     setCurrentProjectId(activeProject);
                 }

                 // C. Fetch Tasks for ALL available projects to avoid constant refetching on switch
                 const projectIds = myProjects.map(p => p.id);
                 const { data: tasksData } = await supabase
                    .from('tasks')
                    .select('*')
                    .in('project_id', projectIds);

                if (tasksData) {
                    const mappedTasks: Task[] = tasksData.map((t: any) => ({
                        id: t.id,
                        title: t.title,
                        description: t.description || '',
                        clientName: t.client_name,
                        clientSegment: t.client_segment,
                        objective: t.objective,
                        websiteUrl: t.website_url,
                        projectId: t.project_id,
                        status: t.status,
                        priority: t.priority,
                        progress: t.progress || 0,
                        tags: t.tags || [],
                        attachments: t.attachments || [],
                        checklist: t.checklist || [],
                        dueDate: t.due_date,
                        assignee: t.assignee,
                        createdAt: t.created_at
                    }));
                    setTasks(mappedTasks);
                }
            } else {
                setTasks([]);
                setCurrentProjectId(null);
            }
          }

      } catch (error) {
          console.error("Error fetching data:", error);
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
    setProjects([]);
    setTasks([]);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      try {
        if (action === 'add') {
            if (!newTags.find(t => t.text === tag.text)) {
                await supabase.from('tags').insert(tag);
                newTags.push(tag);
            }
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
            newTags = newTags.map(t => t.text === oldText ? tag : t);

            // Optimistic update for tasks
            setTasks(prev => prev.map(t => ({
                ...t,
                tags: t.tags.map(tt => tt.text === oldText ? tag : tt)
            })));

        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
            newTags = newTags.filter(t => t.text !== tag.text);
        }
        setSystemTags(newTags);
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

  // Handlers
  const handleCreateProject = async (name: string) => {
    if (!user) return;
    const newProject = {
      id: crypto.randomUUID(),
      name,
      owner_id: user.id,
      shared_with: []
    };

    const { error } = await supabase.from('projects').insert(newProject);

    if (!error) {
        const mappedProject: Project = {
            id: newProject.id,
            name: newProject.name,
            ownerId: newProject.owner_id,
            sharedWith: newProject.shared_with
        };
        setProjects([...projects, mappedProject]);
        setCurrentProjectId(mappedProject.id);
        setCurrentView('board');
    }
  };

  const handleShareProject = async (username: string) => {
    if (!projectToShare) return;
    // Don't share if user doesn't exist (basic check could be added here)
    const updatedSharedWith = [...projectToShare.sharedWith, username];

    const { error } = await supabase
        .from('projects')
        .update({ shared_with: updatedSharedWith })
        .eq('id', projectToShare.id);

    if (!error) {
        const updatedProject = { ...projectToShare, sharedWith: updatedSharedWith };
        setProjects(projects.map(p => p.id === updatedProject.id ? updatedProject : p));
    }
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
  };

  const handleSaveTask = async (taskData: Task) => {
    const dbTask = {
        id: taskData.id,
        project_id: taskData.projectId,
        title: taskData.title,
        description: taskData.description,
        client_name: taskData.clientName,
        client_segment: taskData.clientSegment,
        objective: taskData.objective,
        website_url: taskData.websiteUrl,
        status: taskData.status,
        priority: taskData.priority,
        progress: taskData.progress,
        tags: taskData.tags,
        attachments: taskData.attachments,
        checklist: taskData.checklist,
        due_date: taskData.dueDate,
        assignee: taskData.assignee,
        created_at: taskData.createdAt
    };

    const { error } = await supabase.from('tasks').upsert(dbTask);

    if (!error) {
        if (selectedTask) {
            setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
        } else {
            setTasks([...tasks, taskData]);
        }
        setIsTaskModalOpen(false);
    } else {
        console.error("Error saving task", error);
    }
  };

  const handleQuickAdd = async () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newId = crypto.randomUUID();
      const newTask: Task = {
        id: newId,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString()
      };

      // Save to DB
      const dbTask = {
        id: newTask.id,
        project_id: newTask.projectId,
        title: newTask.title,
        status: newTask.status,
        priority: newTask.priority,
        created_at: newTask.createdAt
      };

      const { error } = await supabase.from('tasks').insert(dbTask);

      if (!error) {
          setTasks([...tasks, newTask]);
          setQuickAddTitle('');
          setQuickAddColumn(null); 
      }
  };

  const handleDeleteTask = async (id: string) => {
    const { error } = await supabase.from('tasks').delete().eq('id', id);
    if (!error) {
        setTasks(tasks.filter(t => t.id !== id));
        setIsTaskModalOpen(false);
    }
  };

  // Drag and Drop
  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = async (e: React.DragEvent, status: Status) => {
    const taskId = e.dataTransfer.getData('taskId');
    const task = tasks.find(t => t.id === taskId);
    if (task && task.status !== status) {
      // Optimistic Update
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status } : t);
      setTasks(updatedTasks);

      // DB Update
      await supabase.from('tasks').update({ status }).eq('id', taskId);
    }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {/* Only show Metrics Header in Board View */}
        {currentView === 'board' && <MetricsHeader tasks={contextTasks} project={currentProject} />}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard tasks={contextTasks} project={currentProject} />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS.map(col => {
                    const colTasks = contextTasks.filter(t => t.status === col.id);
                    return (
                        <div 
                        key={col.id} 
                        className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                        onDragOver={onDragOver}
                        onDrop={(e) => onDrop(e, col.id)}
                        >
                        <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                            <div className="flex items-center gap-2">
                            <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                {col.label}
                            </span>
                            <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                {colTasks.length}
                            </span>
                            </div>
                            <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                        </div>

                        <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                            {colTasks.map(task => (
                                <TaskCard 
                                key={task.id} 
                                task={task} 
                                onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                onDelete={handleDeleteTask} 
                                />
                            ))}

                            {/* Quick Add Section */}
                            {quickAddColumn === col.id ? (
                                <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                    <textarea
                                        autoFocus 
                                        value={quickAddTitle}
                                        onChange={(e) => setQuickAddTitle(e.target.value)}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' && !e.shiftKey) {
                                                e.preventDefault();
                                                handleQuickAdd();
                                            }
                                        }}
                                        placeholder="Insira um título para o cartão..."
                                        className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                    />
                                    <div className="flex items-center gap-2">
                                        <button 
                                            onClick={handleQuickAdd}
                                            className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                        >
                                            Adicionar Cartão
                                        </button>
                                        <button 
                                            onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                            className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                        >
                                            <X size={16} />
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setQuickAddColumn(col.id)}
                                    className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                >
                                    <Plus size={14} /> Adicionar cartão
                                </button>
                            )}
                        </div>
                        </div>
                    );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
      />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { LayoutGrid, ArrowRight, Loader2 } from 'lucide-react';
import { User } from '../types';
import { supabase } from '../supabaseClient';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!username.trim()) {
      setError('Por favor digite um usuário.');
      setLoading(false);
      return;
    }

    try {
      // Check if user exists
      const { data: existingUser, error: fetchError } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', username)
        .single();

      if (fetchError && fetchError.code !== 'PGRST116') { // PGRST116 is "not found"
         throw fetchError;
      }

      if (isRegister) {
        if (existingUser) {
          setError('Usuário já existe. Tente fazer login.');
          setLoading(false);
          return;
        }

        // Create new user
        const { error: insertError } = await supabase
          .from('profiles')
          .insert([{ username }]);

        if (insertError) throw insertError;

        onLogin({ id: username, username }); // Using username as ID for simplicity in this flow
      } else {
        if (!existingUser) {
          setError('Usuário não encontrado. Crie uma conta.');
          setLoading(false);
          return;
        }
        onLogin({ id: existingUser.username, username: existingUser.username });
      }

    } catch (err: any) {
      console.error(err);
      setError('Erro ao conectar com o banco de dados. Verifique o arquivo supabaseClient.ts.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center">
      <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl">
        <div className="flex flex-col items-center mb-8">
          <div className="w-12 h-12 bg-nexus-cobalt rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-blue-900/50">
             <LayoutGrid size={24} className="text-white" />
          </div>
          <h1 className="text-2xl font-bold text-nexus-text font-mono tracking-tight">LUCK OS</h1>
          <p className="text-xs text-nexus-muted mt-2 uppercase tracking-widest text-center">Dashboard de Acompanhamento de Projetos</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="text-xs uppercase font-bold text-nexus-muted mb-1 block">Usuário</label>
            <input 
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors"
              placeholder="Digite seu usuário..."
              disabled={loading}
            />
          </div>

          {error && <p className="text-red-500 text-xs">{error}</p>}

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-3 rounded transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : (
                <>
                    {isRegister ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
                </>
            )}
          </button>
        </form>

        <div className="mt-6 text-center">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {isRegister ? 'Já tem conta? Entrar' : 'Não tem conta? Registrar'}
          </button>
        </div>
      </div>
    </div>
  );
};

