import React, { useState } from 'react';
import { LayoutGrid, Folder, Plus, Activity, Sun, Moon, LogOut, Share2, GripVertical, User as UserIcon, Users } from 'lucide-react';
import { Project, User } from '../types';

interface SidebarProps {
  projects: Project[];
  currentProjectId: string | null;
  setProjectId: (id: string) => void;
  onNewProject: () => void;
  onShareProject: (project: Project) => void;
  onReorderProjects: (projects: Project[]) => void;
  user: User;
  onLogout: () => void;
  isDark: boolean;
  toggleTheme: () => void;
  currentView: 'board' | 'monitoring';
  setView: (view: 'board' | 'monitoring') => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  projects, 
  currentProjectId, 
  setProjectId, 
  onNewProject,
  onShareProject,
  onReorderProjects,
  user,
  onLogout,
  isDark,
  toggleTheme,
  currentView,
  setView
}) => {
  const [draggedProject, setDraggedProject] = useState<Project | null>(null);

  // Group Projects
  const myProjects = projects.filter(p => p.ownerId === user.id);
  const sharedProjects = projects.filter(p => p.ownerId !== user.id);

  // Find current project object
  const selectedProject = projects.find(p => p.id === currentProjectId);

  const handleDragStart = (e: React.DragEvent, project: Project) => {
    setDraggedProject(project);
    e.dataTransfer.effectAllowed = 'move';
    // Only allow reordering within "My Projects" for now to simplify
    if (project.ownerId !== user.id) {
       e.preventDefault();
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, targetProject: Project) => {
    e.preventDefault();
    if (!draggedProject || draggedProject.id === targetProject.id) return;

    // Simple reorder logic for "My Projects"
    if (draggedProject.ownerId === user.id && targetProject.ownerId === user.id) {
        const newOrder = [...projects];
        const draggedIdx = newOrder.findIndex(p => p.id === draggedProject.id);
        const targetIdx = newOrder.findIndex(p => p.id === targetProject.id);

        // Remove and insert
        newOrder.splice(draggedIdx, 1);
        newOrder.splice(targetIdx, 0, draggedProject);

        onReorderProjects(newOrder);
    }
    setDraggedProject(null);
  };

  const renderProjectItem = (item: Project, isShared: boolean) => (
    <div 
        key={item.id} 
        className={`group relative flex items-center ${!isShared ? 'cursor-grab active:cursor-grabbing' : ''}`}
        draggable={!isShared}
        onDragStart={(e) => handleDragStart(e, item)}
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, item)}
    >
      {!isShared && (
        <div className="absolute left-1 opacity-0 group-hover:opacity-100 text-nexus-muted cursor-grab">
            <GripVertical size={12} />
        </div>
      )}
      <button
        onClick={() => { setProjectId(item.id); setView('board'); }}
        className={`flex-1 flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all duration-200 ml-2 ${
          currentProjectId === item.id && currentView === 'board'
            ? 'bg-nexus-card text-nexus-cobalt border-l-2 border-nexus-cobalt shadow-sm'
            : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
        }`}
      >
        <Folder size={16} className={`${currentProjectId === item.id && currentView === 'board' ? 'text-nexus-cobalt' : 'text-nexus-muted'}`} />
        <span className="truncate max-w-[140px]">{item.name}</span>
        {isShared && (
            <span className="text-[9px] bg-nexus-border px-1 rounded text-nexus-muted ml-auto">
                Shared
            </span>
        )}
      </button>
    </div>
  );

  return (
    <aside className="w-64 h-screen bg-nexus-bg border-r border-nexus-border flex flex-col flex-shrink-0 z-20 transition-colors duration-300">
      <div className="h-16 flex items-center px-6 border-b border-nexus-border">
        <div 
            onClick={() => setView('board')}
            className="flex items-center gap-3 text-nexus-text font-bold tracking-tight cursor-pointer hover:opacity-80 transition-opacity"
        >
          <div className="w-8 h-8 bg-nexus-cobalt rounded-sm flex items-center justify-center flex-shrink-0">
             <LayoutGrid size={16} className="text-white" />
          </div>
          <span className="font-mono text-[10px] leading-tight font-bold">PAINEL DE<br/>ACOMPANHAMENTO</span>
        </div>
      </div>

      <div className="flex-1 py-6 px-3 space-y-4 overflow-y-auto">

        <div className="space-y-2">
            {/* New Project Button */}
            <button 
                onClick={onNewProject} 
                className="w-full flex items-center justify-center gap-2 py-2 border border-dashed border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors"
            >
                <Plus size={14} /> Novo Projeto
            </button>

            {/* Share Current Project Button (Contextual) */}
            {selectedProject && selectedProject.ownerId === user.id && (
                <button 
                    onClick={() => onShareProject(selectedProject)}
                    className="w-full flex items-center justify-center gap-2 py-2 bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors shadow-sm"
                >
                    <Share2 size={14} /> Compartilhar Projeto
                </button>
            )}
        </div>

        {/* My Projects Section */}
        <div>
            <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                <UserIcon size={12} />
                <span>Meus Projetos</span>
            </div>
            <div className="space-y-0.5">
                {myProjects.length > 0 ? (
                    myProjects.map(p => renderProjectItem(p, false))
                ) : (
                    <div className="px-5 py-2 text-xs text-nexus-muted italic opacity-50">Vazio</div>
                )}
            </div>
        </div>

        {/* Shared Projects Section */}
        {sharedProjects.length > 0 && (
            <div>
                <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                    <Users size={12} />
                    <span>Compartilhados</span>
                </div>
                <div className="space-y-0.5">
                    {sharedProjects.map(p => renderProjectItem(p, true))}
                </div>
            </div>
        )}

        <div className="pt-4 mt-4 border-t border-nexus-border/50">
            <div className="px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">SISTEMA</div>
            <button 
                onClick={() => setView('monitoring')}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${
                    currentView === 'monitoring' 
                    ? 'bg-nexus-card text-nexus-accent border-l-2 border-nexus-accent' 
                    : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
                }`}
            >
            <Activity size={18} />
            <span>Monitoramento</span>
            </button>
        </div>
      </div>

      <div className="p-4 border-t border-nexus-border space-y-4">
        <div className="flex items-center justify-between px-2">
           <span className="text-xs text-nexus-muted font-medium">Tema</span>
           <button 
             onClick={toggleTheme}
             className="p-2 rounded-full bg-nexus-card hover:bg-nexus-hover text-nexus-text border border-nexus-border transition-colors"
           >
             {isDark ? <Sun size={14} /> : <Moon size={14} />}
           </button>
        </div>

        <div className="flex items-center gap-3 px-2 pt-2 border-t border-nexus-border">
          <div className="w-8 h-8 rounded bg-gradient-to-br from-nexus-cobalt to-purple-600 flex items-center justify-center text-xs font-bold text-white uppercase">
            {user.username.substring(0, 2)}
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            <span className="text-xs font-medium text-nexus-text truncate">{user.username}</span>
            <span className="text-[10px] text-nexus-muted font-mono">Online</span>
          </div>
          <button onClick={onLogout} className="text-nexus-muted hover:text-red-500 transition-colors">
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </aside>
  );
};

import React, { useMemo } from 'react';
import { Task, Project } from '../types';
import { TrendingUp, Clock, CheckCircle2, Filter, Users } from 'lucide-react';

interface MetricsHeaderProps {
  tasks: Task[];
  project?: Project;
  availableAssignees?: string[];
  currentFilter?: string | null;
  onFilterChange?: (assignee: string | null) => void;
}

export const MetricsHeader: React.FC<MetricsHeaderProps> = ({ 
  tasks, 
  project, 
  availableAssignees = [], 
  currentFilter, 
  onFilterChange 
}) => {
  const metrics = useMemo(() => {
    const total = tasks.length;
    const done = tasks.filter(t => t.status === 'done').length;

    // Calculate simple completion rate
    const completionRate = total === 0 ? 0 : Math.round((done / total) * 100);

    // Calculate "velocity" (mocked based on progress of active tasks)
    const activeTasks = tasks.filter(t => t.status === 'inprogress' || t.status === 'review');
    const velocity = activeTasks.reduce((acc, curr) => acc + curr.progress, 0) / (activeTasks.length || 1);

    return [
      { label: 'Tarefas Ativas', value: total - done, icon: Clock, color: 'text-nexus-text' },
      { label: 'Conclusão', value: `${completionRate}%`, icon: CheckCircle2, color: 'text-nexus-cobalt' },
      { label: 'Velocidade', value: Math.round(velocity), icon: TrendingUp, color: 'text-nexus-accent' },
    ];
  }, [tasks]);

  return (
    <header className="h-20 border-b border-nexus-border bg-nexus-bg/80 backdrop-blur-md sticky top-0 z-10 flex items-center justify-between px-8">
      <div>
        <h1 className="text-xl font-bold text-nexus-text tracking-tight flex items-center gap-2">
          {project ? project.name : 'Dashboard'} <span className="text-nexus-muted font-light hidden sm:inline-block">Overview</span>
        </h1>
        <p className="text-xs text-nexus-muted font-mono mt-0.5">
           {project ? (project.sharedWith.length > 0 ? `Compartilhado com ${project.sharedWith.length} usuários` : 'Privado') : 'Selecione um projeto'}
        </p>
      </div>

      <div className="flex items-center gap-8">

        {/* Assignee Filter */}
        {onFilterChange && availableAssignees.length > 0 && (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-nexus-card border border-nexus-border rounded-md mr-4 shadow-sm group hover:border-nexus-cobalt transition-colors">
                <Filter size={14} className={`text-nexus-muted ${currentFilter ? 'text-nexus-cobalt' : ''}`} />
                <select 
                    value={currentFilter || ''} 
                    onChange={(e) => onFilterChange(e.target.value || null)}
                    className="bg-transparent text-xs font-medium text-nexus-text outline-none cursor-pointer min-w-[120px]"
                >
                    <option value="">Todos os membros</option>
                    {availableAssignees.map(user => (
                        <option key={user} value={user}>
                            {user}
                        </option>
                    ))}
                </select>
            </div>
        )}

        {metrics.map((metric, idx) => (
          <div key={idx} className="flex flex-col items-end">
             <div className="flex items-center gap-2">
                <span className="text-[10px] uppercase tracking-wider font-mono text-nexus-muted">{metric.label}</span>
                <metric.icon size={12} className={metric.color} />
             </div>
             <span className={`text-xl font-bold font-mono ${metric.color}`}>{metric.value}</span>
          </div>
        ))}
      </div>
    </header>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS, PRESET_TAGS } from './constants';
import { Plus, X, Loader2, CheckCircle2 } from 'lucide-react';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Filter State
  const [assigneeFilter, setAssigneeFilter] = useState<string | null>(null);

  // Toast State
  const [toast, setToast] = useState<{ visible: boolean; message: string; type: 'success' | 'error' } | null>(null);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
       setUser({ id: activeUsername, username: activeUsername });
    }
  }, []);

  // 2. Fetch Data from Supabase when user is logged in
  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  // Reset filter when project changes
  useEffect(() => {
    setAssigneeFilter(null);
  }, [currentProjectId]);

  // Toast Timer
  useEffect(() => {
    if (toast?.visible) {
      const timer = setTimeout(() => {
        setToast(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ visible: true, message, type });
  };

  const fetchData = async () => {
      if (!user) return;
      setIsLoading(true);
      try {
          // A. Fetch Tags
          const { data: tagsData } = await supabase.from('tags').select('*');
          if (tagsData && tagsData.length > 0) {
              setSystemTags(tagsData);
          } else {
              // Initialize default tags if empty
              const { error } = await supabase.from('tags').insert(PRESET_TAGS);
              if (!error) setSystemTags(PRESET_TAGS);
              else setSystemTags(PRESET_TAGS); 
          }

          // B. Fetch Projects (Owned or Shared)
          const { data: allProjects } = await supabase.from('projects').select('*');

          if (allProjects) {
            const myProjects = allProjects.filter((p: any) => 
                p.owner_id === user.id || 
                (Array.isArray(p.shared_with) && p.shared_with.includes(user.username))
            ).map((p: any) => ({
                id: p.id,
                name: p.name,
                ownerId: p.owner_id,
                sharedWith: p.shared_with || []
            }));

            setProjects(myProjects);

            if (myProjects.length > 0) {
                 // Select first project if none selected
                 let activeProject = currentProjectId;
                 if (!activeProject || !myProjects.find(p => p.id === activeProject)) {
                     activeProject = myProjects[0].id;
                     setCurrentProjectId(activeProject);
                 }

                 // C. Fetch Tasks for ALL available projects to avoid constant refetching on switch
                 const projectIds = myProjects.map(p => p.id);
                 const { data: tasksData } = await supabase
                    .from('tasks')
                    .select('*')
                    .in('project_id', projectIds);

                if (tasksData) {
                    const mappedTasks: Task[] = tasksData.map((t: any) => ({
                        id: t.id,
                        title: t.title,
                        description: t.description || '',
                        clientName: t.client_name,
                        clientSegment: t.client_segment,
                        objective: t.objective,
                        websiteUrl: t.website_url,
                        projectId: t.project_id,
                        status: t.status,
                        priority: t.priority,
                        progress: t.progress || 0,
                        tags: t.tags || [],
                        attachments: t.attachments || [],
                        checklist: t.checklist || [],
                        dueDate: t.due_date,
                        assignee: t.assignee,
                        createdAt: t.created_at
                    }));
                    setTasks(mappedTasks);
                }
            } else {
                setTasks([]);
                setCurrentProjectId(null);
            }
          }

      } catch (error) {
          console.error("Error fetching data:", error);
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
    setProjects([]);
    setTasks([]);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      try {
        if (action === 'add') {
            if (!newTags.find(t => t.text === tag.text)) {
                await supabase.from('tags').insert(tag);
                newTags.push(tag);
            }
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
            newTags = newTags.map(t => t.text === oldText ? tag : t);

            // Optimistic update for tasks
            setTasks(prev => prev.map(t => ({
                ...t,
                tags: t.tags.map(tt => tt.text === oldText ? tag : tt)
            })));

        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
            newTags = newTags.filter(t => t.text !== tag.text);
        }
        setSystemTags(newTags);
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

  // Handlers
  const handleCreateProject = async (name: string) => {
    if (!user) return;
    const newProject = {
      id: crypto.randomUUID(),
      name,
      owner_id: user.id,
      shared_with: []
    };

    const { error } = await supabase.from('projects').insert(newProject);

    if (!error) {
        const mappedProject: Project = {
            id: newProject.id,
            name: newProject.name,
            ownerId: newProject.owner_id,
            sharedWith: newProject.shared_with
        };
        setProjects([...projects, mappedProject]);
        setCurrentProjectId(mappedProject.id);
        setCurrentView('board');
        showToast("Projeto criado com sucesso!");
    }
  };

  const handleShareProject = async (username: string, taskId?: string) => {
    if (!projectToShare) return;

    try {
        // 1. Update Project Sharing
        let updatedSharedWith = projectToShare.sharedWith;
        if (!updatedSharedWith.includes(username)) {
            updatedSharedWith = [...updatedSharedWith, username];

            const { error: projectError } = await supabase
                .from('projects')
                .update({ shared_with: updatedSharedWith })
                .eq('id', projectToShare.id);

            if (projectError) throw projectError;

            const updatedProject = { ...projectToShare, sharedWith: updatedSharedWith };
            setProjects(projects.map(p => p.id === updatedProject.id ? updatedProject : p));
        }

        // 2. If a specific task was selected, assign it to the user
        if (taskId) {
            const { error: taskError } = await supabase
                .from('tasks')
                .update({ assignee: username })
                .eq('id', taskId);

            if (taskError) throw taskError;

            // Update local state
            setTasks(prev => prev.map(t => t.id === taskId ? { ...t, assignee: username } : t));
        }

        showToast("Projeto compartilhado", "success");

    } catch (error) {
        console.error(error);
        showToast("Erro ao compartilhar", "error");
    }
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
  };

  const handleSaveTask = async (taskData: Task) => {
    const dbTask = {
        id: taskData.id,
        project_id: taskData.projectId,
        title: taskData.title,
        description: taskData.description,
        client_name: taskData.clientName,
        client_segment: taskData.clientSegment,
        objective: taskData.objective,
        website_url: taskData.websiteUrl,
        status: taskData.status,
        priority: taskData.priority,
        progress: taskData.progress,
        tags: taskData.tags,
        attachments: taskData.attachments,
        checklist: taskData.checklist,
        due_date: taskData.dueDate,
        assignee: taskData.assignee,
        created_at: taskData.createdAt
    };

    const { error } = await supabase.from('tasks').upsert(dbTask);

    if (!error) {
        if (selectedTask) {
            setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
        } else {
            setTasks([...tasks, taskData]);
        }
        setIsTaskModalOpen(false);
    } else {
        console.error("Error saving task", error);
    }
  };

  const handleQuickAdd = async () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newId = crypto.randomUUID();
      const newTask: Task = {
        id: newId,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString()
      };

      // Save to DB
      const dbTask = {
        id: newTask.id,
        project_id: newTask.projectId,
        title: newTask.title,
        status: newTask.status,
        priority: newTask.priority,
        created_at: newTask.createdAt
      };

      const { error } = await supabase.from('tasks').insert(dbTask);

      if (!error) {
          setTasks([...tasks, newTask]);
          setQuickAddTitle('');
          setQuickAddColumn(null); 
      }
  };

  const handleDeleteTask = async (id: string) => {
    const { error } = await supabase.from('tasks').delete().eq('id', id);
    if (!error) {
        setTasks(tasks.filter(t => t.id !== id));
        setIsTaskModalOpen(false);
    }
  };

  // Drag and Drop
  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = async (e: React.DragEvent, status: Status) => {
    const taskId = e.dataTransfer.getData('taskId');
    const task = tasks.find(t => t.id === taskId);
    if (task && task.status !== status) {
      // Optimistic Update
      const updatedTasks = tasks.map(t => t.id === taskId ? { ...t, status } : t);
      setTasks(updatedTasks);

      // DB Update
      await supabase.from('tasks').update({ status }).eq('id', taskId);
    }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  // Filtering Logic
  const uniqueAssignees = Array.from(new Set(contextTasks.map(t => t.assignee).filter(Boolean))) as string[];

  const filteredTasks = assigneeFilter 
      ? contextTasks.filter(t => t.assignee === assigneeFilter) 
      : contextTasks;

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {/* Only show Metrics Header in Board View */}
        {currentView === 'board' && (
            <MetricsHeader 
                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard tasks={filteredTasks} project={currentProject} />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS.map(col => {
                    const colTasks = filteredTasks.filter(t => t.status === col.id);
                    return (
                        <div 
                        key={col.id} 
                        className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                        onDragOver={onDragOver}
                        onDrop={(e) => onDrop(e, col.id)}
                        >
                        <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                            <div className="flex items-center gap-2">
                            <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                {col.label}
                            </span>
                            <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                {colTasks.length}
                            </span>
                            </div>
                            <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                        </div>

                        <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                            {colTasks.map(task => (
                                <TaskCard 
                                key={task.id} 
                                task={task} 
                                onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                onDelete={handleDeleteTask} 
                                />
                            ))}

                            {/* Quick Add Section */}
                            {quickAddColumn === col.id ? (
                                <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                    <textarea
                                        autoFocus 
                                        value={quickAddTitle}
                                        onChange={(e) => setQuickAddTitle(e.target.value)}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' && !e.shiftKey) {
                                                e.preventDefault();
                                                handleQuickAdd();
                                            }
                                        }}
                                        placeholder="Insira um título para o cartão..."
                                        className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                    />
                                    <div className="flex items-center gap-2">
                                        <button 
                                            onClick={handleQuickAdd}
                                            className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                        >
                                            Adicionar Cartão
                                        </button>
                                        <button 
                                            onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                            className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                        >
                                            <X size={16} />
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setQuickAddColumn(col.id)}
                                    className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                >
                                    <Plus size={14} /> Adicionar cartão
                                </button>
                            )}
                        </div>
                        </div>
                    );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      {/* Toast Notification */}
      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'success' 
                ? 'bg-green-500/10 border-green-500/20 text-green-500' 
                : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
