               <div className="mt-4 p-3 bg-nexus-bg/50 rounded border border-nexus-border">
                   <div className="text-xs text-nexus-muted mb-1">Progresso (Automático)</div>
                   <div className="flex items-center gap-2">
                       <div className="flex-1 h-2 bg-nexus-card rounded-full overflow-hidden border border-nexus-border">
