                                <button 
                                    onClick={() => {
                                        if (editingTag) {
                                            onManageTags('edit', { text: tagInput, color: selectedTagColor }, editingTag);
                                            setEditingTag(null);
                                            setTagInput('');
                                        } else {
                                            createNewTag();
                                        }
                                    }} 
