const MOCK_TASKS: Task[] = [
    { id: 't1', title: 'Integração Gateway de Pagamento', description: 'Configurar Stripe e webhooks', status: 'inprogress', priority: 'High', progress: 65, tags: [{text: 'Integração API', color: '#22c55e'}], attachments: [], checklist: [{id:'1', text: 'Chaves API', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 10000).toISOString(), assignee: 'demo', position: 1000, coverUrl: 'https://images.unsplash.com/photo-1556742049-0cfed4f7a07d?auto=format&fit=crop&q=80&w=800' },
    { id: 't2', title: 'Design System v2.0', description: 'Atualizar componentes no Figma', status: 'todo', priority: 'Medium', progress: 0, tags: [{text: 'Dashboard', color: '#ec4899'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 8000).toISOString(), assignee: 'demo', position: 2000 },
    { id: 't3', title: 'Setup de CI/CD', description: 'Pipeline no Github Actions', status: 'done', priority: 'High', progress: 100, tags: [{text: 'Infra/Deploy', color: '#ef4444'}], attachments: [], checklist: [{id:'1', text: 'Build script', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 6000).toISOString(), assignee: 'demo', position: 3000 },
    { id: 't4', title: 'Fluxo de Automação de Leads', description: 'Conectar Typeform ao CRM via Make', status: 'inprogress', priority: 'High', progress: 40, tags: [{text: 'Automação (Make/Zapier)', color: '#f97316'}], attachments: [], checklist: [], projectId: 'proj-2', createdAt: new Date(Date.now() - 4000).toISOString(), assignee: 'demo', position: 1000 },
    { id: 't5', title: 'Otimização de Banco de Dados', description: 'Indexação de tabelas críticas', status: 'review', priority: 'Medium', progress: 90, tags: [{text: 'Limpeza/ETL', color: '#06b6d4'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 2000).toISOString(), assignee: 'demo', position: 4000 },
];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);
  const [isOfflineMode, setIsOfflineMode] = useState(false);

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Column Visibility State
  const [hiddenColumns, setHiddenColumns] = useState<Status[]>([]);

  // Filter State
  const [assigneeFilter, setAssigneeFilter] = useState<string | null>(null);

  // Toast State
  const [toast, setToast] = useState<{ visible: boolean; message: string; type: 'success' | 'error' } | null>(null);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
       setUser({ id: activeUsername, username: activeUsername });
    }
  }, []);

  // 2. Fetch Data from Supabase when user is logged in
  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  // Reset filter when project changes
  useEffect(() => {
    setAssigneeFilter(null);
  }, [currentProjectId]);

  // Toast Timer
  useEffect(() => {
    if (toast?.visible) {
      const timer = setTimeout(() => {
        setToast(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ visible: true, message, type });
  };

  const loadMockData = () => {
    console.log("Loading Mock Data for Offline Mode");
    setIsOfflineMode(true);
    setSystemTags(PRESET_TAGS);
    setProjects(MOCK_PROJECTS);
    setTasks(MOCK_TASKS);
    setCurrentProjectId(MOCK_PROJECTS[0].id);
  };

  const fetchData = async () => {
      if (!user) return;
      setIsLoading(true);
      setIsOfflineMode(false);

      try {
          // A. Fetch Tags
          const { data: tagsData, error: tagsError } = await supabase.from('tags').select('*');

          if (tagsError) throw tagsError; // Force catch if DB fails

          if (tagsData && tagsData.length > 0) {
              setSystemTags(tagsData);
          } else {
             await supabase.from('tags').insert(PRESET_TAGS).then(({error}) => {
                 if(!error) setSystemTags(PRESET_TAGS);
                 else setSystemTags(PRESET_TAGS);
             }); 
          }

          // B. Fetch Projects
          const { data: allProjects, error: projectsError } = await supabase.from('projects').select('*');

          if (projectsError) throw projectsError;

          if (allProjects) {
            const myProjects = allProjects.filter((p: any) => 
                p.owner_id === user.id || 
                (Array.isArray(p.shared_with) && p.shared_with.includes(user.username))
            ).map((p: any) => ({
                id: p.id,
                name: p.name,
                ownerId: p.owner_id,
                sharedWith: Array.isArray(p.shared_with) 
                    ? p.shared_with.filter((s: any) => typeof s === 'string') 
                    : []
            }));

            setProjects(myProjects);

            if (myProjects.length > 0) {
                 let activeProject = currentProjectId;
                 if (!activeProject || !myProjects.find(p => p.id === activeProject)) {
                     activeProject = myProjects[0].id;
                     setCurrentProjectId(activeProject);
                 }

                 // C. Fetch Tasks
                 const projectIds = myProjects.map(p => p.id);
                 const { data: tasksData, error: tasksError } = await supabase
                    .from('tasks')
                    .select('*')
                    .in('project_id', projectIds);

                if (tasksError) throw tasksError;

                if (tasksData) {
                    const mappedTasks: Task[] = tasksData.map((t: any, index: number) => ({
                        id: t.id,
                        title: t.title,
                        description: t.description || '',
                        clientName: t.client_name,
                        clientSegment: t.client_segment,
                        objective: t.objective,
                        websiteUrl: t.website_url,
                        projectId: t.project_id,
                        status: t.status,
                        priority: t.priority,
                        progress: t.progress || 0,
                        tags: t.tags || [],
                        attachments: t.attachments || [],
                        checklist: t.checklist || [],
                        dueDate: t.due_date,
                        assignee: typeof t.assignee === 'string' ? t.assignee : undefined,
                        createdAt: t.created_at,
                        // Ensure distinct positions on load if missing or 0
                        position: t.position || (index + 1) * 1000,
                        coverUrl: t.cover_url
                    }));
                    setTasks(mappedTasks);
                }
            } else {
                setTasks([]);
                setCurrentProjectId(null);
            }
          }

      } catch (error) {
          console.error("Error fetching data, falling back to local mode:", error);
          loadMockData();
          showToast("Modo Offline: Dados de exemplo carregados", "error");
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
    setProjects([]);
    setTasks([]);
    setIsOfflineMode(false);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      if (action === 'add') {
         if (!newTags.find(t => t.text === tag.text)) newTags.push(tag);
      } else if (action === 'edit' && oldText) {
         newTags = newTags.map(t => t.text === oldText ? tag : t);
         setTasks(prev => prev.map(t => ({...t, tags: t.tags.map(tt => tt.text === oldText ? tag : tt)})));
      } else if (action === 'delete') {
         newTags = newTags.filter(t => t.text !== tag.text);
      }
      setSystemTags(newTags);

      if (isOfflineMode) return;

      try {
        if (action === 'add') {
           await supabase.from('tags').insert(tag);
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
        }
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

  const handleCreateProject = async (name: string) => {
    if (!user) return;
    const newProject = {
      id: crypto.randomUUID(),
      name,
      owner_id: user.id,
      shared_with: []
    };

    const mappedProject: Project = {
        id: newProject.id,
        name: newProject.name,
        ownerId: newProject.owner_id,
        sharedWith: newProject.shared_with
    };
    setProjects([...projects, mappedProject]);
    setCurrentProjectId(mappedProject.id);
    setCurrentView('board');
    showToast("Projeto criado com sucesso!");

    if (isOfflineMode) return;

    const { error } = await supabase.from('projects').insert(newProject);
    if (error) console.error(error);
  };

  const handleShareProject = async (username: string, taskId?: string) => {
    if (!projectToShare) return;

    let updatedSharedWith = projectToShare.sharedWith;
    if (!updatedSharedWith.includes(username)) {
        updatedSharedWith = [...updatedSharedWith, username];
        const updatedProject = { ...projectToShare, sharedWith: updatedSharedWith };
        setProjects(projects.map(p => p.id === updatedProject.id ? updatedProject : p));
    }
    if (taskId) {
        setTasks(prev => prev.map(t => t.id === taskId ? { ...t, assignee: username } : t));
    }
    showToast("Projeto compartilhado (Local)", "success");

    if (isOfflineMode) return;

    try {
        const { error: projectError } = await supabase
            .from('projects')
            .update({ shared_with: updatedSharedWith })
            .eq('id', projectToShare.id);
        if (projectError) throw projectError;

        if (taskId) {
            const { error: taskError } = await supabase
                .from('tasks')
                .update({ assignee: username })
                .eq('id', taskId);
            if (taskError) throw taskError;
        }
    } catch (error) {
        console.error(error);
        showToast("Erro ao sincronizar compartilhamento", "error");
    }
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
  };

  const handleSaveTask = async (taskData: Task) => {
    if (selectedTask) {
        setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
        setTasks([...tasks, taskData]);
    }
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;

    const dbTask = {
        id: taskData.id,
        project_id: taskData.projectId,
        title: taskData.title,
        description: taskData.description,
        client_name: taskData.clientName,
        client_segment: taskData.clientSegment,
        objective: taskData.objective,
        website_url: taskData.websiteUrl,
        status: taskData.status,
        priority: taskData.priority,
        progress: taskData.progress,
        tags: taskData.tags,
        attachments: taskData.attachments,
        checklist: taskData.checklist,
        due_date: taskData.dueDate,
        assignee: taskData.assignee,
        created_at: taskData.createdAt,
        position: taskData.position,
        cover_url: taskData.coverUrl
    };

    const { error } = await supabase.from('tasks').upsert(dbTask);
    if (error) console.error("Error saving task", error);
  };

  const handleQuickAdd = async () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newId = crypto.randomUUID();
      const columnTasks = tasks.filter(t => t.status === quickAddColumn && t.projectId === currentProjectId);
      const maxPos = columnTasks.length > 0 ? Math.max(...columnTasks.map(t => t.position || 0)) : 0;

      const newTask: Task = {
        id: newId,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString(),
        position: maxPos + 1000
      };

      setTasks([...tasks, newTask]);
      setQuickAddTitle('');
      setQuickAddColumn(null); 

      if (isOfflineMode) return;

      const dbTask = {
        id: newTask.id,
        project_id: newTask.projectId,
        title: newTask.title,
        status: newTask.status,
        priority: newTask.priority,
        created_at: newTask.createdAt,
        position: newTask.position
      };

      const { error } = await supabase.from('tasks').insert(dbTask);
      if (error) console.error(error);
  };

  const handleDeleteTask = async (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;
    const { error } = await supabase.from('tasks').delete().eq('id', id);
    if (error) console.error(error);
  };

  const toggleColumnVisibility = (status: Status) => {
      setHiddenColumns(prev => 
          prev.includes(status) 
          ? prev.filter(s => s !== status) 
          : [...prev, status]
      );
  };

  // --- DRAG AND DROP REORDERING ---
  const handleTaskDrop = async (draggedTaskId: string, targetId: string | null, targetStatus: Status, positionOnTarget: 'before' | 'after' = 'after') => {
      if (!currentProjectId) return;

      const draggedTask = tasks.find(t => t.id === draggedTaskId);
      if (!draggedTask) return;

      // 1. Clean list excluding dragged task
      const otherTasks = tasks.filter(t => t.id !== draggedTaskId);

      // 2. Get target column tasks sorted strictly
      const targetColumnTasks = otherTasks
            .filter(t => t.projectId === currentProjectId && t.status === targetStatus)
            .sort((a, b) => {
                const posA = a.position || 0;
                const posB = b.position || 0;
                if (posA !== posB) return posA - posB;
                return a.createdAt.localeCompare(b.createdAt);
            });

      let newPosition = 0;

      if (!targetId) {
          // Drop on Empty Column or at end
          const lastTask = targetColumnTasks[targetColumnTasks.length - 1];
          newPosition = lastTask ? (lastTask.position || 0) + 1000 : 1000;
      } else {
          // Drop relative to specific task
          const targetIndex = targetColumnTasks.findIndex(t => t.id === targetId);
          if (targetIndex !== -1) {
              const targetTask = targetColumnTasks[targetIndex];
              const targetPos = targetTask.position || 0;

              if (positionOnTarget === 'before') {
                  const prevTask = targetColumnTasks[targetIndex - 1];
                  const prevPos = prevTask ? (prevTask.position || 0) : 0;

                  // If we are placing before the first item, or between two items
                  if (!prevTask) {
                      newPosition = targetPos / 2;
                  } else {
                      newPosition = (targetPos + prevPos) / 2;
                  }
              } else {
                  // After
                  const nextTask = targetColumnTasks[targetIndex + 1];
                  const nextPos = nextTask ? (nextTask.position || 0) : targetPos + 1000;

                  newPosition = (targetPos + nextPos) / 2;
              }
          } else {
              newPosition = 1000;
          }
      }

      // 3. Update State
      const updatedTask = { ...draggedTask, status: targetStatus, position: newPosition };
      setTasks([...otherTasks, updatedTask]);

      // 4. Update Database
      if (!isOfflineMode) {
          await supabase.from('tasks').update({ status: targetStatus, position: newPosition }).eq('id', draggedTaskId);
      }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDropColumn = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    handleTaskDrop(taskId, null, status);
  };

  const onDropTask = (draggedId: string, targetId: string, position: 'before' | 'after') => {
      const targetTask = tasks.find(t => t.id === targetId);
      if (targetTask) {
          handleTaskDrop(draggedId, targetId, targetTask.status, position);
      }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  const uniqueAssignees = Array.from(new Set(
      contextTasks
        .map(t => t.assignee)
        .filter((a): a is string => typeof a === 'string' && a.length > 0)
  ));

  const filteredTasks = assigneeFilter 
      ? contextTasks.filter(t => t.assignee === assigneeFilter) 
      : contextTasks;

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isOfflineMode && (
             <div className="bg-red-500/10 border-b border-red-500/20 text-red-500 text-[10px] font-bold uppercase tracking-widest py-1 text-center flex items-center justify-center gap-2">
                 <WifiOff size={10} /> Modo Offline / Demonstração
             </div>
        )}

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {currentView === 'board' && (
            <MetricsHeader 
                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
                hiddenColumns={hiddenColumns}
                onToggleColumn={toggleColumnVisibility}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard 
                tasks={tasks} 
                projects={projects} 
                initialProjectId={currentProjectId}
             />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS
                        .filter(col => !hiddenColumns.includes(col.id))
                        .map(col => {
                        // Stable Sort: Position ASC, then CreatedAt ASC
                        const colTasks = filteredTasks
                            .filter(t => t.status === col.id)
                            .sort((a, b) => {
                                const posA = a.position || 0;
                                const posB = b.position || 0;
                                if (posA !== posB) return posA - posB;
                                // Secondary sort for stability
                                return a.createdAt.localeCompare(b.createdAt);
                            });

                        return (
                            <div 
                            key={col.id} 
                            className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                            onDragOver={onDragOver}
                            onDrop={(e) => onDropColumn(e, col.id)}
                            >
                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                                <div className="flex items-center gap-2">
                                <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                    {col.label}
                                </span>
                                <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                    {colTasks.length}
                                </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => toggleColumnVisibility(col.id)}
                                        className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-nexus-cobalt transition-all"
                                        title="Ocultar coluna"
                                    >
                                        <EyeOff size={14} />
                                    </button>
                                    <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {colTasks.map(task => (
                                    <TaskCard 
                                    key={task.id} 
                                    task={task} 
                                    onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                    onDelete={handleDeleteTask}
                                    onDropOnTask={onDropTask}
                                    />
                                ))}

                                {quickAddColumn === col.id ? (
                                    <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                        <textarea
                                            autoFocus 
                                            value={quickAddTitle}
                                            onChange={(e) => setQuickAddTitle(e.target.value)}
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter' && !e.shiftKey) {
                                                    e.preventDefault();
                                                    handleQuickAdd();
                                                }
                                            }}
                                            placeholder="Insira um título para o cartão..."
                                            className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                            >
                                                Adicionar Cartão
                                            </button>
                                            <button 
                                                onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                                className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => setQuickAddColumn(col.id)}
                                        className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                    >
                                        <Plus size={14} /> Adicionar cartão
                                    </button>
                                )}
                            </div>
                            </div>
                        );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'success' 
                ? 'bg-green-500/10 border-green-500/20 text-green-500' 
                : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS, PRESET_TAGS } from './constants';
import { Plus, X, Loader2, CheckCircle2, WifiOff, EyeOff } from 'lucide-react';
import { supabase } from './supabaseClient';

// --- MOCK DATA FOR OFFLINE MODE ---
// Fixed positions to prevent initial collision
const MOCK_PROJECTS: Project[] = [
    { id: 'proj-1', name: 'Plataforma E-commerce', ownerId: 'demo', sharedWith: [] },
    { id: 'proj-2', name: 'Automação Marketing', ownerId: 'demo', sharedWith: [] },
    { id: 'proj-3', name: 'App Mobile Delivery', ownerId: 'demo', sharedWith: [] }
];

const MOCK_TASKS: Task[] = [
    { id: 't1', title: 'Integração Gateway de Pagamento', description: 'Configurar Stripe e webhooks', status: 'inprogress', priority: 'High', progress: 65, tags: [{text: 'Integração API', color: '#22c55e'}], attachments: [], checklist: [{id:'1', text: 'Chaves API', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 10000).toISOString(), assignee: 'demo', position: 1000, coverUrl: 'https://images.unsplash.com/photo-1556742049-0cfed4f7a07d?auto=format&fit=crop&q=80&w=800' },
    { id: 't2', title: 'Design System v2.0', description: 'Atualizar componentes no Figma', status: 'todo', priority: 'Medium', progress: 0, tags: [{text: 'Dashboard', color: '#ec4899'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 8000).toISOString(), assignee: 'demo', position: 2000 },
    { id: 't3', title: 'Setup de CI/CD', description: 'Pipeline no Github Actions', status: 'done', priority: 'High', progress: 100, tags: [{text: 'Infra/Deploy', color: '#ef4444'}], attachments: [], checklist: [{id:'1', text: 'Build script', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 6000).toISOString(), assignee: 'demo', position: 3000 },
    { id: 't4', title: 'Fluxo de Automação de Leads', description: 'Conectar Typeform ao CRM via Make', status: 'inprogress', priority: 'High', progress: 40, tags: [{text: 'Automação (Make/Zapier)', color: '#f97316'}], attachments: [], checklist: [], projectId: 'proj-2', createdAt: new Date(Date.now() - 4000).toISOString(), assignee: 'demo', position: 1000 },
    { id: 't5', title: 'Otimização de Banco de Dados', description: 'Indexação de tabelas críticas', status: 'review', priority: 'Medium', progress: 90, tags: [{text: 'Limpeza/ETL', color: '#06b6d4'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 2000).toISOString(), assignee: 'demo', position: 4000 },
];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);
  const [isOfflineMode, setIsOfflineMode] = useState(false);

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Column Visibility State
  const [hiddenColumns, setHiddenColumns] = useState<Status[]>([]);

  // Filter State
  const [assigneeFilter, setAssigneeFilter] = useState<string | null>(null);

  // Toast State
  const [toast, setToast] = useState<{ visible: boolean; message: string; type: 'success' | 'error' } | null>(null);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
       setUser({ id: activeUsername, username: activeUsername });
    }
  }, []);

  // 2. Fetch Data from Supabase when user is logged in
  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  // Reset filter when project changes
  useEffect(() => {
    setAssigneeFilter(null);
  }, [currentProjectId]);

  // Toast Timer
  useEffect(() => {
    if (toast?.visible) {
      const timer = setTimeout(() => {
        setToast(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ visible: true, message, type });
  };

  const loadMockData = () => {
    console.log("Loading Mock Data for Offline Mode");
    setIsOfflineMode(true);
    setSystemTags(PRESET_TAGS);
    setProjects(MOCK_PROJECTS);
    setTasks(MOCK_TASKS);
    setCurrentProjectId(MOCK_PROJECTS[0].id);
  };

  const fetchData = async () => {
      if (!user) return;
      setIsLoading(true);
      setIsOfflineMode(false);

      try {
          // A. Fetch Tags
          const { data: tagsData, error: tagsError } = await supabase.from('tags').select('*');

          if (tagsError) throw tagsError; // Force catch if DB fails

          if (tagsData && tagsData.length > 0) {
              setSystemTags(tagsData);
          } else {
             await supabase.from('tags').insert(PRESET_TAGS).then(({error}) => {
                 if(!error) setSystemTags(PRESET_TAGS);
                 else setSystemTags(PRESET_TAGS);
             }); 
          }

          // B. Fetch Projects
          const { data: allProjects, error: projectsError } = await supabase.from('projects').select('*');

          if (projectsError) throw projectsError;

          if (allProjects) {
            const myProjects = allProjects.filter((p: any) => 
                p.owner_id === user.id || 
                (Array.isArray(p.shared_with) && p.shared_with.includes(user.username))
            ).map((p: any) => ({
                id: p.id,
                name: p.name,
                ownerId: p.owner_id,
                sharedWith: Array.isArray(p.shared_with) 
                    ? p.shared_with.filter((s: any) => typeof s === 'string') 
                    : []
            }));

            setProjects(myProjects);

            if (myProjects.length > 0) {
                 let activeProject = currentProjectId;
                 if (!activeProject || !myProjects.find(p => p.id === activeProject)) {
                     activeProject = myProjects[0].id;
                     setCurrentProjectId(activeProject);
                 }

                 // C. Fetch Tasks
                 const projectIds = myProjects.map(p => p.id);
                 const { data: tasksData, error: tasksError } = await supabase
                    .from('tasks')
                    .select('*')
                    .in('project_id', projectIds);

                if (tasksError) throw tasksError;

                if (tasksData) {
                    const mappedTasks: Task[] = tasksData.map((t: any, index: number) => ({
                        id: t.id,
                        title: t.title,
                        description: t.description || '',
                        clientName: t.client_name,
                        clientSegment: t.client_segment,
                        objective: t.objective,
                        websiteUrl: t.website_url,
                        projectId: t.project_id,
                        status: t.status,
                        priority: t.priority,
                        progress: t.progress || 0,
                        tags: t.tags || [],
                        attachments: t.attachments || [],
                        checklist: t.checklist || [],
                        dueDate: t.due_date,
                        assignee: typeof t.assignee === 'string' ? t.assignee : undefined,
                        createdAt: t.created_at,
                        // Ensure distinct positions on load if missing or 0
                        position: t.position || (index + 1) * 1000,
                        coverUrl: t.cover_url
                    }));
                    setTasks(mappedTasks);
                }
            } else {
                setTasks([]);
                setCurrentProjectId(null);
            }
          }

      } catch (error) {
          console.error("Error fetching data, falling back to local mode:", error);
          loadMockData();
          showToast("Modo Offline: Dados de exemplo carregados", "error");
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
    setProjects([]);
    setTasks([]);
    setIsOfflineMode(false);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      if (action === 'add') {
         if (!newTags.find(t => t.text === tag.text)) newTags.push(tag);
      } else if (action === 'edit' && oldText) {
         newTags = newTags.map(t => t.text === oldText ? tag : t);
         setTasks(prev => prev.map(t => ({...t, tags: t.tags.map(tt => tt.text === oldText ? tag : tt)})));
      } else if (action === 'delete') {
         newTags = newTags.filter(t => t.text !== tag.text);
      }
      setSystemTags(newTags);

      if (isOfflineMode) return;

      try {
        if (action === 'add') {
           await supabase.from('tags').insert(tag);
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
        }
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

  const handleCreateProject = async (name: string) => {
    if (!user) return;
    const newProject = {
      id: crypto.randomUUID(),
      name,
      owner_id: user.id,
      shared_with: []
    };

    const mappedProject: Project = {
        id: newProject.id,
        name: newProject.name,
        ownerId: newProject.owner_id,
        sharedWith: newProject.shared_with
    };
    setProjects([...projects, mappedProject]);
    setCurrentProjectId(mappedProject.id);
    setCurrentView('board');
    showToast("Projeto criado com sucesso!");

    if (isOfflineMode) return;

    const { error } = await supabase.from('projects').insert(newProject);
    if (error) console.error(error);
  };

  const handleShareProject = async (username: string, taskId?: string) => {
    if (!projectToShare) return;

    let updatedSharedWith = projectToShare.sharedWith;
    if (!updatedSharedWith.includes(username)) {
        updatedSharedWith = [...updatedSharedWith, username];
        const updatedProject = { ...projectToShare, sharedWith: updatedSharedWith };
        setProjects(projects.map(p => p.id === updatedProject.id ? updatedProject : p));
    }
    if (taskId) {
        setTasks(prev => prev.map(t => t.id === taskId ? { ...t, assignee: username } : t));
    }
    showToast("Projeto compartilhado (Local)", "success");

    if (isOfflineMode) return;

    try {
        const { error: projectError } = await supabase
            .from('projects')
            .update({ shared_with: updatedSharedWith })
            .eq('id', projectToShare.id);
        if (projectError) throw projectError;

        if (taskId) {
            const { error: taskError } = await supabase
                .from('tasks')
                .update({ assignee: username })
                .eq('id', taskId);
            if (taskError) throw taskError;
        }
    } catch (error) {
        console.error(error);
        showToast("Erro ao sincronizar compartilhamento", "error");
    }
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
  };

  const handleSaveTask = async (taskData: Task) => {
    if (selectedTask) {
        setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
        setTasks([...tasks, taskData]);
    }
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;

    const dbTask = {
        id: taskData.id,
        project_id: taskData.projectId,
        title: taskData.title,
        description: taskData.description,
        client_name: taskData.clientName,
        client_segment: taskData.clientSegment,
        objective: taskData.objective,
        website_url: taskData.websiteUrl,
        status: taskData.status,
        priority: taskData.priority,
        progress: taskData.progress,
        tags: taskData.tags,
        attachments: taskData.attachments,
        checklist: taskData.checklist,
        due_date: taskData.dueDate,
        assignee: taskData.assignee,
        created_at: taskData.createdAt,
        position: taskData.position,
        cover_url: taskData.coverUrl
    };

    const { error } = await supabase.from('tasks').upsert(dbTask);
    if (error) console.error("Error saving task", error);
  };

  const handleQuickAdd = async () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newId = crypto.randomUUID();
      const columnTasks = tasks.filter(t => t.status === quickAddColumn && t.projectId === currentProjectId);
      const maxPos = columnTasks.length > 0 ? Math.max(...columnTasks.map(t => t.position || 0)) : 0;

      const newTask: Task = {
        id: newId,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString(),
        position: maxPos + 1000
      };

      setTasks([...tasks, newTask]);
      setQuickAddTitle('');
      setQuickAddColumn(null); 

      if (isOfflineMode) return;

      const dbTask = {
        id: newTask.id,
        project_id: newTask.projectId,
        title: newTask.title,
        status: newTask.status,
        priority: newTask.priority,
        created_at: newTask.createdAt,
        position: newTask.position
      };

      const { error } = await supabase.from('tasks').insert(dbTask);
      if (error) console.error(error);
  };

  const handleDeleteTask = async (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;
    const { error } = await supabase.from('tasks').delete().eq('id', id);
    if (error) console.error(error);
  };

  const toggleColumnVisibility = (status: Status) => {
      setHiddenColumns(prev => 
          prev.includes(status) 
          ? prev.filter(s => s !== status) 
          : [...prev, status]
      );
  };

  // --- DRAG AND DROP REORDERING ---
  const handleTaskDrop = async (draggedTaskId: string, targetId: string | null, targetStatus: Status, positionOnTarget: 'before' | 'after' = 'after') => {
      if (!currentProjectId) return;

      const draggedTask = tasks.find(t => t.id === draggedTaskId);
      if (!draggedTask) return;

      // 1. Clean list excluding dragged task
      const otherTasks = tasks.filter(t => t.id !== draggedTaskId);

      // 2. Get target column tasks sorted strictly
      const targetColumnTasks = otherTasks
            .filter(t => t.projectId === currentProjectId && t.status === targetStatus)
            .sort((a, b) => {
                const posA = a.position || 0;
                const posB = b.position || 0;
                if (posA !== posB) return posA - posB;
                return a.createdAt.localeCompare(b.createdAt);
            });

      let newPosition = 0;

      if (!targetId) {
          // Drop on Empty Column or at end
          const lastTask = targetColumnTasks[targetColumnTasks.length - 1];
          newPosition = lastTask ? (lastTask.position || 0) + 1000 : 1000;
      } else {
          // Drop relative to specific task
          const targetIndex = targetColumnTasks.findIndex(t => t.id === targetId);
          if (targetIndex !== -1) {
              const targetTask = targetColumnTasks[targetIndex];
              const targetPos = targetTask.position || 0;

              if (positionOnTarget === 'before') {
                  const prevTask = targetColumnTasks[targetIndex - 1];
                  const prevPos = prevTask ? (prevTask.position || 0) : 0;

                  // If we are placing before the first item, or between two items
                  if (!prevTask) {
                      newPosition = targetPos / 2;
                  } else {
                      newPosition = (targetPos + prevPos) / 2;
                  }
              } else {
                  // After
                  const nextTask = targetColumnTasks[targetIndex + 1];
                  const nextPos = nextTask ? (nextTask.position || 0) : targetPos + 1000;

                  newPosition = (targetPos + nextPos) / 2;
              }
          } else {
              newPosition = 1000;
          }
      }

      // 3. Update State
      const updatedTask = { ...draggedTask, status: targetStatus, position: newPosition };
      setTasks([...otherTasks, updatedTask]);

      // 4. Update Database
      if (!isOfflineMode) {
          await supabase.from('tasks').update({ status: targetStatus, position: newPosition }).eq('id', draggedTaskId);
      }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDropColumn = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    handleTaskDrop(taskId, null, status);
  };

  const onDropTask = (draggedId: string, targetId: string, position: 'before' | 'after') => {
      const targetTask = tasks.find(t => t.id === targetId);
      if (targetTask) {
          handleTaskDrop(draggedId, targetId, targetTask.status, position);
      }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  const uniqueAssignees = Array.from(new Set(
      contextTasks
        .map(t => t.assignee)
        .filter((a): a is string => typeof a === 'string' && a.length > 0)
  ));

  const filteredTasks = assigneeFilter 
      ? contextTasks.filter(t => t.assignee === assigneeFilter) 
      : contextTasks;

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isOfflineMode && (
             <div className="bg-red-500/10 border-b border-red-500/20 text-red-500 text-[10px] font-bold uppercase tracking-widest py-1 text-center flex items-center justify-center gap-2">
                 <WifiOff size={10} /> Modo Offline / Demonstração
             </div>
        )}

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {currentView === 'board' && (
            <MetricsHeader 
                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
                hiddenColumns={hiddenColumns}
                onToggleColumn={toggleColumnVisibility}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard 
                tasks={tasks} 
                projects={projects} 
                initialProjectId={currentProjectId}
             />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS
                        .filter(col => !hiddenColumns.includes(col.id))
                        .map(col => {
                        // Stable Sort: Position ASC, then CreatedAt ASC
                        const colTasks = filteredTasks
                            .filter(t => t.status === col.id)
                            .sort((a, b) => {
                                const posA = a.position || 0;
                                const posB = b.position || 0;
                                if (posA !== posB) return posA - posB;
                                // Secondary sort for stability
                                return a.createdAt.localeCompare(b.createdAt);
                            });

                        return (
                            <div 
                            key={col.id} 
                            className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                            onDragOver={onDragOver}
                            onDrop={(e) => onDropColumn(e, col.id)}
                            >
                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                                <div className="flex items-center gap-2">
                                <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                    {col.label}
                                </span>
                                <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                    {colTasks.length}
                                </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => toggleColumnVisibility(col.id)}
                                        className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-nexus-cobalt transition-all"
                                        title="Ocultar coluna"
                                    >
                                        <EyeOff size={14} />
                                    </button>
                                    <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {colTasks.map(task => (
                                    <TaskCard 
                                    key={task.id} 
                                    task={task} 
                                    onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                    onDelete={handleDeleteTask}
                                    onDropOnTask={onDropTask}
                                    />
                                ))}

                                {quickAddColumn === col.id ? (
                                    <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                        <textarea
                                            autoFocus 
                                            value={quickAddTitle}
                                            onChange={(e) => setQuickAddTitle(e.target.value)}
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter' && !e.shiftKey) {
                                                    e.preventDefault();
                                                    handleQuickAdd();
                                                }
                                            }}
                                            placeholder="Insira um título para o cartão..."
                                            className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                            >
                                                Adicionar Cartão
                                            </button>
                                            <button 
                                                onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                                className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => setQuickAddColumn(col.id)}
                                        className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                    >
                                        <Plus size={14} /> Adicionar cartão
                                    </button>
                                )}
                            </div>
                            </div>
                        );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'success' 
                ? 'bg-green-500/10 border-green-500/20 text-green-500' 
                : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS, PRESET_TAGS } from './constants';
import { Plus, X, Loader2, CheckCircle2, WifiOff, EyeOff } from 'lucide-react';
import { supabase } from './supabaseClient';

// --- MOCK DATA FOR OFFLINE MODE ---
// Fixed positions to prevent initial collision
const MOCK_PROJECTS: Project[] = [
    { id: 'proj-1', name: 'Plataforma E-commerce', ownerId: 'demo', sharedWith: [] },
    { id: 'proj-2', name: 'Automação Marketing', ownerId: 'demo', sharedWith: [] },
    { id: 'proj-3', name: 'App Mobile Delivery', ownerId: 'demo', sharedWith: [] }
];

const MOCK_TASKS: Task[] = [
    { id: 't1', title: 'Integração Gateway de Pagamento', description: 'Configurar Stripe e webhooks', status: 'inprogress', priority: 'High', progress: 65, tags: [{text: 'Integração API', color: '#22c55e'}], attachments: [], checklist: [{id:'1', text: 'Chaves API', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 10000).toISOString(), assignee: 'demo', position: 1000, coverUrl: 'https://images.unsplash.com/photo-1556742049-0cfed4f7a07d?auto=format&fit=crop&q=80&w=800' },
    { id: 't2', title: 'Design System v2.0', description: 'Atualizar componentes no Figma', status: 'todo', priority: 'Medium', progress: 0, tags: [{text: 'Dashboard', color: '#ec4899'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 8000).toISOString(), assignee: 'demo', position: 2000 },
    { id: 't3', title: 'Setup de CI/CD', description: 'Pipeline no Github Actions', status: 'done', priority: 'High', progress: 100, tags: [{text: 'Infra/Deploy', color: '#ef4444'}], attachments: [], checklist: [{id:'1', text: 'Build script', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 6000).toISOString(), assignee: 'demo', position: 3000 },
    { id: 't4', title: 'Fluxo de Automação de Leads', description: 'Conectar Typeform ao CRM via Make', status: 'inprogress', priority: 'High', progress: 40, tags: [{text: 'Automação (Make/Zapier)', color: '#f97316'}], attachments: [], checklist: [], projectId: 'proj-2', createdAt: new Date(Date.now() - 4000).toISOString(), assignee: 'demo', position: 1000 },
    { id: 't5', title: 'Otimização de Banco de Dados', description: 'Indexação de tabelas críticas', status: 'review', priority: 'Medium', progress: 90, tags: [{text: 'Limpeza/ETL', color: '#06b6d4'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 2000).toISOString(), assignee: 'demo', position: 4000 },
];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);
  const [isOfflineMode, setIsOfflineMode] = useState(false);

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Column Visibility State
  const [hiddenColumns, setHiddenColumns] = useState<Status[]>([]);

  // Filter State
  const [assigneeFilter, setAssigneeFilter] = useState<string | null>(null);

  // Toast State
  const [toast, setToast] = useState<{ visible: boolean; message: string; type: 'success' | 'error' } | null>(null);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
       setUser({ id: activeUsername, username: activeUsername });
    }
  }, []);

  // 2. Fetch Data from Supabase when user is logged in
  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  // Reset filter when project changes
  useEffect(() => {
    setAssigneeFilter(null);
  }, [currentProjectId]);

  // Toast Timer
  useEffect(() => {
    if (toast?.visible) {
      const timer = setTimeout(() => {
        setToast(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ visible: true, message, type });
  };

  const loadMockData = () => {
    console.log("Loading Mock Data for Offline Mode");
    setIsOfflineMode(true);
    setSystemTags(PRESET_TAGS);
    setProjects(MOCK_PROJECTS);
    setTasks(MOCK_TASKS);
    setCurrentProjectId(MOCK_PROJECTS[0].id);
  };

  const fetchData = async () => {
      if (!user) return;
      setIsLoading(true);
      setIsOfflineMode(false);

      try {
          // A. Fetch Tags
          const { data: tagsData, error: tagsError } = await supabase.from('tags').select('*');

          if (tagsError) throw tagsError; // Force catch if DB fails

          if (tagsData && tagsData.length > 0) {
              setSystemTags(tagsData);
          } else {
             await supabase.from('tags').insert(PRESET_TAGS).then(({error}) => {
                 if(!error) setSystemTags(PRESET_TAGS);
                 else setSystemTags(PRESET_TAGS);
             }); 
          }

          // B. Fetch Projects
          const { data: allProjects, error: projectsError } = await supabase.from('projects').select('*');

          if (projectsError) throw projectsError;

          if (allProjects) {
            const myProjects = allProjects.filter((p: any) => 
                p.owner_id === user.id || 
                (Array.isArray(p.shared_with) && p.shared_with.includes(user.username))
            ).map((p: any) => ({
                id: p.id,
                name: p.name,
                ownerId: p.owner_id,
                sharedWith: Array.isArray(p.shared_with) 
                    ? p.shared_with.filter((s: any) => typeof s === 'string') 
                    : []
            }));

            setProjects(myProjects);

            if (myProjects.length > 0) {
                 let activeProject = currentProjectId;
                 if (!activeProject || !myProjects.find(p => p.id === activeProject)) {
                     activeProject = myProjects[0].id;
                     setCurrentProjectId(activeProject);
                 }

                 // C. Fetch Tasks
                 const projectIds = myProjects.map(p => p.id);
                 const { data: tasksData, error: tasksError } = await supabase
                    .from('tasks')
                    .select('*')
                    .in('project_id', projectIds);

                if (tasksError) throw tasksError;

                if (tasksData) {
                    const mappedTasks: Task[] = tasksData.map((t: any, index: number) => ({
                        id: t.id,
                        title: t.title,
                        description: t.description || '',
                        clientName: t.client_name,
                        clientSegment: t.client_segment,
                        objective: t.objective,
                        websiteUrl: t.website_url,
                        projectId: t.project_id,
                        status: t.status,
                        priority: t.priority,
                        progress: t.progress || 0,
                        tags: t.tags || [],
                        attachments: t.attachments || [],
                        checklist: t.checklist || [],
                        dueDate: t.due_date,
                        assignee: typeof t.assignee === 'string' ? t.assignee : undefined,
                        createdAt: t.created_at,
                        // Ensure distinct positions on load if missing or 0
                        position: t.position || (index + 1) * 1000,
                        coverUrl: t.cover_url
                    }));
                    setTasks(mappedTasks);
                }
            } else {
                setTasks([]);
                setCurrentProjectId(null);
            }
          }

      } catch (error) {
          console.error("Error fetching data, falling back to local mode:", error);
          loadMockData();
          showToast("Modo Offline: Dados de exemplo carregados", "error");
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
    setProjects([]);
    setTasks([]);
    setIsOfflineMode(false);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      if (action === 'add') {
         if (!newTags.find(t => t.text === tag.text)) newTags.push(tag);
      } else if (action === 'edit' && oldText) {
         newTags = newTags.map(t => t.text === oldText ? tag : t);
         setTasks(prev => prev.map(t => ({...t, tags: t.tags.map(tt => tt.text === oldText ? tag : tt)})));
      } else if (action === 'delete') {
         newTags = newTags.filter(t => t.text !== tag.text);
      }
      setSystemTags(newTags);

      if (isOfflineMode) return;

      try {
        if (action === 'add') {
           await supabase.from('tags').insert(tag);
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
        }
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

  const handleCreateProject = async (name: string) => {
    if (!user) return;
    const newProject = {
      id: crypto.randomUUID(),
      name,
      owner_id: user.id,
      shared_with: []
    };

    const mappedProject: Project = {
        id: newProject.id,
        name: newProject.name,
        ownerId: newProject.owner_id,
        sharedWith: newProject.shared_with
    };
    setProjects([...projects, mappedProject]);
    setCurrentProjectId(mappedProject.id);
    setCurrentView('board');
    showToast("Projeto criado com sucesso!");

    if (isOfflineMode) return;

    const { error } = await supabase.from('projects').insert(newProject);
    if (error) console.error(error);
  };

  const handleShareProject = async (username: string, taskId?: string) => {
    if (!projectToShare) return;

    let updatedSharedWith = projectToShare.sharedWith;
    if (!updatedSharedWith.includes(username)) {
        updatedSharedWith = [...updatedSharedWith, username];
        const updatedProject = { ...projectToShare, sharedWith: updatedSharedWith };
        setProjects(projects.map(p => p.id === updatedProject.id ? updatedProject : p));
    }
    if (taskId) {
        setTasks(prev => prev.map(t => t.id === taskId ? { ...t, assignee: username } : t));
    }
    showToast("Projeto compartilhado (Local)", "success");

    if (isOfflineMode) return;

    try {
        const { error: projectError } = await supabase
            .from('projects')
            .update({ shared_with: updatedSharedWith })
            .eq('id', projectToShare.id);
        if (projectError) throw projectError;

        if (taskId) {
            const { error: taskError } = await supabase
                .from('tasks')
                .update({ assignee: username })
                .eq('id', taskId);
            if (taskError) throw taskError;
        }
    } catch (error) {
        console.error(error);
        showToast("Erro ao sincronizar compartilhamento", "error");
    }
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
  };

  const handleSaveTask = async (taskData: Task) => {
    // Optimistic Update
    if (selectedTask) {
        setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
        setTasks([...tasks, taskData]);
    }
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;

    const dbTask = {
        id: taskData.id,
        project_id: taskData.projectId,
        title: taskData.title,
        description: taskData.description,
        client_name: taskData.clientName,
        client_segment: taskData.clientSegment,
        objective: taskData.objective,
        website_url: taskData.websiteUrl,
        status: taskData.status,
        priority: taskData.priority,
        progress: taskData.progress,
        tags: taskData.tags,
        attachments: taskData.attachments,
        checklist: taskData.checklist,
        due_date: taskData.dueDate,
        assignee: taskData.assignee,
        created_at: taskData.createdAt,
        position: taskData.position,
        cover_url: taskData.coverUrl
    };

    // Attempt to save fully
    const { error } = await supabase.from('tasks').upsert(dbTask);

    if (error) {
        console.error("Error saving task details:", error.message, error.code);

        // Code 42703: Undefined column. Means DB schema is older than code.
        // Fallback: Try saving without the new fields so basic task data persists.
        if (error.code === '42703' || error.message.includes('column')) {
            console.warn("Schema mismatch detected. Retrying without new fields...");
            const legacyTask = { ...dbTask };
            delete (legacyTask as any).cover_url;
            delete (legacyTask as any).client_segment;

            const { error: retryError } = await supabase.from('tasks').upsert(legacyTask);

            if (retryError) {
                console.error("Retry failed:", retryError.message);
                showToast(`Erro ao salvar no servidor: ${retryError.message}`, "error");
            } else {
                showToast("Salvo (Schema desatualizado)", "success");
            }
        } else {
            showToast(`Erro ao salvar: ${error.message}`, "error");
        }
    }
  };

  const handleQuickAdd = async () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newId = crypto.randomUUID();
      const columnTasks = tasks.filter(t => t.status === quickAddColumn && t.projectId === currentProjectId);
      const maxPos = columnTasks.length > 0 ? Math.max(...columnTasks.map(t => t.position || 0)) : 0;

      const newTask: Task = {
        id: newId,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString(),
        position: maxPos + 1000
      };

      setTasks([...tasks, newTask]);
      setQuickAddTitle('');
      setQuickAddColumn(null); 

      if (isOfflineMode) return;

      const dbTask = {
        id: newTask.id,
        project_id: newTask.projectId,
        title: newTask.title,
        status: newTask.status,
        priority: newTask.priority,
        created_at: newTask.createdAt,
        position: newTask.position
      };

      const { error } = await supabase.from('tasks').insert(dbTask);
      if (error) {
          console.error("Error quick adding:", error.message);
          showToast("Erro ao criar cartão rápido", "error");
      }
  };

  const handleDeleteTask = async (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;
    const { error } = await supabase.from('tasks').delete().eq('id', id);
    if (error) console.error(error);
  };

  const toggleColumnVisibility = (status: Status) => {
      setHiddenColumns(prev => 
          prev.includes(status) 
          ? prev.filter(s => s !== status) 
          : [...prev, status]
      );
  };

  // --- DRAG AND DROP REORDERING ---
  const handleTaskDrop = async (draggedTaskId: string, targetId: string | null, targetStatus: Status, positionOnTarget: 'before' | 'after' = 'after') => {
      if (!currentProjectId) return;

      const draggedTask = tasks.find(t => t.id === draggedTaskId);
      if (!draggedTask) return;

      // 1. Clean list excluding dragged task
      const otherTasks = tasks.filter(t => t.id !== draggedTaskId);

      // 2. Get target column tasks sorted strictly
      const targetColumnTasks = otherTasks
            .filter(t => t.projectId === currentProjectId && t.status === targetStatus)
            .sort((a, b) => {
                const posA = a.position || 0;
                const posB = b.position || 0;
                if (posA !== posB) return posA - posB;
                return a.createdAt.localeCompare(b.createdAt);
            });

      let newPosition = 0;

      if (!targetId) {
          // Drop on Empty Column or at end
          const lastTask = targetColumnTasks[targetColumnTasks.length - 1];
          newPosition = lastTask ? (lastTask.position || 0) + 1000 : 1000;
      } else {
          // Drop relative to specific task
          const targetIndex = targetColumnTasks.findIndex(t => t.id === targetId);
          if (targetIndex !== -1) {
              const targetTask = targetColumnTasks[targetIndex];
              const targetPos = targetTask.position || 0;

              if (positionOnTarget === 'before') {
                  const prevTask = targetColumnTasks[targetIndex - 1];
                  const prevPos = prevTask ? (prevTask.position || 0) : 0;

                  // If we are placing before the first item, or between two items
                  if (!prevTask) {
                      newPosition = targetPos / 2;
                  } else {
                      newPosition = (targetPos + prevPos) / 2;
                  }
              } else {
                  // After
                  const nextTask = targetColumnTasks[targetIndex + 1];
                  const nextPos = nextTask ? (nextTask.position || 0) : targetPos + 1000;

                  newPosition = (targetPos + nextPos) / 2;
              }
          } else {
              newPosition = 1000;
          }
      }

      // 3. Update State
      const updatedTask = { ...draggedTask, status: targetStatus, position: newPosition };
      setTasks([...otherTasks, updatedTask]);

      // 4. Update Database
      if (!isOfflineMode) {
          await supabase.from('tasks').update({ status: targetStatus, position: newPosition }).eq('id', draggedTaskId);
      }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDropColumn = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    handleTaskDrop(taskId, null, status);
  };

  const onDropTask = (draggedId: string, targetId: string, position: 'before' | 'after') => {
      const targetTask = tasks.find(t => t.id === targetId);
      if (targetTask) {
          handleTaskDrop(draggedId, targetId, targetTask.status, position);
      }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  const uniqueAssignees = Array.from(new Set(
      contextTasks
        .map(t => t.assignee)
        .filter((a): a is string => typeof a === 'string' && a.length > 0)
  ));

  const filteredTasks = assigneeFilter 
      ? contextTasks.filter(t => t.assignee === assigneeFilter) 
      : contextTasks;

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isOfflineMode && (
             <div className="bg-red-500/10 border-b border-red-500/20 text-red-500 text-[10px] font-bold uppercase tracking-widest py-1 text-center flex items-center justify-center gap-2">
                 <WifiOff size={10} /> Modo Offline / Demonstração
             </div>
        )}

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {currentView === 'board' && (
            <MetricsHeader 
                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
                hiddenColumns={hiddenColumns}
                onToggleColumn={toggleColumnVisibility}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard 
                tasks={tasks} 
                projects={projects} 
                initialProjectId={currentProjectId}
             />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS
                        .filter(col => !hiddenColumns.includes(col.id))
                        .map(col => {
                        // Stable Sort: Position ASC, then CreatedAt ASC
                        const colTasks = filteredTasks
                            .filter(t => t.status === col.id)
                            .sort((a, b) => {
                                const posA = a.position || 0;
                                const posB = b.position || 0;
                                if (posA !== posB) return posA - posB;
                                // Secondary sort for stability
                                return a.createdAt.localeCompare(b.createdAt);
                            });

                        return (
                            <div 
                            key={col.id} 
                            className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                            onDragOver={onDragOver}
                            onDrop={(e) => onDropColumn(e, col.id)}
                            >
                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                                <div className="flex items-center gap-2">
                                <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                    {col.label}
                                </span>
                                <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                    {colTasks.length}
                                </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => toggleColumnVisibility(col.id)}
                                        className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-nexus-cobalt transition-all"
                                        title="Ocultar coluna"
                                    >
                                        <EyeOff size={14} />
                                    </button>
                                    <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {colTasks.map(task => (
                                    <TaskCard 
                                    key={task.id} 
                                    task={task} 
                                    onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                    onDelete={handleDeleteTask}
                                    onDropOnTask={onDropTask}
                                    />
                                ))}

                                {quickAddColumn === col.id ? (
                                    <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                        <textarea
                                            autoFocus 
                                            value={quickAddTitle}
                                            onChange={(e) => setQuickAddTitle(e.target.value)}
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter' && !e.shiftKey) {
                                                    e.preventDefault();
                                                    handleQuickAdd();
                                                }
                                            }}
                                            placeholder="Insira um título para o cartão..."
                                            className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                            >
                                                Adicionar Cartão
                                            </button>
                                            <button 
                                                onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                                className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => setQuickAddColumn(col.id)}
                                        className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                    >
                                        <Plus size={14} /> Adicionar cartão
                                    </button>
                                )}
                            </div>
                            </div>
                        );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'success' 
                ? 'bg-green-500/10 border-green-500/20 text-green-500' 
                : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { MetricsHeader } from './components/MetricsHeader';
import { TaskCard } from './components/TaskCard';
import { TaskModal } from './components/TaskModal';
import { AuthScreen } from './components/AuthScreen';
import { ProjectModal } from './components/ProjectModal';
import { MonitoringDashboard } from './components/MonitoringDashboard';
import { Task, Status, User, Project, Tag } from './types';
import { STATUS_COLUMNS, PRESET_TAGS } from './constants';
import { Plus, X, Loader2, CheckCircle2, WifiOff, EyeOff } from 'lucide-react';
import { supabase } from './supabaseClient';

// --- MOCK DATA FOR OFFLINE MODE ---
// Fixed positions to prevent initial collision
const MOCK_PROJECTS: Project[] = [
    { id: 'proj-1', name: 'Plataforma E-commerce', ownerId: 'demo', sharedWith: [] },
    { id: 'proj-2', name: 'Automação Marketing', ownerId: 'demo', sharedWith: [] },
    { id: 'proj-3', name: 'App Mobile Delivery', ownerId: 'demo', sharedWith: [] }
];

const MOCK_TASKS: Task[] = [
    { id: 't1', title: 'Integração Gateway de Pagamento', description: 'Configurar Stripe e webhooks', status: 'inprogress', priority: 'High', progress: 65, tags: [{text: 'Integração API', color: '#22c55e'}], attachments: [], checklist: [{id:'1', text: 'Chaves API', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 10000).toISOString(), assignee: 'demo', position: 1000, coverUrl: 'https://images.unsplash.com/photo-1556742049-0cfed4f7a07d?auto=format&fit=crop&q=80&w=800' },
    { id: 't2', title: 'Design System v2.0', description: 'Atualizar componentes no Figma', status: 'todo', priority: 'Medium', progress: 0, tags: [{text: 'Dashboard', color: '#ec4899'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 8000).toISOString(), assignee: 'demo', position: 2000 },
    { id: 't3', title: 'Setup de CI/CD', description: 'Pipeline no Github Actions', status: 'done', priority: 'High', progress: 100, tags: [{text: 'Infra/Deploy', color: '#ef4444'}], attachments: [], checklist: [{id:'1', text: 'Build script', checked: true}], projectId: 'proj-1', createdAt: new Date(Date.now() - 6000).toISOString(), assignee: 'demo', position: 3000 },
    { id: 't4', title: 'Fluxo de Automação de Leads', description: 'Conectar Typeform ao CRM via Make', status: 'inprogress', priority: 'High', progress: 40, tags: [{text: 'Automação (Make/Zapier)', color: '#f97316'}], attachments: [], checklist: [], projectId: 'proj-2', createdAt: new Date(Date.now() - 4000).toISOString(), assignee: 'demo', position: 1000 },
    { id: 't5', title: 'Otimização de Banco de Dados', description: 'Indexação de tabelas críticas', status: 'review', priority: 'Medium', progress: 90, tags: [{text: 'Limpeza/ETL', color: '#06b6d4'}], attachments: [], checklist: [], projectId: 'proj-1', createdAt: new Date(Date.now() - 2000).toISOString(), assignee: 'demo', position: 4000 },
];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentProjectId, setCurrentProjectId] = useState<string | null>(null);
  const [systemTags, setSystemTags] = useState<Tag[]>([]);
  const [isOfflineMode, setIsOfflineMode] = useState(false);

  // UI State
  const [isLoading, setIsLoading] = useState(false);
  const [currentView, setCurrentView] = useState<'board' | 'monitoring'>('board');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [projectModalMode, setProjectModalMode] = useState<'create' | 'share'>('create');
  const [projectToShare, setProjectToShare] = useState<Project | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDark, setIsDark] = useState(true);

  // Column Visibility State
  const [hiddenColumns, setHiddenColumns] = useState<Status[]>([]);

  // Filter State
  const [assigneeFilter, setAssigneeFilter] = useState<string | null>(null);

  // Toast State
  const [toast, setToast] = useState<{ visible: boolean; message: string; type: 'success' | 'error' } | null>(null);

  // Quick Add State
  const [quickAddColumn, setQuickAddColumn] = useState<Status | null>(null);
  const [quickAddTitle, setQuickAddTitle] = useState('');

  // 1. Check for persisted user session
  useEffect(() => {
    const activeUsername = localStorage.getItem('luck_active_user');
    if (activeUsername) {
       setUser({ id: activeUsername, username: activeUsername });
    }
  }, []);

  // 2. Fetch Data from Supabase when user is logged in
  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  // Reset filter when project changes
  useEffect(() => {
    setAssigneeFilter(null);
  }, [currentProjectId]);

  // Toast Timer
  useEffect(() => {
    if (toast?.visible) {
      const timer = setTimeout(() => {
        setToast(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ visible: true, message, type });
  };

  const loadMockData = () => {
    console.log("Loading Mock Data for Offline Mode");
    setIsOfflineMode(true);
    setSystemTags(PRESET_TAGS);
    setProjects(MOCK_PROJECTS);
    setTasks(MOCK_TASKS);
    setCurrentProjectId(MOCK_PROJECTS[0].id);
  };

  const fetchData = async () => {
      if (!user) return;
      setIsLoading(true);
      setIsOfflineMode(false);

      try {
          // A. Fetch Tags
          const { data: tagsData, error: tagsError } = await supabase.from('tags').select('*');

          if (tagsError) throw tagsError; // Force catch if DB fails

          if (tagsData && tagsData.length > 0) {
              setSystemTags(tagsData);
          } else {
             await supabase.from('tags').insert(PRESET_TAGS).then(({error}) => {
                 if(!error) setSystemTags(PRESET_TAGS);
                 else setSystemTags(PRESET_TAGS);
             }); 
          }

          // B. Fetch Projects
          const { data: allProjects, error: projectsError } = await supabase.from('projects').select('*');

          if (projectsError) throw projectsError;

          if (allProjects) {
            const myProjects = allProjects.filter((p: any) => 
                p.owner_id === user.id || 
                (Array.isArray(p.shared_with) && p.shared_with.includes(user.username))
            ).map((p: any) => ({
                id: p.id,
                name: p.name,
                ownerId: p.owner_id,
                sharedWith: Array.isArray(p.shared_with) 
                    ? p.shared_with.filter((s: any) => typeof s === 'string') 
                    : []
            }));

            setProjects(myProjects);

            if (myProjects.length > 0) {
                 let activeProject = currentProjectId;
                 if (!activeProject || !myProjects.find(p => p.id === activeProject)) {
                     activeProject = myProjects[0].id;
                     setCurrentProjectId(activeProject);
                 }

                 // C. Fetch Tasks
                 const projectIds = myProjects.map(p => p.id);
                 const { data: tasksData, error: tasksError } = await supabase
                    .from('tasks')
                    .select('*')
                    .in('project_id', projectIds);

                if (tasksError) throw tasksError;

                if (tasksData) {
                    const mappedTasks: Task[] = tasksData.map((t: any, index: number) => ({
                        id: t.id,
                        title: t.title,
                        description: t.description || '',
                        clientName: t.client_name,
                        clientSegment: t.client_segment,
                        objective: t.objective,
                        websiteUrl: t.website_url,
                        projectId: t.project_id,
                        status: t.status,
                        priority: t.priority,
                        progress: t.progress || 0,
                        tags: t.tags || [],
                        attachments: t.attachments || [],
                        checklist: t.checklist || [],
                        dueDate: t.due_date,
                        assignee: typeof t.assignee === 'string' ? t.assignee : undefined,
                        createdAt: t.created_at,
                        // Ensure distinct positions on load if missing or 0
                        position: t.position || (index + 1) * 1000,
                        coverUrl: t.cover_url
                    }));
                    setTasks(mappedTasks);
                }
            } else {
                setTasks([]);
                setCurrentProjectId(null);
            }
          }

      } catch (error) {
          console.error("Error fetching data, falling back to local mode:", error);
          loadMockData();
          showToast("Modo Offline: Dados de exemplo carregados", "error");
      } finally {
          setIsLoading(false);
      }
  };

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('luck_active_user', loggedInUser.username);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('luck_active_user');
    setCurrentProjectId(null);
    setProjects([]);
    setTasks([]);
    setIsOfflineMode(false);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      let newTags = [...systemTags];

      if (action === 'add') {
         if (!newTags.find(t => t.text === tag.text)) newTags.push(tag);
      } else if (action === 'edit' && oldText) {
         newTags = newTags.map(t => t.text === oldText ? tag : t);
         setTasks(prev => prev.map(t => ({...t, tags: t.tags.map(tt => tt.text === oldText ? tag : tt)})));
      } else if (action === 'delete') {
         newTags = newTags.filter(t => t.text !== tag.text);
      }
      setSystemTags(newTags);

      if (isOfflineMode) return;

      try {
        if (action === 'add') {
           await supabase.from('tags').insert(tag);
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
        }
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

  const handleCreateProject = async (name: string) => {
    if (!user) return;
    const newProject = {
      id: crypto.randomUUID(),
      name,
      owner_id: user.id,
      shared_with: []
    };

    const mappedProject: Project = {
        id: newProject.id,
        name: newProject.name,
        ownerId: newProject.owner_id,
        sharedWith: newProject.shared_with
    };
    setProjects([...projects, mappedProject]);
    setCurrentProjectId(mappedProject.id);
    setCurrentView('board');
    showToast("Projeto criado com sucesso!");

    if (isOfflineMode) return;

    const { error } = await supabase.from('projects').insert(newProject);
    if (error) console.error(error);
  };

  const handleShareProject = async (username: string, taskId?: string) => {
    if (!projectToShare) return;

    let updatedSharedWith = projectToShare.sharedWith;
    if (!updatedSharedWith.includes(username)) {
        updatedSharedWith = [...updatedSharedWith, username];
        const updatedProject = { ...projectToShare, sharedWith: updatedSharedWith };
        setProjects(projects.map(p => p.id === updatedProject.id ? updatedProject : p));
    }
    if (taskId) {
        setTasks(prev => prev.map(t => t.id === taskId ? { ...t, assignee: username } : t));
    }
    showToast("Projeto compartilhado (Local)", "success");

    if (isOfflineMode) return;

    try {
        const { error: projectError } = await supabase
            .from('projects')
            .update({ shared_with: updatedSharedWith })
            .eq('id', projectToShare.id);
        if (projectError) throw projectError;

        if (taskId) {
            const { error: taskError } = await supabase
                .from('tasks')
                .update({ assignee: username })
                .eq('id', taskId);
            if (taskError) throw taskError;
        }
    } catch (error) {
        console.error(error);
        showToast("Erro ao sincronizar compartilhamento", "error");
    }
  };

  const handleReorderProjects = (reorderedProjects: Project[]) => {
     setProjects(reorderedProjects);
  };

  const handleSaveTask = async (taskData: Task) => {
    // Optimistic Update
    if (selectedTask) {
        setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
        setTasks([...tasks, taskData]);
    }
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;

    const dbTask = {
        id: taskData.id,
        project_id: taskData.projectId,
        title: taskData.title,
        description: taskData.description,
        client_name: taskData.clientName,
        client_segment: taskData.clientSegment,
        objective: taskData.objective,
        website_url: taskData.websiteUrl,
        status: taskData.status,
        priority: taskData.priority,
        progress: taskData.progress,
        tags: taskData.tags,
        attachments: taskData.attachments,
        checklist: taskData.checklist,
        due_date: taskData.dueDate,
        assignee: taskData.assignee,
        created_at: taskData.createdAt,
        position: taskData.position,
        cover_url: taskData.coverUrl
    };

    // Attempt to save fully
    const { error } = await supabase.from('tasks').upsert(dbTask);

    if (error) {
        console.error("Error saving task details:", error.message, error.code);

        // Code 42703: Undefined column (Postgres)
        // Code PGRST204: Columns not found (PostgREST)
        // Checks if it is a schema mismatch issue
        if (error.code === '42703' || error.code === 'PGRST204' || error.message.includes('column')) {
            console.warn("Schema mismatch detected. Retrying with minimal fields...");

            // Fallback: Try saving without the new fields so basic task data persists.
            // We strip out everything that is likely optional or new.
            const minimalTask = {
                id: dbTask.id,
                project_id: dbTask.project_id,
                title: dbTask.title,
                description: dbTask.description,
                status: dbTask.status,
                priority: dbTask.priority,
                created_at: dbTask.created_at
                // Excluding: position, cover_url, client info, tags, attachments, checklist etc. 
                // as these columns might be missing in the backend.
            };

            const { error: retryError } = await supabase.from('tasks').upsert(minimalTask);

            if (retryError) {
                console.error("Retry failed:", retryError.message);
                showToast(`Erro ao salvar no servidor: ${retryError.message} (Apenas local)`, "error");
            } else {
                showToast("Salvo parcialmente (Banco de dados desatualizado)", "success");
            }
        } else {
            showToast(`Erro ao salvar: ${error.message}`, "error");
        }
    }
  };

  const handleQuickAdd = async () => {
      if (!quickAddTitle.trim() || !currentProjectId || !quickAddColumn) return;

      const newId = crypto.randomUUID();
      const columnTasks = tasks.filter(t => t.status === quickAddColumn && t.projectId === currentProjectId);
      const maxPos = columnTasks.length > 0 ? Math.max(...columnTasks.map(t => t.position || 0)) : 0;

      const newTask: Task = {
        id: newId,
        title: quickAddTitle,
        description: '',
        status: quickAddColumn,
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        projectId: currentProjectId,
        createdAt: new Date().toISOString(),
        position: maxPos + 1000
      };

      setTasks([...tasks, newTask]);
      setQuickAddTitle('');
      setQuickAddColumn(null); 

      if (isOfflineMode) return;

      const dbTask = {
        id: newTask.id,
        project_id: newTask.projectId,
        title: newTask.title,
        status: newTask.status,
        priority: newTask.priority,
        created_at: newTask.createdAt,
        position: newTask.position
      };

      const { error } = await supabase.from('tasks').insert(dbTask);
      if (error) {
          console.error("Error quick adding:", error.message);
          // Try minimal insert if quick add fails due to position/etc
          if (error.code === '42703' || error.code === 'PGRST204') {
             const minimalDbTask = { ...dbTask };
             delete (minimalDbTask as any).position;
             await supabase.from('tasks').insert(minimalDbTask);
          } else {
             showToast("Erro ao criar cartão rápido", "error");
          }
      }
  };

  const handleDeleteTask = async (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
    setIsTaskModalOpen(false);

    if (isOfflineMode) return;
    const { error } = await supabase.from('tasks').delete().eq('id', id);
    if (error) console.error(error);
  };

  const toggleColumnVisibility = (status: Status) => {
      setHiddenColumns(prev => 
          prev.includes(status) 
          ? prev.filter(s => s !== status) 
          : [...prev, status]
      );
  };

  // --- DRAG AND DROP REORDERING ---
  const handleTaskDrop = async (draggedTaskId: string, targetId: string | null, targetStatus: Status, positionOnTarget: 'before' | 'after' = 'after') => {
      if (!currentProjectId) return;

      const draggedTask = tasks.find(t => t.id === draggedTaskId);
      if (!draggedTask) return;

      // 1. Clean list excluding dragged task
      const otherTasks = tasks.filter(t => t.id !== draggedTaskId);

      // 2. Get target column tasks sorted strictly
      const targetColumnTasks = otherTasks
            .filter(t => t.projectId === currentProjectId && t.status === targetStatus)
            .sort((a, b) => {
                const posA = a.position || 0;
                const posB = b.position || 0;
                if (posA !== posB) return posA - posB;
                return a.createdAt.localeCompare(b.createdAt);
            });

      let newPosition = 0;

      if (!targetId) {
          // Drop on Empty Column or at end
          const lastTask = targetColumnTasks[targetColumnTasks.length - 1];
          newPosition = lastTask ? (lastTask.position || 0) + 1000 : 1000;
      } else {
          // Drop relative to specific task
          const targetIndex = targetColumnTasks.findIndex(t => t.id === targetId);
          if (targetIndex !== -1) {
              const targetTask = targetColumnTasks[targetIndex];
              const targetPos = targetTask.position || 0;

              if (positionOnTarget === 'before') {
                  const prevTask = targetColumnTasks[targetIndex - 1];
                  const prevPos = prevTask ? (prevTask.position || 0) : 0;

                  // If we are placing before the first item, or between two items
                  if (!prevTask) {
                      newPosition = targetPos / 2;
                  } else {
                      newPosition = (targetPos + prevPos) / 2;
                  }
              } else {
                  // After
                  const nextTask = targetColumnTasks[targetIndex + 1];
                  const nextPos = nextTask ? (nextTask.position || 0) : targetPos + 1000;

                  newPosition = (targetPos + nextPos) / 2;
              }
          } else {
              newPosition = 1000;
          }
      }

      // 3. Update State
      const updatedTask = { ...draggedTask, status: targetStatus, position: newPosition };
      setTasks([...otherTasks, updatedTask]);

      // 4. Update Database
      if (!isOfflineMode) {
          const { error } = await supabase.from('tasks').update({ status: targetStatus, position: newPosition }).eq('id', draggedTaskId);
          if (error && (error.code === '42703' || error.code === 'PGRST204')) {
              // Fallback for reorder if position missing: just update status
              await supabase.from('tasks').update({ status: targetStatus }).eq('id', draggedTaskId);
          }
      }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDropColumn = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    handleTaskDrop(taskId, null, status);
  };

  const onDropTask = (draggedId: string, targetId: string, position: 'before' | 'after') => {
      const targetTask = tasks.find(t => t.id === targetId);
      if (targetTask) {
          handleTaskDrop(draggedId, targetId, targetTask.status, position);
      }
  };

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  const uniqueAssignees = Array.from(new Set(
      contextTasks
        .map(t => t.assignee)
        .filter((a): a is string => typeof a === 'string' && a.length > 0)
  ));

  const filteredTasks = assigneeFilter 
      ? contextTasks.filter(t => t.assignee === assigneeFilter) 
      : contextTasks;

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isOfflineMode && (
             <div className="bg-red-500/10 border-b border-red-500/20 text-red-500 text-[10px] font-bold uppercase tracking-widest py-1 text-center flex items-center justify-center gap-2">
                 <WifiOff size={10} /> Modo Offline / Demonstração
             </div>
        )}

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {currentView === 'board' && (
            <MetricsHeader 
                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
                hiddenColumns={hiddenColumns}
                onToggleColumn={toggleColumnVisibility}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard 
                tasks={tasks} 
                projects={projects} 
                initialProjectId={currentProjectId}
             />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS
                        .filter(col => !hiddenColumns.includes(col.id))
                        .map(col => {
                        // Stable Sort: Position ASC, then CreatedAt ASC
                        const colTasks = filteredTasks
                            .filter(t => t.status === col.id)
                            .sort((a, b) => {
                                const posA = a.position || 0;
                                const posB = b.position || 0;
                                if (posA !== posB) return posA - posB;
                                // Secondary sort for stability
                                return a.createdAt.localeCompare(b.createdAt);
                            });

                        return (
                            <div 
                            key={col.id} 
                            className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                            onDragOver={onDragOver}
                            onDrop={(e) => onDropColumn(e, col.id)}
                            >
                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                                <div className="flex items-center gap-2">
                                <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                    {col.label}
                                </span>
                                <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                    {colTasks.length}
                                </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => toggleColumnVisibility(col.id)}
                                        className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-nexus-cobalt transition-all"
                                        title="Ocultar coluna"
                                    >
                                        <EyeOff size={14} />
                                    </button>
                                    <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {colTasks.map(task => (
                                    <TaskCard 
                                    key={task.id} 
                                    task={task} 
                                    onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                    onDelete={handleDeleteTask}
                                    onDropOnTask={onDropTask}
                                    />
                                ))}

                                {quickAddColumn === col.id ? (
                                    <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                        <textarea
                                            autoFocus 
                                            value={quickAddTitle}
                                            onChange={(e) => setQuickAddTitle(e.target.value)}
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter' && !e.shiftKey) {
                                                    e.preventDefault();
                                                    handleQuickAdd();
                                                }
                                            }}
                                            placeholder="Insira um título para o cartão..."
                                            className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                            >
                                                Adicionar Cartão
                                            </button>
                                            <button 
                                                onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                                className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => setQuickAddColumn(col.id)}
                                        className="w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1"
                                    >
                                        <Plus size={14} /> Adicionar cartão
                                    </button>
                                )}
                            </div>
                            </div>
                        );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'success' 
                ? 'bg-green-500/10 border-green-500/20 text-green-500' 
                : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag, ChecklistItem } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target, Calendar, CheckSquare, User, Edit2, Clock, PanelRightClose, Image as ImageIcon, Link as LinkIcon } from 'lucide-react';
import { STATUS_COLUMNS, PRESET_SEGMENTS } from '../constants';
import { ImageGalleryModal } from './ImageGalleryModal';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
  availableTags: Tag[];
  onManageTags: (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => void;
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ 
    task, 
    isOpen, 
    onClose, 
    onSave, 
    onDelete, 
    currentProjectId,
    availableTags,
    onManageTags
}) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    clientSegment: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
    checklist: [],
    dueDate: '',
    assignee: '',
    coverUrl: ''
  });

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); 
  const [checklistInput, setChecklistInput] = useState('');

  // State for cover inputs
  const [showCoverUrlInput, setShowCoverUrlInput] = useState(false);
  const [coverUrlInput, setCoverUrlInput] = useState('');

  // State for editing tags mode
  const [editingTag, setEditingTag] = useState<string | null>(null);

  // Gallery State
  const [isGalleryOpen, setIsGalleryOpen] = useState(false);
  const [galleryStartIndex, setGalleryStartIndex] = useState(0);

  // Auto-calculate progress whenever checklist changes
  useEffect(() => {
    if (formData.checklist) {
        const total = formData.checklist.length;
        const checked = formData.checklist.filter(i => i.checked).length;
        const newProgress = total === 0 ? 0 : Math.round((checked / total) * 100);

        if (newProgress !== formData.progress) {
            setFormData(prev => ({ ...prev, progress: newProgress }));
        }
    }
  }, [formData.checklist]);

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        clientSegment: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        dueDate: '',
        assignee: '',
        projectId: currentProjectId,
        coverUrl: ''
      });
    }
    setShowCoverUrlInput(false);
    setCoverUrlInput('');
  }, [task, isOpen, currentProjectId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const handleCoverFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          // Use FileReader to convert to Base64
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64String = reader.result as string;
              setFormData(prev => ({ ...prev, coverUrl: base64String }));
          };
          reader.readAsDataURL(file);
      }
  };

  const handleCoverUrlSubmit = () => {
      if (coverUrlInput.trim()) {
          setFormData(prev => ({ ...prev, coverUrl: coverUrlInput.trim() }));
          setShowCoverUrlInput(false);
          setCoverUrlInput('');
      }
  };

  const removeAttachment = (id: string) => {
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  // Helper to open gallery
  const imageAttachments = formData.attachments?.filter(a => a.type === 'image') || [];

  const handleImageClick = (attId: string) => {
      const index = imageAttachments.findIndex(a => a.id === attId);
      if (index !== -1) {
          setGalleryStartIndex(index);
          setIsGalleryOpen(true);
      }
  };

  const addTagToTask = (tag: Tag) => {
      if (!formData.tags?.find(t => t.text === tag.text)) {
          setFormData(prev => ({
              ...prev,
              tags: [...(prev.tags || []), tag]
          }));
      }
  };

  const createNewTag = () => {
      const tagName = tagInput.trim();
      if (tagName) {
          const newTag = { text: tagName, color: selectedTagColor };
          // Add to global list
          onManageTags('add', newTag);
          // Add to this task
          addTagToTask(newTag);
          setTagInput('');
      }
  };

  const removeTagFromTask = (textToRemove: string) => {
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  const addChecklistItem = () => {
      if (checklistInput.trim()) {
          const newItem: ChecklistItem = {
              id: Date.now().toString(),
              text: checklistInput.trim(),
              checked: false,
              dueDate: ''
          };
          setFormData(prev => ({
              ...prev,
              checklist: [...(prev.checklist || []), newItem]
          }));
          setChecklistInput('');
      }
  };

  const toggleChecklistItem = (id: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
          )
      }));
  };

  const updateChecklistItemText = (id: string, newText: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, text: newText } : item
          )
      }));
  };

  const updateChecklistItemDate = (id: string, date: string) => {
    setFormData(prev => ({
        ...prev,
        checklist: prev.checklist?.map(item => 
          item.id === id ? { ...item, dueDate: date } : item
        )
    }));
  };

  const deleteChecklistItem = (id: string) => {
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  if (!isOpen) return null;

  return (
    <>
    {/* Fixed: pointer-events-none on parent allows clicking/scrolling the board behind. */}
    <div className="fixed inset-0 z-50 flex justify-end pointer-events-none">

      {/* Fixed: Set width to 50% (w-1/2) on desktop (md) and full width on mobile. */}
      <div className="pointer-events-auto w-full md:w-1/2 h-full bg-nexus-card border-l border-nexus-border shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        {/* Header */}
        <div className="flex justify-between items-start p-6 border-b border-nexus-border bg-nexus-bg/50 flex-shrink-0">
          <div className="flex-1 mr-4">
             <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-transparent border-none text-xl font-bold text-nexus-text focus:ring-0 outline-none p-0 placeholder-nexus-muted"
                  placeholder="Nome do Cartão..."
            />
            <div className="text-xs text-nexus-muted mt-1 flex gap-2">
                <span>em lista <strong>{STATUS_COLUMNS.find(c => c.id === formData.status)?.label}</strong></span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
                onClick={onClose} 
                className="p-2 text-nexus-muted hover:text-nexus-text hover:bg-nexus-bg rounded transition-colors"
                title="Fechar painel"
            >
                <PanelRightClose size={20} />
            </button>
          </div>
        </div>

        {/* Content - Two Column Layout */}
        <div className="flex-1 overflow-y-auto p-6 flex gap-6 custom-scrollbar">

          {/* LEFT COLUMN (Main Content) */}
          <div className="flex-1 space-y-8 pb-12">

              {/* Cover Image Section */}
              <div className="space-y-3">
                 {formData.coverUrl ? (
                     <div className="relative w-full h-48 rounded-lg overflow-hidden group bg-nexus-bg border border-nexus-border">
                         <img src={formData.coverUrl} alt="Cover" className="w-full h-full object-cover" />
                         <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3">
                             <button 
                                onClick={() => setFormData(prev => ({...prev, coverUrl: undefined}))}
                                className="px-3 py-1.5 bg-red-500/80 hover:bg-red-500 text-white text-xs font-bold rounded backdrop-blur-sm transition-colors"
                             >
                                 Remover
                             </button>
                         </div>
                     </div>
                 ) : (
                     <div className="flex flex-col gap-2">
                        {!showCoverUrlInput ? (
                            <div className="flex gap-2">
                                <label className="flex items-center gap-2 px-3 py-2 bg-nexus-bg hover:bg-nexus-border border border-nexus-border rounded cursor-pointer transition-colors text-xs font-bold text-nexus-muted hover:text-nexus-text">
                                    <ImageIcon size={14} /> Upload Capa
                                    <input type="file" className="hidden" accept="image/*" onChange={handleCoverFileChange} />
                                </label>
                                <button 
                                    onClick={() => setShowCoverUrlInput(true)}
                                    className="flex items-center gap-2 px-3 py-2 bg-nexus-bg hover:bg-nexus-border border border-nexus-border rounded cursor-pointer transition-colors text-xs font-bold text-nexus-muted hover:text-nexus-text"
                                >
                                    <LinkIcon size={14} /> Link da Imagem
                                </button>
                            </div>
                        ) : (
                            <div className="flex gap-2 animate-in fade-in duration-200">
                                <input 
                                    type="text" 
                                    value={coverUrlInput}
                                    onChange={(e) => setCoverUrlInput(e.target.value)}
                                    className="flex-1 bg-nexus-bg border border-nexus-border rounded px-3 py-1.5 text-sm outline-none focus:border-nexus-cobalt"
                                    placeholder="https://exemplo.com/imagem.png"
                                    autoFocus
                                    onKeyDown={(e) => e.key === 'Enter' && handleCoverUrlSubmit()}
                                />
                                <button onClick={handleCoverUrlSubmit} className="bg-nexus-cobalt text-white px-3 py-1 rounded text-xs font-bold">OK</button>
                                <button onClick={() => { setShowCoverUrlInput(false); setCoverUrlInput(''); }} className="bg-nexus-card border border-nexus-border text-nexus-text px-3 py-1 rounded text-xs"><X size={14}/></button>
                            </div>
                        )}
                     </div>
                 )}
              </div>

              {/* Description */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                    <FileText size={16} className="text-nexus-cobalt" />
                    <h3>Descrição</h3>
                </div>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
