import React from 'react';
import { User } from '../types';
import { Shield, Check, X, UserCog } from 'lucide-react';
import { ROLES_CONFIG } from '../constants';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: User;
  onUpdateRole: (role: 'admin' | 'editor' | 'viewer') => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose, user, onUpdateRole }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[500px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">

        <div className="flex justify-between items-center p-6 border-b border-nexus-border bg-nexus-bg/50">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 rounded-full bg-nexus-cobalt flex items-center justify-center text-white font-bold text-lg">
                {user.username.charAt(0).toUpperCase()}
             </div>
             <div>
                 <h2 className="text-lg font-bold text-nexus-text tracking-tight">{user.username}</h2>
                 <p className="text-xs text-nexus-muted uppercase tracking-wider">Configuração de Perfil e Acesso</p>
             </div>
          </div>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-6">
           <div className="bg-nexus-accent/10 border border-nexus-accent/20 rounded p-4 flex gap-3">
               <Shield className="text-nexus-accent flex-shrink-0" size={20} />
               <div className="text-sm">
                   <p className="font-bold text-nexus-text mb-1">Simulação de Níveis de Acesso</p>
                   <p className="text-nexus-muted text-xs leading-relaxed">
                       Selecione um nível abaixo para testar as permissões do sistema em tempo real.
                       Em produção, isso seria gerido pelo administrador da organização.
                   </p>
               </div>
           </div>

           <div className="space-y-3">
               {(Object.keys(ROLES_CONFIG) as Array<keyof typeof ROLES_CONFIG>).map((roleKey) => {
                   const config = ROLES_CONFIG[roleKey];
                   const isSelected = user.role === roleKey;

                   return (
                       <button
                           key={roleKey}
                           onClick={() => onUpdateRole(roleKey)}
                           className={`w-full flex items-center justify-between p-4 rounded-lg border transition-all ${
                               isSelected 
                               ? 'bg-nexus-cobalt/10 border-nexus-cobalt ring-1 ring-nexus-cobalt' 
                               : 'bg-nexus-bg border-nexus-border hover:border-nexus-muted'
                           }`}
                       >
                           <div className="flex items-center gap-4">
                               <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${isSelected ? 'border-nexus-cobalt bg-nexus-cobalt' : 'border-nexus-muted'}`}>
                                   {isSelected && <Check size={12} className="text-white" />}
                               </div>
                               <div className="text-left">
                                   <div className={`font-bold text-sm ${isSelected ? 'text-nexus-cobalt' : 'text-nexus-text'}`}>
                                       {config.label}
                                   </div>
                                   <div className="flex gap-2 mt-1">
                                       {config.permissions.map(p => (
                                           <span key={p} className="text-[10px] px-1.5 py-0.5 rounded bg-nexus-card border border-nexus-border text-nexus-muted uppercase tracking-wider">
                                               {p}
                                           </span>
                                       ))}
                                   </div>
                               </div>
                           </div>
                           {roleKey === 'admin' && <UserCog size={18} className="text-nexus-muted opacity-50" />}
                       </button>
                   );
               })}
           </div>
        </div>

        <div className="p-4 border-t border-nexus-border bg-nexus-bg/30 text-center">
            <button onClick={onClose} className="text-xs font-bold text-nexus-muted hover:text-nexus-text transition-colors uppercase tracking-widest">
                Fechar
            </button>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { LayoutGrid, Folder, Plus, Activity, Sun, Moon, LogOut, Share2, GripVertical, User as UserIcon, Users, Settings } from 'lucide-react';
import { Project, User } from '../types';
import { ROLES_CONFIG } from '../constants';

interface SidebarProps {
  projects: Project[];
  currentProjectId: string | null;
  setProjectId: (id: string) => void;
  onNewProject: () => void;
  onShareProject: (project: Project) => void;
  onReorderProjects: (projects: Project[]) => void;
  user: User;
  onLogout: () => void;
  isDark: boolean;
  toggleTheme: () => void;
  currentView: 'board' | 'monitoring';
  setView: (view: 'board' | 'monitoring') => void;
  onOpenProfile: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  projects, 
  currentProjectId, 
  setProjectId, 
  onNewProject,
  onShareProject,
  onReorderProjects,
  user,
  onLogout,
  isDark,
  toggleTheme,
  currentView,
  setView,
  onOpenProfile
}) => {
  const [draggedProject, setDraggedProject] = useState<Project | null>(null);

  // Group Projects
  const myProjects = projects.filter(p => p.ownerId === user.id);
  const sharedProjects = projects.filter(p => p.ownerId !== user.id);

  // Find current project object
  const selectedProject = projects.find(p => p.id === currentProjectId);

  const handleDragStart = (e: React.DragEvent, project: Project) => {
    setDraggedProject(project);
    e.dataTransfer.effectAllowed = 'move';
    // Only allow reordering within "My Projects" for now to simplify
    if (project.ownerId !== user.id) {
       e.preventDefault();
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, targetProject: Project) => {
    e.preventDefault();
    if (!draggedProject || draggedProject.id === targetProject.id) return;

    // Simple reorder logic for "My Projects"
    if (draggedProject.ownerId === user.id && targetProject.ownerId === user.id) {
        const newOrder = [...projects];
        const draggedIdx = newOrder.findIndex(p => p.id === draggedProject.id);
        const targetIdx = newOrder.findIndex(p => p.id === targetProject.id);

        // Remove and insert
        newOrder.splice(draggedIdx, 1);
        newOrder.splice(targetIdx, 0, draggedProject);

        onReorderProjects(newOrder);
    }
    setDraggedProject(null);
  };

  const renderProjectItem = (item: Project, isShared: boolean) => (
    <div 
        key={item.id} 
        className={`group relative flex items-center ${!isShared ? 'cursor-grab active:cursor-grabbing' : ''}`}
        draggable={!isShared}
        onDragStart={(e) => handleDragStart(e, item)}
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, item)}
    >
      {!isShared && (
        <div className="absolute left-1 opacity-0 group-hover:opacity-100 text-nexus-muted cursor-grab">
            <GripVertical size={12} />
        </div>
      )}
      <button
        onClick={() => { setProjectId(item.id); setView('board'); }}
        className={`flex-1 flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all duration-200 ml-2 ${
          currentProjectId === item.id && currentView === 'board'
            ? 'bg-nexus-card text-nexus-cobalt border-l-2 border-nexus-cobalt shadow-sm'
            : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
        }`}
      >
        <Folder size={16} className={`${currentProjectId === item.id && currentView === 'board' ? 'text-nexus-cobalt' : 'text-nexus-muted'}`} />
        <span className="truncate max-w-[140px]">{item.name}</span>
        {isShared && (
            <span className="text-[9px] bg-nexus-border px-1 rounded text-nexus-muted ml-auto">
                Shared
            </span>
        )}
      </button>
    </div>
  );

  return (
    <aside className="w-64 h-screen bg-nexus-bg border-r border-nexus-border flex flex-col flex-shrink-0 z-20 transition-colors duration-300">
      <div className="h-16 flex items-center px-6 border-b border-nexus-border">
        <div 
            onClick={() => setView('board')}
            className="flex items-center gap-3 text-nexus-text font-bold tracking-tight cursor-pointer hover:opacity-80 transition-opacity"
        >
          <div className="w-8 h-8 bg-nexus-cobalt rounded-sm flex items-center justify-center flex-shrink-0">
             <LayoutGrid size={16} className="text-white" />
          </div>
          <span className="font-mono text-[10px] leading-tight font-bold">PAINEL DE<br/>ACOMPANHAMENTO</span>
        </div>
      </div>

      <div className="flex-1 py-6 px-3 space-y-4 overflow-y-auto">

        <div className="space-y-2">
            {/* New Project Button - Only for Admin/Editors ideally, but let's keep unrestricted for structure, controlled by logic */}
            <button 
                onClick={onNewProject} 
                className="w-full flex items-center justify-center gap-2 py-2 border border-dashed border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors"
            >
                <Plus size={14} /> Novo Projeto
            </button>

            {/* Share Current Project Button (Contextual) */}
            {selectedProject && selectedProject.ownerId === user.id && (
                <button 
                    onClick={() => onShareProject(selectedProject)}
                    className="w-full flex items-center justify-center gap-2 py-2 bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors shadow-sm"
                >
                    <Share2 size={14} /> Compartilhar Projeto
                </button>
            )}
        </div>

        {/* My Projects Section */}
        <div>
            <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                <UserIcon size={12} />
                <span>Meus Projetos</span>
            </div>
            <div className="space-y-0.5">
                {myProjects.length > 0 ? (
                    myProjects.map(p => renderProjectItem(p, false))
                ) : (
                    <div className="px-5 py-2 text-xs text-nexus-muted italic opacity-50">Vazio</div>
                )}
            </div>
        </div>

        {/* Shared Projects Section */}
        {sharedProjects.length > 0 && (
            <div>
                <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                    <Users size={12} />
                    <span>Compartilhados</span>
                </div>
                <div className="space-y-0.5">
                    {sharedProjects.map(p => renderProjectItem(p, true))}
                </div>
            </div>
        )}

        <div className="pt-4 mt-4 border-t border-nexus-border/50">
            <div className="px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">SISTEMA</div>
            <button 
                onClick={() => setView('monitoring')}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${
                    currentView === 'monitoring' 
                    ? 'bg-nexus-card text-nexus-accent border-l-2 border-nexus-accent' 
                    : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
                }`}
            >
            <Activity size={18} />
            <span>Monitoramento</span>
            </button>
        </div>
      </div>

      <div className="p-4 border-t border-nexus-border space-y-4">
        <div className="flex items-center justify-between px-2">
           <span className="text-xs text-nexus-muted font-medium">Tema</span>
           <button 
             onClick={toggleTheme}
             className="p-2 rounded-full bg-nexus-card hover:bg-nexus-hover text-nexus-text border border-nexus-border transition-colors"
           >
             {isDark ? <Sun size={14} /> : <Moon size={14} />}
           </button>
        </div>

        <div 
            onClick={onOpenProfile}
            className="flex items-center gap-3 px-2 pt-2 border-t border-nexus-border cursor-pointer group hover:bg-nexus-card/50 rounded-md p-2 transition-colors"
        >
          <div className="w-8 h-8 rounded bg-gradient-to-br from-nexus-cobalt to-purple-600 flex items-center justify-center text-xs font-bold text-white uppercase relative">
            {String(user.username || '').substring(0, 2)}
            <div className="absolute -bottom-1 -right-1 bg-nexus-card rounded-full p-0.5 border border-nexus-border">
                 <Settings size={8} className="text-nexus-muted" />
            </div>
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            <span className="text-xs font-medium text-nexus-text truncate">{String(user.username)}</span>
            <span className="text-[9px] text-nexus-muted font-mono flex items-center gap-1">
                {ROLES_CONFIG[user.role].label}
            </span>
          </div>
          <button onClick={(e) => { e.stopPropagation(); onLogout(); }} className="text-nexus-muted hover:text-red-500 transition-colors" title="Sair">
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </aside>
  );
};

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag, ChecklistItem, User } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target, Calendar, CheckSquare, User as UserIcon, Edit2, Clock, PanelRightClose, Lock } from 'lucide-react';
import { STATUS_COLUMNS, PRESET_SEGMENTS } from '../constants';
import { ImageGalleryModal } from './ImageGalleryModal';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
  availableTags: Tag[];
  onManageTags: (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => void;
  userRole: User['role'];
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ 
    task, 
    isOpen, 
    onClose, 
    onSave, 
    onDelete, 
    currentProjectId,
    availableTags,
    onManageTags,
    userRole
}) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    clientSegment: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
    checklist: [],
    dueDate: '',
    assignee: '',
    coverUrl: ''
  });

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); 
  const [checklistInput, setChecklistInput] = useState('');

  // State for editing tags mode
  const [editingTag, setEditingTag] = useState<string | null>(null);

  // Gallery State
  const [isGalleryOpen, setIsGalleryOpen] = useState(false);
  const [galleryStartIndex, setGalleryStartIndex] = useState(0);

  // PERMISSION CHECK
  const isReadOnly = userRole === 'viewer';
  const canDelete = userRole === 'admin';

  // Auto-calculate progress whenever checklist changes
  useEffect(() => {
    if (formData.checklist) {
        const total = formData.checklist.length;
        const checked = formData.checklist.filter(i => i.checked).length;
        const newProgress = total === 0 ? 0 : Math.round((checked / total) * 100);

        if (newProgress !== formData.progress) {
            setFormData(prev => ({ ...prev, progress: newProgress }));
        }
    }
  }, [formData.checklist]);

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        clientSegment: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        dueDate: '',
        assignee: '',
        projectId: currentProjectId,
        coverUrl: ''
      });
    }
  }, [task, isOpen, currentProjectId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isReadOnly) return;
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  // Helper to open gallery
  const imageAttachments = formData.attachments?.filter(a => a.type === 'image') || [];

  const handleImageClick = (attId: string) => {
      const index = imageAttachments.findIndex(a => a.id === attId);
      if (index !== -1) {
          setGalleryStartIndex(index);
          setIsGalleryOpen(true);
      }
  };

  const addTagToTask = (tag: Tag) => {
      if (isReadOnly) return;
      if (!formData.tags?.find(t => t.text === tag.text)) {
          setFormData(prev => ({
              ...prev,
              tags: [...(prev.tags || []), tag]
          }));
      }
  };

  const createNewTag = () => {
      if (isReadOnly) return;
      const tagName = tagInput.trim();
      if (tagName) {
          const newTag = { text: tagName, color: selectedTagColor };
          // Add to global list
          onManageTags('add', newTag);
          // Add to this task
          addTagToTask(newTag);
          setTagInput('');
      }
  };

  const removeTagFromTask = (textToRemove: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  const addChecklistItem = () => {
      if (isReadOnly) return;
      if (checklistInput.trim()) {
          const newItem: ChecklistItem = {
              id: Date.now().toString(),
              text: checklistInput.trim(),
              checked: false,
              dueDate: ''
          };
          setFormData(prev => ({
              ...prev,
              checklist: [...(prev.checklist || []), newItem]
          }));
          setChecklistInput('');
      }
  };

  const toggleChecklistItem = (id: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
          )
      }));
  };

  const updateChecklistItemText = (id: string, newText: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, text: newText } : item
          )
      }));
  };

  const updateChecklistItemDate = (id: string, date: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({
        ...prev,
        checklist: prev.checklist?.map(item => 
          item.id === id ? { ...item, dueDate: date } : item
        )
    }));
  };

  const deleteChecklistItem = (id: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  if (!isOpen) return null;

  return (
    <>
    {/* Fixed: pointer-events-none on parent allows clicking/scrolling the board behind. */}
    <div className="fixed inset-0 z-50 flex justify-end pointer-events-none">

      {/* Fixed: Set width to 50% (w-1/2) on desktop (md) and full width on mobile. */}
      <div className="pointer-events-auto w-full md:w-1/2 h-full bg-nexus-card border-l border-nexus-border shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        {/* Header */}
        <div className="flex justify-between items-start p-6 border-b border-nexus-border bg-nexus-bg/50 flex-shrink-0">
          <div className="flex-1 mr-4">
             <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-transparent border-none text-xl font-bold text-nexus-text focus:ring-0 outline-none p-0 placeholder-nexus-muted"
                  placeholder="Nome do Cartão..."
                  readOnly={isReadOnly}
            />
            <div className="text-xs text-nexus-muted mt-1 flex gap-2">
                <span>em lista <strong>{STATUS_COLUMNS.find(c => c.id === formData.status)?.label}</strong></span>
                {isReadOnly && <span className="flex items-center gap-1 text-nexus-muted border border-nexus-border px-1.5 rounded bg-nexus-bg"><Lock size={10} /> Somente Leitura</span>}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
                onClick={onClose} 
                className="p-2 text-nexus-muted hover:text-nexus-text hover:bg-nexus-bg rounded transition-colors"
                title="Fechar painel"
            >
                <PanelRightClose size={20} />
            </button>
          </div>
        </div>

        {/* Content - Two Column Layout */}
        <div className="flex-1 overflow-y-auto p-6 flex gap-6 custom-scrollbar">

          {/* LEFT COLUMN (Main Content) */}
          <div className="flex-1 space-y-8 pb-12">

              {/* Description */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                    <FileText size={16} className="text-nexus-cobalt" />
                    <h3>Descrição</h3>
                </div>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={6}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none leading-relaxed text-sm read-only:opacity-60"
                  placeholder="Adicionar descrição detalhada..."
                  readOnly={isReadOnly}
                />
              </div>

              {/* Checklist */}
              <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                      <CheckSquare size={16} className="text-nexus-cobalt" />
                      <h3>Checklist</h3>
                  </div>

                  {/* Progress Bar */}
                  {formData.checklist && formData.checklist.length > 0 && (
                      <div className="flex items-center gap-2 mb-2">
                          <span className="text-xs text-nexus-muted w-8 text-right font-mono">
                              {Math.round((formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100)}%
                          </span>
                          <div className="flex-1 h-1.5 bg-nexus-bg rounded-full overflow-hidden">
                              <div 
                                className="h-full bg-nexus-cobalt transition-all duration-300 ease-out" 
                                style={{ width: `${(formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100}%` }}
                              ></div>
                          </div>
                      </div>
                  )}

                  <div className="space-y-2">
                      {formData.checklist?.map(item => (
                          <div key={item.id} className="flex flex-col gap-1 border-b border-nexus-border/50 pb-2 mb-2 last:border-0 last:mb-0 last:pb-0 group/item">
                             <div className="flex items-center gap-3">
                                <input 
                                    type="checkbox" 
                                    checked={item.checked} 
                                    onChange={() => toggleChecklistItem(item.id)}
                                    className="w-4 h-4 rounded border-nexus-border bg-nexus-bg checked:bg-nexus-cobalt cursor-pointer flex-shrink-0 disabled:opacity-50"
                                    disabled={isReadOnly}
                                />
                                <input 
                                    type="text"
                                    value={item.text}
                                    onChange={(e) => updateChecklistItemText(item.id, e.target.value)}
                                    className={`flex-1 text-sm bg-transparent outline-none border-b border-transparent focus:border-nexus-cobalt transition-all ${item.checked ? 'line-through text-nexus-muted' : 'text-nexus-text'}`}
                                    readOnly={isReadOnly}
                                />
                                {!isReadOnly && (
                                    <button onClick={() => deleteChecklistItem(item.id)} className="opacity-0 group-hover/item:opacity-100 text-nexus-muted hover:text-red-500 transition-opacity p-1">
                                        <X size={14} />
                                    </button>
                                )}
                             </div>

                             {/* Date for checklist item */}
                             <div className="pl-7">
                                <input 
                                    type="datetime-local" 
                                    value={item.dueDate || ''}
                                    onChange={(e) => updateChecklistItemDate(item.id, e.target.value)}
                                    className="text-[10px] bg-transparent text-nexus-muted border-none hover:bg-nexus-bg rounded px-1.5 py-0.5 outline-none focus:text-nexus-cobalt transition-colors cursor-pointer disabled:opacity-50"
                                    disabled={isReadOnly}
                                />
                             </div>
                          </div>
                      ))}
                      {!isReadOnly && (
                          <div className="flex gap-2 mt-2 pl-7">
                              <input 
                                type="text" 
                                value={checklistInput}
                                onChange={(e) => setChecklistInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && addChecklistItem()}
                                className="flex-1 bg-nexus-bg border border-nexus-border rounded px-3 py-1.5 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                placeholder="Adicionar item..."
                              />
                              <button onClick={addChecklistItem} className="bg-nexus-card hover:bg-nexus-border text-nexus-text border border-nexus-border rounded px-3 py-1 text-xs font-medium transition-colors">Add</button>
                          </div>
                      )}
                  </div>
              </div>

               {/* Attachments */}
               <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                      <FileText size={16} className="text-nexus-cobalt" />
                      <h3>Anexos</h3>
                  </div>
                  <div className="grid grid-cols-2 gap-3 mb-2">
                    {formData.attachments?.map(att => (
                        <div key={att.id} className="flex items-center gap-3 p-3 bg-nexus-bg border border-nexus-border rounded hover:border-nexus-cobalt transition-colors group">
                        {att.type === 'image' ? (
                            <img 
                                src={att.url} 
                                alt="prev" 
                                onClick={() => handleImageClick(att.id)}
                                className="w-10 h-10 object-cover rounded bg-nexus-card cursor-pointer hover:opacity-80 transition-opacity" 
                            />
                        ) : (
                            <div className="w-10 h-10 bg-nexus-card flex items-center justify-center rounded text-nexus-text border border-nexus-border"><FileText size={16} /></div>
                        )}
