import React, { useState } from 'react';
import { LayoutGrid, ArrowRight, Loader2, WifiOff, ShieldCheck, Lock, User as UserIcon } from 'lucide-react';
import { User } from '../types';
import { supabase } from '../supabaseClient';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [formData, setFormData] = useState({
      username: '',
      password: '',
      role: 'viewer' as 'admin' | 'editor' | 'viewer'
  });

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const validatePassword = (pwd: string) => {
      const hasUpper = /[A-Z]/.test(pwd);
      const hasLower = /[a-z]/.test(pwd);
      const hasNumber = /[0-9]/.test(pwd);
      const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd);
      return hasUpper && hasLower && hasNumber && hasSpecial;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!formData.username.trim()) {
      setError('Por favor digite um usuário.');
      setLoading(false);
      return;
    }

    if (!formData.password) {
        setError('Por favor digite sua senha.');
        setLoading(false);
        return;
    }

    if (isRegister) {
        if (!validatePassword(formData.password)) {
            setError('A senha deve conter: Maiúscula, minúscula, número e caractere especial.');
            setLoading(false);
            return;
        }
    }

    try {
      // Try to connect to Supabase
      const { data: existingUser, error: fetchError } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', formData.username)
        .single();

      // Handle specific "Row not found" error (PGRST116) vs Connection Errors
      if (fetchError && fetchError.code !== 'PGRST116') { 
         throw fetchError; // This throws to catch block for connection errors
      }

      if (isRegister) {
        if (existingUser) {
          setError('Usuário já existe. Tente fazer login.');
          setLoading(false);
          return;
        }

        const { error: insertError } = await supabase
          .from('profiles')
          .insert([{ 
              username: formData.username,
              // Note: In a real app, hash password and store role in DB or Auth Metadata.
              // For this demo structure, we pass it to the App state.
          }]);

        if (insertError) throw insertError;

        // Login with new credentials
        onLogin({ 
            id: formData.username, 
            username: formData.username,
            role: formData.role
        }); 

      } else {
        // Login Logic
        if (!existingUser) {
            setError('Usuário não encontrado. Crie uma conta.');
            setLoading(false);
            return;
        }
        // In a real app, verify password hash here.
        // For demo, we just log them in and restore previous role if saved, else default.
        const storedRole = localStorage.getItem(`role_${existingUser.username}`);
        onLogin({ 
            id: existingUser.username, 
            username: existingUser.username,
            role: (storedRole as any) || 'admin'
        });
      }

    } catch (err: any) {
      console.warn("Supabase Connection Failed:", err);

      // FALLBACK: Enable Offline/Demo Mode
      console.log("Entering Offline/Demo Mode...");
      onLogin({ 
          id: formData.username, 
          username: formData.username,
          role: isRegister ? formData.role : 'admin'
      });

    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center">
      <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl relative overflow-hidden">

        {/* Decorative background element */}
        <div className="absolute -top-10 -right-10 w-32 h-32 bg-nexus-cobalt/10 rounded-full blur-3xl"></div>
        <div className="absolute -bottom-10 -left-10 w-32 h-32 bg-nexus-accent/10 rounded-full blur-3xl"></div>

        <div className="flex flex-col items-center mb-6 relative z-10">
          <div className="w-12 h-12 bg-nexus-cobalt rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-blue-900/50">
             <LayoutGrid size={24} className="text-white" />
          </div>
          <h1 className="text-2xl font-bold text-nexus-text font-mono tracking-tight">LUCK OS</h1>
          <p className="text-xs text-nexus-muted mt-2 uppercase tracking-widest text-center">Dashboard de Projetos</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 relative z-10">
          {/* Username */}
          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                <UserIcon size={10} /> Usuário
            </label>
            <input 
              type="text" 
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
              placeholder="Digite seu usuário..."
              disabled={loading}
            />
          </div>

          {/* Role Selection (Only Registration) */}
          {isRegister && (
            <div className="space-y-1 animate-in fade-in slide-in-from-top-2 duration-300">
                <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                    <ShieldCheck size={10} /> Cargo
                </label>
                <select
                    value={formData.role}
                    onChange={(e) => setFormData({...formData, role: e.target.value as any})}
                    className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm cursor-pointer"
                >
                    <option value="admin">Administrador</option>
                    <option value="editor">Gerente</option>
                    <option value="viewer">Usuário</option>
                </select>
            </div>
          )}

          {/* Password */}
          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                <Lock size={10} /> Senha
            </label>
            <input 
              type="password" 
              value={formData.password}
              onChange={(e) => setFormData({...formData, password: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
              placeholder="********"
              disabled={loading}
            />
            {isRegister && (
                <p className="text-[9px] text-nexus-muted leading-tight mt-1">
                    Requer: Maiúscula, minúscula, número e caractere especial.
                </p>
            )}
          </div>

          {error && <p className="text-red-500 text-xs flex items-center gap-1 bg-red-500/10 p-2 rounded border border-red-500/20"><WifiOff size={12}/> {error}</p>}

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-md shadow-blue-900/20 mt-2"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : (
                <>
                    {isRegister ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
                </>
            )}
          </button>
        </form>

        <div className="mt-6 text-center relative z-10">
          <button 
            onClick={() => { setIsRegister(!isRegister); setError(''); setFormData({...formData, role: 'viewer', password: ''}) }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {isRegister ? 'Já tem conta? Entrar' : 'Não tem conta? Registrar'}
          </button>
        </div>

        <div className="mt-4 text-[9px] text-center text-nexus-muted opacity-40">
            Modo demonstração ativo
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { Shield, Check, X, UserCog, Camera, Lock, Save, AlertCircle } from 'lucide-react';
import { ROLES_CONFIG } from '../constants';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: User;
  onUpdateProfile: (updates: Partial<User> & { password?: string }) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose, user, onUpdateProfile }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'security'>('general');

  // Form States
  const [avatarUrl, setAvatarUrl] = useState('');
  const [role, setRole] = useState<User['role']>('viewer');

  // Password States
  const [passwordData, setPasswordData] = useState({
      current: '',
      new: '',
      confirm: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
      if (isOpen) {
          setAvatarUrl(user.avatarUrl || '');
          setRole(user.role);
          setPasswordData({ current: '', new: '', confirm: '' });
          setError('');
          setSuccess('');
      }
  }, [isOpen, user]);

  const validatePassword = (pwd: string) => {
      const hasUpper = /[A-Z]/.test(pwd);
      const hasLower = /[a-z]/.test(pwd);
      const hasNumber = /[0-9]/.test(pwd);
      const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd);
      return hasUpper && hasLower && hasNumber && hasSpecial;
  };

  const handleSaveGeneral = () => {
      onUpdateProfile({ role, avatarUrl });
      setSuccess('Perfil atualizado com sucesso!');
      setTimeout(() => setSuccess(''), 3000);
  };

  const handleSaveSecurity = () => {
      setError('');
      setSuccess('');

      if (!passwordData.new) {
          setError('Digite a nova senha.');
          return;
      }

      if (passwordData.new !== passwordData.confirm) {
          setError('As senhas não conferem.');
          return;
      }

      if (!validatePassword(passwordData.new)) {
          setError('A senha deve conter: Maiúscula, minúscula, número e caractere especial.');
          return;
      }

      // In a real app, verify current password here.
      onUpdateProfile({ password: passwordData.new });
      setSuccess('Senha alterada com sucesso!');
      setPasswordData({ current: '', new: '', confirm: '' });
      setTimeout(() => setSuccess(''), 3000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[600px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-nexus-border bg-nexus-bg/50">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 rounded-full bg-nexus-cobalt flex items-center justify-center text-white font-bold text-xl overflow-hidden relative">
                {avatarUrl ? (
                    <img src={avatarUrl} alt={user.username} className="w-full h-full object-cover" />
                ) : (
                    user.username.charAt(0).toUpperCase()
                )}
             </div>
             <div>
                 <h2 className="text-xl font-bold text-nexus-text tracking-tight">{user.username}</h2>
                 <p className="text-xs text-nexus-muted uppercase tracking-wider flex items-center gap-1">
                     {ROLES_CONFIG[user.role].label}
                 </p>
             </div>
          </div>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-nexus-border">
            <button 
                onClick={() => setActiveTab('general')}
                className={`flex-1 py-3 text-sm font-medium transition-colors ${activeTab === 'general' ? 'text-nexus-cobalt border-b-2 border-nexus-cobalt bg-nexus-cobalt/5' : 'text-nexus-muted hover:text-nexus-text'}`}
            >
                Geral & Permissões
            </button>
            <button 
                onClick={() => setActiveTab('security')}
