  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
    } else {
      document.documentElement.classList.add('dark');
    }
    setIsDark(!isDark);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  const currentProject = projects.find(p => p.id === currentProjectId);
  const contextTasks = tasks.filter(t => t.projectId === currentProjectId);

  const uniqueAssignees = Array.from(new Set(
      contextTasks
        .map(t => t.assignee)
        .filter((a): a is string => typeof a === 'string' && a.length > 0)
  ));

  const filteredTasks = assigneeFilter 
      ? contextTasks.filter(t => t.assignee === assigneeFilter) 
      : contextTasks;

  return (
    <div className="flex h-screen w-screen bg-nexus-bg text-nexus-text font-sans overflow-hidden selection:bg-nexus-cobalt selection:text-white transition-colors duration-300">
      <Sidebar 
        projects={projects}
        currentProjectId={currentProjectId}
        setProjectId={setCurrentProjectId}
        onNewProject={() => { setProjectModalMode('create'); setIsProjectModalOpen(true); }}
        onShareProject={(p) => { setProjectToShare(p); setProjectModalMode('share'); setIsProjectModalOpen(true); }}
        onReorderProjects={handleReorderProjects}
        user={user}
        onLogout={handleLogout}
        isDark={isDark}
        toggleTheme={toggleTheme}
        currentView={currentView}
        setView={setCurrentView}
        onOpenProfile={() => setIsProfileModalOpen(true)}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">

        {isOfflineMode && (
             <div className="bg-red-500/10 border-b border-red-500/20 text-red-500 text-[10px] font-bold uppercase tracking-widest py-1 text-center flex items-center justify-center gap-2">
                 <WifiOff size={10} /> Modo Offline / Demonstração
             </div>
        )}

        {isLoading && (
            <div className="absolute inset-0 bg-nexus-bg/80 z-50 flex items-center justify-center backdrop-blur-sm">
                <div className="flex flex-col items-center gap-2">
                    <Loader2 size={32} className="animate-spin text-nexus-cobalt" />
                    <span className="text-xs font-mono text-nexus-muted">Sincronizando...</span>
                </div>
            </div>
        )}

        {currentView === 'board' && (
            <MetricsHeader 
                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
                hiddenColumns={hiddenColumns}
                onToggleColumn={toggleColumnVisibility}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard 
                tasks={tasks} 
                projects={projects} 
                initialProjectId={currentProjectId}
             />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS
                        .filter(col => !hiddenColumns.includes(col.id))
                        .map(col => {
                        // Stable Sort: Position ASC, then CreatedAt ASC
                        const colTasks = filteredTasks
                            .filter(t => t.status === col.id)
                            .sort((a, b) => {
                                const posA = a.position || 0;
                                const posB = b.position || 0;
                                if (posA !== posB) return posA - posB;
                                // Secondary sort for stability
                                return a.createdAt.localeCompare(b.createdAt);
                            });

                        return (
                            <div 
                            key={col.id} 
                            className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                            onDragOver={onDragOver}
                            onDrop={(e) => onDropColumn(e, col.id)}
                            >
                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                                <div className="flex items-center gap-2">
                                <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                    {col.label}
                                </span>
                                <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                    {colTasks.length}
                                </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => toggleColumnVisibility(col.id)}
                                        className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-nexus-cobalt transition-all"
                                        title="Ocultar coluna"
                                    >
                                        <EyeOff size={14} />
                                    </button>
                                    <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {colTasks.map(task => (
                                    <TaskCard 
                                    key={task.id} 
                                    task={task} 
                                    onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                    onDelete={handleDeleteTask}
                                    onDropOnTask={onDropTask}
                                    />
                                ))}

                                {quickAddColumn === col.id ? (
                                    <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                        <textarea
                                            autoFocus 
                                            value={quickAddTitle}
                                            onChange={(e) => setQuickAddTitle(e.target.value)}
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter' && !e.shiftKey) {
                                                    e.preventDefault();
                                                    handleQuickAdd();
                                                }
                                            }}
                                            placeholder="Insira um título para o cartão..."
                                            className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                            >
                                                Adicionar Cartão
                                            </button>
                                            <button 
                                                onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                                className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => setQuickAddColumn(col.id)}
                                        className={`w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1 ${user?.role === 'viewer' ? 'opacity-50 cursor-not-allowed' : ''}`}
                                        disabled={user?.role === 'viewer'}
                                        title={user?.role === 'viewer' ? 'Visualizadores não podem criar tarefas' : ''}
                                    >
                                        <Plus size={14} /> Adicionar cartão
                                    </button>
                                )}
                            </div>
                            </div>
                        );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
        userRole={user.role}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      <ProfileModal 
        isOpen={isProfileModalOpen}
        onClose={() => setIsProfileModalOpen(false)}
        user={user}
        onUpdateProfile={handleUpdateProfile}
      />

      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'automation'
                ? 'bg-nexus-accent/10 border-nexus-accent/20 text-nexus-accent'
                : toast.type === 'success' 
                    ? 'bg-green-500/10 border-green-500/20 text-green-500' 
                    : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            {toast.type === 'automation' && <Zap size={18} className="fill-current" />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag, ChecklistItem, User } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target, Calendar, CheckSquare, User as UserIcon, Edit2, Clock, Lock, AlertCircle } from 'lucide-react';
import { STATUS_COLUMNS, PRESET_SEGMENTS } from '../constants';
import { ImageGalleryModal } from './ImageGalleryModal';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
  availableTags: Tag[];
  onManageTags: (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => void;
  userRole: User['role'];
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ 
    task, 
    isOpen, 
    onClose, 
    onSave, 
    onDelete, 
    currentProjectId, 
    availableTags,
    onManageTags,
    userRole
}) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    clientSegment: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
    checklist: [],
    dueDate: '',
    assignee: '',
    coverUrl: ''
  });

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); 
  const [checklistInput, setChecklistInput] = useState('');

  // State for editing tags mode
  const [editingTag, setEditingTag] = useState<string | null>(null);

  // Validation state
  const [tagError, setTagError] = useState<string | null>(null);

  // Gallery State
  const [isGalleryOpen, setIsGalleryOpen] = useState(false);
  const [galleryStartIndex, setGalleryStartIndex] = useState(0);

  // PERMISSION CHECK
  const isReadOnly = userRole === 'viewer';
  const canDelete = userRole === 'admin';

  // Auto-calculate progress whenever checklist changes
  useEffect(() => {
    if (formData.checklist) {
        const total = formData.checklist.length;
        const checked = formData.checklist.filter(i => i.checked).length;
        const newProgress = total === 0 ? 0 : Math.round((checked / total) * 100);

        if (newProgress !== formData.progress) {
            setFormData(prev => ({ ...prev, progress: newProgress }));
        }
    }
  }, [formData.checklist]);

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        clientSegment: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        dueDate: '',
        assignee: '',
        projectId: currentProjectId,
        coverUrl: ''
      });
    }
  }, [task, isOpen, currentProjectId]);

  const getProgressLabel = (progress: number) => {
      if (progress === 0) return "Não iniciado";
      if (progress <= 60) return "Em andamento";
      if (progress <= 99) return "Quase concluído";
      return "Concluído";
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isReadOnly) return;
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  // Helper to open gallery
  const imageAttachments = formData.attachments?.filter(a => a.type === 'image') || [];

  const handleImageClick = (attId: string) => {
      const index = imageAttachments.findIndex(a => a.id === attId);
      if (index !== -1) {
          setGalleryStartIndex(index);
          setIsGalleryOpen(true);
      }
  };

  const addTagToTask = (tag: Tag) => {
      if (isReadOnly) return;
      if (!formData.tags?.find(t => t.text === tag.text)) {
          setFormData(prev => ({
              ...prev,
              tags: [...(prev.tags || []), tag]
          }));
      }
  };

  const createNewTag = () => {
      if (isReadOnly) return;
      const tagName = tagInput.trim();

      if (tagName) {
          // Validation: Check for duplicates (case insensitive)
          const isDuplicate = availableTags.some(t => t.text.toLowerCase() === tagName.toLowerCase());

          if (isDuplicate) {
              setTagError('Esta etiqueta já existe.');
              return;
          }

          const newTag = { text: tagName, color: selectedTagColor };
          // Add to global list
          onManageTags('add', newTag);
          // Add to this task automatically for convenience
          addTagToTask(newTag);
          setTagInput('');
          setTagError(null);
      }
  };

  const removeTagFromTask = (textToRemove: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  const addChecklistItem = () => {
      if (isReadOnly) return;
      if (checklistInput.trim()) {
          const newItem: ChecklistItem = {
              id: Date.now().toString(),
              text: checklistInput.trim(),
              checked: false,
              dueDate: ''
          };
          setFormData(prev => ({
              ...prev,
              checklist: [...(prev.checklist || []), newItem]
          }));
          setChecklistInput('');
      }
  };

  const toggleChecklistItem = (id: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
          )
      }));
  };

  const updateChecklistItemText = (id: string, newText: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, text: newText } : item
          )
      }));
  };

  const updateChecklistItemDate = (id: string, date: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({
        ...prev,
        checklist: prev.checklist?.map(item => 
          item.id === id ? { ...item, dueDate: date } : item
        )
    }));
  };

  const deleteChecklistItem = (id: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  if (!isOpen) return null;

  return (
    <>
    {/* Overlay background that handles closing (Click Outside) */}
    <div 
        className="fixed inset-0 z-50 flex justify-end bg-black/30 backdrop-blur-[1px] animate-in fade-in duration-200"
        onClick={onClose}
    >

      {/* Modal Content - Stop propagation to prevent closing when clicking inside the panel */}
      <div 
          className="w-full md:w-1/2 h-full bg-nexus-card border-l border-nexus-border shadow-2xl flex flex-col animate-in slide-in-from-right duration-300"
          onClick={(e) => e.stopPropagation()}
      >

        {/* Header */}
        <div className="flex justify-between items-start p-6 border-b border-nexus-border bg-nexus-bg/50 flex-shrink-0">
          <div className="flex-1 mr-4">
             <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-transparent border-none text-xl font-bold text-nexus-text focus:ring-0 outline-none p-0 placeholder-nexus-muted"
                  placeholder="Nome do Cartão..."
                  readOnly={isReadOnly}
            />
            <div className="text-xs text-nexus-muted mt-1 flex gap-2">
                <span>em lista <strong>{STATUS_COLUMNS.find(c => c.id === formData.status)?.label}</strong></span>
                {isReadOnly && <span className="flex items-center gap-1 text-nexus-muted border border-nexus-border px-1.5 rounded bg-nexus-bg"><Lock size={10} /> Somente Leitura</span>}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
                onClick={onClose} 
                className="p-2 text-nexus-muted hover:text-nexus-text hover:bg-nexus-bg rounded transition-colors"
                title="Fechar (Esc)"
            >
                <X size={24} />
            </button>
          </div>
        </div>

        {/* Content - Two Column Layout */}
        <div className="flex-1 overflow-y-auto p-6 flex gap-6 custom-scrollbar">

          {/* LEFT COLUMN (Main Content) */}
          <div className="flex-1 space-y-8 pb-12">

              {/* Description */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                    <FileText size={16} className="text-nexus-cobalt" />
                    <h3>Descrição</h3>
                </div>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={6}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none leading-relaxed text-sm read-only:opacity-60"
                  placeholder="Adicionar descrição detalhada..."
                  readOnly={isReadOnly}
                />
              </div>

              {/* Checklist */}
              <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide justify-between">
                      <div className="flex items-center gap-2">
                        <CheckSquare size={16} className="text-nexus-cobalt" />
                        <h3>Checklist</h3>
                      </div>
                      {/* Normalized Status Label */}
                      {formData.progress !== undefined && (
                          <span className="text-[10px] font-mono px-2 py-0.5 bg-nexus-bg border border-nexus-border rounded text-nexus-muted">
                              {getProgressLabel(formData.progress)}
                          </span>
                      )}
                  </div>

                  {/* Progress Bar */}
                  {formData.checklist && formData.checklist.length > 0 && (
                      <div className="flex items-center gap-2 mb-2">
                          <span className="text-xs text-nexus-muted w-8 text-right font-mono">
                              {Math.round((formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100)}%
                          </span>
                          <div className="flex-1 h-1.5 bg-nexus-bg rounded-full overflow-hidden">
                              <div 
                                className="h-full bg-nexus-cobalt transition-all duration-300 ease-out" 
                                style={{ width: `${(formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100}%` }}
                              ></div>
                          </div>
                      </div>
                  )}

                  <div className="space-y-2">
                      {formData.checklist?.map(item => (
                          <div key={item.id} className="flex flex-col gap-1 border-b border-nexus-border/50 pb-2 mb-2 last:border-0 last:mb-0 last:pb-0 group/item">
                             <div className="flex items-center gap-3">
                                <input 
                                    type="checkbox" 
                                    checked={item.checked} 
                                    onChange={() => toggleChecklistItem(item.id)}
                                    className="w-4 h-4 rounded border-nexus-border bg-nexus-bg checked:bg-nexus-cobalt cursor-pointer flex-shrink-0 disabled:opacity-50"
                                    disabled={isReadOnly}
                                />
                                <input 
                                    type="text"
                                    value={item.text}
                                    onChange={(e) => updateChecklistItemText(item.id, e.target.value)}
                                    className={`flex-1 text-sm bg-transparent outline-none border-b border-transparent focus:border-nexus-cobalt transition-all ${item.checked ? 'line-through text-nexus-muted' : 'text-nexus-text'}`}
                                    readOnly={isReadOnly}
                                />
                                {!isReadOnly && (
                                    <button onClick={() => deleteChecklistItem(item.id)} className="opacity-0 group-hover/item:opacity-100 text-nexus-muted hover:text-red-500 transition-opacity p-1">
                                        <X size={14} />
                                    </button>
                                )}
                             </div>

                             {/* Date for checklist item */}
                             <div className="pl-7">
                                <input 
                                    type="datetime-local" 
                                    value={item.dueDate || ''}
                                    onChange={(e) => updateChecklistItemDate(item.id, e.target.value)}
                                    className="text-[10px] bg-transparent text-nexus-muted border-none hover:bg-nexus-bg rounded px-1.5 py-0.5 outline-none focus:text-nexus-cobalt transition-colors cursor-pointer disabled:opacity-50"
                                    disabled={isReadOnly}
                                />
                             </div>
                          </div>
                      ))}
                      {!isReadOnly && (
                          <div className="flex gap-2 mt-2 pl-7">
                              <input 
                                type="text" 
                                value={checklistInput}
                                onChange={(e) => setChecklistInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && addChecklistItem()}
                                className="flex-1 bg-nexus-bg border border-nexus-border rounded px-3 py-1.5 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                placeholder="Adicionar item..."
                              />
                              <button onClick={addChecklistItem} className="bg-nexus-card hover:bg-nexus-border text-nexus-text border border-nexus-border rounded px-3 py-1 text-xs font-medium transition-colors">Add</button>
                          </div>
                      )}
                  </div>
              </div>

               {/* Attachments */}
               <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                      <FileText size={16} className="text-nexus-cobalt" />
                      <h3>Anexos</h3>
                  </div>
                  <div className="grid grid-cols-2 gap-3 mb-2">
                    {formData.attachments?.map(att => (
                        <div key={att.id} className="flex items-center gap-3 p-3 bg-nexus-bg border border-nexus-border rounded hover:border-nexus-cobalt transition-colors group">
                        {att.type === 'image' ? (
                            <img 
                                src={att.url} 
                                alt="prev" 
                                onClick={() => handleImageClick(att.id)}
                                className="w-10 h-10 object-cover rounded bg-nexus-card cursor-pointer hover:opacity-80 transition-opacity" 
                            />
                        ) : (
                            <div className="w-10 h-10 bg-nexus-card flex items-center justify-center rounded text-nexus-text border border-nexus-border"><FileText size={16} /></div>
                        )}
                        <div className="flex-1 min-w-0">
                            <p 
                                className={`text-xs font-medium truncate text-nexus-text ${att.type === 'image' ? 'cursor-pointer hover:text-nexus-cobalt' : ''}`}
                                onClick={() => att.type === 'image' && handleImageClick(att.id)}
                            >
                                {att.name}
                            </p>
                            <a href={att.url} target="_blank" rel="noreferrer" className="text-[10px] text-nexus-cobalt hover:underline">Visualizar / Baixar</a>
                        </div>
                        {!isReadOnly && (
                            <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><X size={14} /></button>
                        )}
                        </div>
                    ))}
                  </div>
                   {!isReadOnly && (
                       <div className="relative group">
                        <input 
                            type="file" 
                            onChange={handleFileChange} 
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
                        />
                        <button className="flex items-center justify-center gap-2 text-sm text-nexus-muted bg-nexus-bg/50 hover:bg-nexus-bg px-3 py-3 rounded w-full border border-nexus-border border-dashed transition-all group-hover:border-nexus-cobalt group-hover:text-nexus-cobalt">
                            <Upload size={14} /> Adicionar anexo
                        </button>
                       </div>
                   )}
               </div>

               {/* Client Info (Backlog) */}
               {formData.status === 'backlog' && (
                   <div className="bg-gradient-to-br from-nexus-bg to-nexus-card border border-nexus-border rounded p-5 space-y-4">
                       <h4 className="text-xs font-bold uppercase text-nexus-text tracking-wider flex items-center gap-2 border-b border-nexus-border pb-2">
                           <Briefcase size={14} className="text-nexus-accent" /> Dados do Cliente (Intake)
                       </h4>
                       <div className="grid grid-cols-2 gap-4">
                           <div className="space-y-1">
                               <label className="text-[10px] uppercase text-nexus-muted font-bold">Nome do Cliente</label>
                               <input 
                                    type="text" 
                                    value={formData.clientName} 
                                    onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                    placeholder="Empresa Ltda"
                                    readOnly={isReadOnly}
                                />
                           </div>

                            <div className="space-y-1">
                                <label className="text-[10px] uppercase text-nexus-muted font-bold">Segmento</label>
                                <div className="relative">
                                    <input 
                                        list="segment-options"
                                        type="text" 
                                        value={formData.clientSegment} 
                                        onChange={(e) => setFormData({...formData, clientSegment: e.target.value})}
                                        className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                        placeholder="Selecione..."
                                        readOnly={isReadOnly}
                                    />
                                    <datalist id="segment-options">
                                        {PRESET_SEGMENTS.map(seg => (
                                            <option key={seg} value={seg} />
                                        ))}
                                    </datalist>
                                </div>
                            </div>
                       </div>

                       <div className="space-y-1">
                           <label className="text-[10px] uppercase text-nexus-muted font-bold">Website / Links</label>
                           <div className="relative">
                               <Globe size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                               <input 
                                    type="text" 
                                    value={formData.websiteUrl} 
                                    onChange={(e) => setFormData({...formData, websiteUrl: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 pl-8 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                    placeholder="https://..."
                                    readOnly={isReadOnly}
                                />
                           </div>
                       </div>

                       <div className="space-y-1">
                           <label className="text-[10px] uppercase text-nexus-muted font-bold">Objetivo Principal</label>
                           <div className="relative">
                               <Target size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                               <input 
                                    type="text" 
                                    value={formData.objective} 
                                    onChange={(e) => setFormData({...formData, objective: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 pl-8 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                    placeholder="Ex: Aumentar leads em 20%..."
                                    readOnly={isReadOnly}
                                />
                           </div>
                       </div>
                   </div>
               )}

          </div>

          {/* RIGHT COLUMN (Metadata Sidebar) */}
          <div className="w-72 space-y-6 pt-1">

              {/* Properties Panel */}
              <div className="bg-nexus-bg/30 border border-nexus-border rounded-lg p-4 space-y-4">
                  <div className="text-xs font-bold text-nexus-muted uppercase tracking-wider mb-2">Propriedades</div>

                  {/* Status */}
                  <div className="space-y-1">
                    <label className="text-[10px] text-nexus-muted">Status</label>
                    <select 
                        value={formData.status} 
                        onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                        className="w-full bg-nexus-card border border-nexus-border rounded px-2 py-2 text-xs font-medium outline-none focus:border-nexus-cobalt disabled:opacity-70"
                        disabled={isReadOnly}
                    >
                        {STATUS_COLUMNS.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
                    </select>
                  </div>

                  {/* Priority */}
                  <div className="space-y-1">
                    <label className="text-[10px] text-nexus-muted">Prioridade</label>
                    <select 
                        value={formData.priority} 
                        onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                        className="w-full bg-nexus-card border border-nexus-border rounded px-2 py-2 text-xs font-medium outline-none focus:border-nexus-cobalt disabled:opacity-70"
                        disabled={isReadOnly}
                    >
                        <option value="Low">Baixa</option>
                        <option value="Medium">Média</option>
                        <option value="High">Alta</option>
                    </select>
                  </div>

                   {/* Assignee */}
                  <div className="space-y-1">
                      <label className="text-[10px] text-nexus-muted">Responsável</label>
                      <div className="relative">
                          <UserIcon size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                          <input 
                            type="text" 
                            value={formData.assignee}
                            onChange={(e) => setFormData({...formData, assignee: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded pl-7 py-2 text-xs outline-none focus:border-nexus-cobalt"
                            placeholder="Nome do usuário..."
                            readOnly={isReadOnly}
                          />
                      </div>
                  </div>

                  {/* Due Date */}
                  <div className="space-y-1">
                      <label className="text-[10px] text-nexus-muted">Data de Entrega</label>
                      <div className="relative">
                          <Calendar size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                          <input 
                            type="date"
                            value={formData.dueDate}
                            onChange={(e) => setFormData({...formData, dueDate: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded pl-7 py-2 text-xs outline-none focus:border-nexus-cobalt text-nexus-text disabled:opacity-70" 
                            disabled={isReadOnly}
                          />
                      </div>
                  </div>
              </div>

              {/* Tags Section */}
              <div className="space-y-3">
                   <div className="flex items-center gap-2 text-xs font-bold text-nexus-muted uppercase tracking-wider">
                       <TagIcon size={12} /> Etiquetas
                   </div>

                   {/* Selected Tags */}
                   <div className="flex flex-wrap gap-1.5 mb-2">
                        {formData.tags?.map(tag => (
                             <div key={tag.text} className="h-6 rounded flex items-center px-2 text-[10px] font-bold text-white relative group cursor-default shadow-sm" style={{ backgroundColor: tag.color }}>
                                 {tag.text}
                                 {!isReadOnly && <button onClick={() => removeTagFromTask(tag.text)} className="ml-1 opacity-50 hover:opacity-100 hover:text-white"><X size={10}/></button>}
                             </div>
                        ))}
                        {(!formData.tags || formData.tags.length === 0) && (
                            <span className="text-xs text-nexus-muted italic">Sem etiquetas</span>
                        )}
                   </div>

                   {/* Tag Manager - Only show if not read only */}
                   {!isReadOnly && (
                       <div className="p-3 bg-nexus-bg/50 border border-nexus-border rounded-lg max-h-60 overflow-y-auto custom-scrollbar">
                            <div className="text-[10px] text-nexus-muted font-bold uppercase mb-2">Adicionar / Criar</div>

                            {/* New Tag Input */}
                            <div className="flex flex-col gap-2 mb-3 bg-nexus-card p-2 rounded border border-nexus-border transition-colors">
                                <input 
                                    type="text" 
                                    value={tagInput} 
                                    onChange={(e) => {
                                        setTagInput(e.target.value);
                                        if (tagError) setTagError(null);
                                    }}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            if (editingTag) {
                                                onManageTags('edit', { text: tagInput, color: selectedTagColor }, editingTag);
                                                setEditingTag(null);
                                                setTagInput('');
                                                setTagError(null);
                                            } else {
                                                createNewTag();
                                            }
                                        }
                                    }}
                                    className={`w-full bg-transparent border-b text-xs outline-none pb-1 mb-1 focus:border-nexus-cobalt transition-colors ${tagError ? 'border-red-500' : 'border-nexus-border'}`}
                                    placeholder={editingTag ? "Editar nome..." : "Nova etiqueta..."}
                                />
                                {tagError && (
                                    <div className="flex items-center gap-1 mb-1">
                                        <AlertCircle size={8} className="text-red-500" />
                                        <span className="text-[9px] text-red-500 font-medium">{tagError}</span>
                                    </div>
                                )}

                                <div className="flex justify-between items-center">
                                    <div className="flex gap-1">
                                        {TAG_COLORS.slice(0, 5).map(c => (
                                            <button 
                                                key={c}
                                                onClick={() => setSelectedTagColor(c)}
                                                className={`w-3 h-3 rounded-full transition-transform ${selectedTagColor === c ? 'scale-125 ring-1 ring-nexus-text' : 'hover:scale-110'}`}
                                                style={{ backgroundColor: c }}
                                            />
                                        ))}
                                    </div>
                                    <button 
                                        onClick={() => {
                                            if (editingTag) {
                                                onManageTags('edit', { text: tagInput, color: selectedTagColor }, editingTag);
                                                setEditingTag(null);
                                                setTagInput('');
                                                setTagError(null);
                                            } else {
                                                createNewTag();
                                            }
                                        }} 
                                        className="text-[10px] bg-nexus-cobalt text-white px-2 py-0.5 rounded hover:bg-blue-600 transition-colors"
                                    >
                                        {editingTag ? 'Salvar' : 'Criar'}
                                    </button>
                                </div>
                            </div>

                            {/* Existing Tags List */}
                            <div className="space-y-1">
                                {availableTags.map(tag => {
                                    const isSelected = formData.tags?.find(t => t.text === tag.text);
                                    return (
                                    <div key={tag.text} className="flex items-center gap-1 group/tag">
                                        <button 
                                            onClick={() => addTagToTask(tag)}
                                            className={`flex-1 text-left px-2 py-1.5 rounded text-[10px] font-medium text-white hover:opacity-90 transition-all flex items-center justify-between shadow-sm ${isSelected ? 'ring-1 ring-white ring-offset-1 ring-offset-nexus-bg' : 'opacity-70'}`}
                                            style={{ backgroundColor: tag.color }}
                                            title="Adicionar à tarefa"
                                        >
                                            <span className="truncate">{tag.text}</span>
                                            {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-white/50"></div>}
                                        </button>

                                        <div className="flex gap-0.5 opacity-0 group-hover/tag:opacity-100 transition-opacity">
                                            <button 
                                                onClick={() => { setTagInput(tag.text); setSelectedTagColor(tag.color); setEditingTag(tag.text); setTagError(null); }}
                                                className="p-1 text-nexus-muted hover:text-nexus-cobalt bg-nexus-card rounded border border-nexus-border"
                                                title="Editar etiqueta"
                                            >
                                                <Edit2 size={10} />
                                            </button>
                                            <button 
                                                onClick={() => onManageTags('delete', tag)}
                                                className="p-1 text-nexus-muted hover:text-red-500 bg-nexus-card rounded border border-nexus-border"
                                                title="Excluir etiqueta do sistema"
                                            >
                                                <Trash2 size={10} />
                                            </button>
                                        </div>
                                    </div>
                                )})}
                            </div>
                       </div>
                   )}
              </div>

               {/* Metadata Footer */}
               {formData.createdAt && typeof formData.createdAt === 'string' && (
                <div className="pt-4 border-t border-nexus-border text-center">
                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-nexus-bg rounded-full border border-nexus-border text-[10px] text-nexus-muted">
                        <Clock size={10} />
                        <span>Criado em {new Date(formData.createdAt).toLocaleDateString('pt-BR')}</span>
                    </div>
                </div>
              )}

          </div>

        </div>

        {/* Footer */}
        <div className="p-5 border-t border-nexus-border flex justify-between bg-nexus-bg/50 flex-shrink-0">
          {task && canDelete ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-3 py-2 text-xs font-bold text-red-500 hover:bg-red-500/10 rounded transition-colors border border-transparent hover:border-red-500/20"
            >
              <Trash2 size={14} /> Excluir Cartão
            </button>
          ) : <div></div>}

          <div className="flex gap-3">
              <button 
                onClick={onClose}
                className="px-4 py-2 text-xs font-bold text-nexus-text hover:bg-nexus-border rounded transition-colors"
              >
                Cancelar
              </button>
              {!isReadOnly && (
                <button 
                    onClick={() => onSave(formData as Task)}
                    className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-all shadow-lg shadow-blue-900/20"
                >
                    <Save size={14} /> Salvar Alterações
                </button>
              )}
          </div>
        </div>
      </div>
    </div>

    {/* Image Gallery Modal */}
    <ImageGalleryModal 
        isOpen={isGalleryOpen} 
        onClose={() => setIsGalleryOpen(false)} 
        images={imageAttachments} 
        initialIndex={galleryStartIndex} 
    />
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { Task, Status, Priority, Attachment, Tag, ChecklistItem, User } from '../types';
import { X, Upload, FileText, Trash2, Save, Tag as TagIcon, Globe, Briefcase, Target, Calendar, CheckSquare, User as UserIcon, Edit2, Clock, Lock, AlertCircle } from 'lucide-react';
import { STATUS_COLUMNS, PRESET_SEGMENTS } from '../constants';
import { ImageGalleryModal } from './ImageGalleryModal';

interface TaskModalProps {
  task?: Task | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Task) => void;
  onDelete: (id: string) => void;
  currentProjectId: string;
  availableTags: Tag[];
  onManageTags: (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => void;
  userRole: User['role'];
}

const TAG_COLORS = [
  '#ef4444', // Red
  '#f97316', // Orange
  '#eab308', // Yellow/Amber
  '#22c55e', // Green
  '#06b6d4', // Cyan
  '#3b82f6', // Blue
  '#a855f7', // Purple
  '#ec4899', // Pink
  '#737373', // Grey
];

export const TaskModal: React.FC<TaskModalProps> = ({ 
    task, 
    isOpen, 
    onClose, 
    onSave, 
    onDelete, 
    currentProjectId, 
    availableTags,
    onManageTags,
    userRole
}) => {
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    description: '',
    clientName: '',
    clientSegment: '',
    objective: '',
    websiteUrl: '',
    status: 'backlog',
    priority: 'Medium',
    progress: 0,
    tags: [],
    attachments: [],
    checklist: [],
    dueDate: '',
    assignee: '',
    coverUrl: ''
  });

  const [tagInput, setTagInput] = useState('');
  const [selectedTagColor, setSelectedTagColor] = useState(TAG_COLORS[5]); 
  const [checklistInput, setChecklistInput] = useState('');

  // State for editing tags mode
  const [editingTag, setEditingTag] = useState<string | null>(null);

  // Validation state
  const [tagError, setTagError] = useState<string | null>(null);

  // Gallery State
  const [isGalleryOpen, setIsGalleryOpen] = useState(false);
  const [galleryStartIndex, setGalleryStartIndex] = useState(0);

  // PERMISSION CHECK
  const isReadOnly = userRole === 'viewer';
  const canDelete = userRole === 'admin';

  // Auto-calculate progress whenever checklist changes
  useEffect(() => {
    if (formData.checklist) {
        const total = formData.checklist.length;
        const checked = formData.checklist.filter(i => i.checked).length;
        const newProgress = total === 0 ? 0 : Math.round((checked / total) * 100);

        if (newProgress !== formData.progress) {
            setFormData(prev => ({ ...prev, progress: newProgress }));
        }
    }
  }, [formData.checklist]);

  useEffect(() => {
    if (task) {
      setFormData(task);
    } else {
      setFormData({
        title: '',
        description: '',
        clientName: '',
        clientSegment: '',
        objective: '',
        websiteUrl: '',
        status: 'backlog',
        priority: 'Medium',
        progress: 0,
        tags: [],
        attachments: [],
        checklist: [],
        dueDate: '',
        assignee: '',
        projectId: currentProjectId,
        coverUrl: ''
      });
    }
  }, [task, isOpen, currentProjectId]);

  const getProgressLabel = (progress: number) => {
      if (progress === 0) return "Não iniciado";
      if (progress <= 60) return "Em andamento";
      if (progress <= 99) return "Quase concluído";
      return "Concluído";
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isReadOnly) return;
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const newAttachment: Attachment = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf', 
        url: URL.createObjectURL(file),
      };
      setFormData(prev => ({
        ...prev,
        attachments: [...(prev.attachments || []), newAttachment]
      }));
    }
  };

  const removeAttachment = (id: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({
      ...prev,
      attachments: prev.attachments?.filter(a => a.id !== id)
    }));
  };

  // Helper to open gallery
  const imageAttachments = formData.attachments?.filter(a => a.type === 'image') || [];

  const handleImageClick = (attId: string) => {
      const index = imageAttachments.findIndex(a => a.id === attId);
      if (index !== -1) {
          setGalleryStartIndex(index);
          setIsGalleryOpen(true);
      }
  };

  const addTagToTask = (tag: Tag) => {
      if (isReadOnly) return;
      if (!formData.tags?.find(t => t.text === tag.text)) {
          setFormData(prev => ({
              ...prev,
              tags: [...(prev.tags || []), tag]
          }));
      }
  };

  const createNewTag = () => {
      if (isReadOnly) return;
      const tagName = tagInput.trim();

      if (tagName) {
          // Validation: Check for duplicates (case insensitive)
          const isDuplicate = availableTags.some(t => t.text.toLowerCase() === tagName.toLowerCase());

          if (isDuplicate) {
              setTagError('Esta etiqueta já existe.');
              return;
          }

          const newTag = { text: tagName, color: selectedTagColor };
          // Add to global list
          onManageTags('add', newTag);
          // Add to this task automatically for convenience
          addTagToTask(newTag);
          setTagInput('');
          setTagError(null);
      }
  };

  const removeTagFromTask = (textToRemove: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          tags: prev.tags?.filter(t => t.text !== textToRemove)
      }));
  };

  const addChecklistItem = () => {
      if (isReadOnly) return;
      if (checklistInput.trim()) {
          const newItem: ChecklistItem = {
              id: Date.now().toString(),
              text: checklistInput.trim(),
              checked: false,
              dueDate: ''
          };
          setFormData(prev => ({
              ...prev,
              checklist: [...(prev.checklist || []), newItem]
          }));
          setChecklistInput('');
      }
  };

  const toggleChecklistItem = (id: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, checked: !item.checked } : item
          )
      }));
  };

  const updateChecklistItemText = (id: string, newText: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.map(item => 
            item.id === id ? { ...item, text: newText } : item
          )
      }));
  };

  const updateChecklistItemDate = (id: string, date: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({
        ...prev,
        checklist: prev.checklist?.map(item => 
          item.id === id ? { ...item, dueDate: date } : item
        )
    }));
  };

  const deleteChecklistItem = (id: string) => {
      if (isReadOnly) return;
      setFormData(prev => ({
          ...prev,
          checklist: prev.checklist?.filter(item => item.id !== id)
      }));
  };

  if (!isOpen) return null;

  return (
    <>
    {/* Overlay background that handles closing (Click Outside) */}
    <div 
        className="fixed inset-0 z-50 flex justify-end bg-black/30 backdrop-blur-[1px] animate-in fade-in duration-200"
        onClick={onClose}
    >

      {/* Modal Content - Stop propagation to prevent closing when clicking inside the panel */}
      <div 
          className="w-full md:w-1/2 h-full bg-nexus-card border-l border-nexus-border shadow-2xl flex flex-col animate-in slide-in-from-right duration-300"
          onClick={(e) => e.stopPropagation()}
      >

        {/* Header */}
        <div className="flex justify-between items-start p-6 border-b border-nexus-border bg-nexus-bg/50 flex-shrink-0">
          <div className="flex-1 mr-4">
             <input 
                  type="text" 
                  value={formData.title} 
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  className="w-full bg-transparent border-none text-xl font-bold text-nexus-text focus:ring-0 outline-none p-0 placeholder-nexus-muted"
                  placeholder="Nome do Cartão..."
                  readOnly={isReadOnly}
            />
            <div className="text-xs text-nexus-muted mt-1 flex gap-2">
                <span>em lista <strong>{STATUS_COLUMNS.find(c => c.id === formData.status)?.label}</strong></span>
                {isReadOnly && <span className="flex items-center gap-1 text-nexus-muted border border-nexus-border px-1.5 rounded bg-nexus-bg"><Lock size={10} /> Somente Leitura</span>}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
                onClick={onClose} 
                className="p-2 text-nexus-muted hover:text-nexus-text hover:bg-nexus-bg rounded transition-colors"
                title="Fechar (Esc)"
            >
                <X size={24} />
            </button>
          </div>
        </div>

        {/* Content - Two Column Layout */}
        <div className="flex-1 overflow-y-auto p-6 flex gap-6 custom-scrollbar">

          {/* LEFT COLUMN (Main Content) */}
          <div className="flex-1 space-y-8 pb-12">

              {/* Description */}
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                    <FileText size={16} className="text-nexus-cobalt" />
                    <h3>Descrição</h3>
                </div>
                <textarea 
                  value={formData.description} 
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={6}
                  className="w-full bg-nexus-bg border border-nexus-border rounded p-3 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors resize-none leading-relaxed text-sm read-only:opacity-60"
                  placeholder="Adicionar descrição detalhada..."
                  readOnly={isReadOnly}
                />
              </div>

              {/* Checklist */}
              <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide justify-between">
                      <div className="flex items-center gap-2">
                        <CheckSquare size={16} className="text-nexus-cobalt" />
                        <h3>Checklist</h3>
                      </div>
                      {/* Normalized Status Label */}
                      {formData.progress !== undefined && (
                          <span className="text-[10px] font-mono px-2 py-0.5 bg-nexus-bg border border-nexus-border rounded text-nexus-muted">
                              {getProgressLabel(formData.progress)}
                          </span>
                      )}
                  </div>

                  {/* Progress Bar */}
                  {formData.checklist && formData.checklist.length > 0 && (
                      <div className="flex items-center gap-2 mb-2">
                          <span className="text-xs text-nexus-muted w-8 text-right font-mono">
                              {Math.round((formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100)}%
                          </span>
                          <div className="flex-1 h-1.5 bg-nexus-bg rounded-full overflow-hidden">
                              <div 
                                className="h-full bg-nexus-cobalt transition-all duration-300 ease-out" 
                                style={{ width: `${(formData.checklist.filter(i => i.checked).length / formData.checklist.length) * 100}%` }}
                              ></div>
                          </div>
                      </div>
                  )}

                  <div className="space-y-2">
                      {formData.checklist?.map(item => (
                          <div key={item.id} className="flex flex-col gap-1 border-b border-nexus-border/50 pb-2 mb-2 last:border-0 last:mb-0 last:pb-0 group/item">
                             <div className="flex items-center gap-3">
                                <input 
                                    type="checkbox" 
                                    checked={item.checked} 
                                    onChange={() => toggleChecklistItem(item.id)}
                                    className="w-4 h-4 rounded border-nexus-border bg-nexus-bg checked:bg-nexus-cobalt cursor-pointer flex-shrink-0 disabled:opacity-50"
                                    disabled={isReadOnly}
                                />
                                <input 
                                    type="text"
                                    value={item.text}
                                    onChange={(e) => updateChecklistItemText(item.id, e.target.value)}
                                    className={`flex-1 text-sm bg-transparent outline-none border-b border-transparent focus:border-nexus-cobalt transition-all ${item.checked ? 'line-through text-nexus-muted' : 'text-nexus-text'}`}
                                    readOnly={isReadOnly}
                                />
                                {!isReadOnly && (
                                    <button onClick={() => deleteChecklistItem(item.id)} className="opacity-0 group-hover/item:opacity-100 text-nexus-muted hover:text-red-500 transition-opacity p-1">
                                        <X size={14} />
                                    </button>
                                )}
                             </div>

                             {/* Date for checklist item */}
                             <div className="pl-7">
                                <input 
                                    type="datetime-local" 
                                    value={item.dueDate || ''}
                                    onChange={(e) => updateChecklistItemDate(item.id, e.target.value)}
                                    className="text-[10px] bg-transparent text-nexus-muted border-none hover:bg-nexus-bg rounded px-1.5 py-0.5 outline-none focus:text-nexus-cobalt transition-colors cursor-pointer disabled:opacity-50"
                                    disabled={isReadOnly}
                                />
                             </div>
                          </div>
                      ))}
                      {!isReadOnly && (
                          <div className="flex gap-2 mt-2 pl-7">
                              <input 
                                type="text" 
                                value={checklistInput}
                                onChange={(e) => setChecklistInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && addChecklistItem()}
                                className="flex-1 bg-nexus-bg border border-nexus-border rounded px-3 py-1.5 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                placeholder="Adicionar item..."
                              />
                              <button onClick={addChecklistItem} className="bg-nexus-card hover:bg-nexus-border text-nexus-text border border-nexus-border rounded px-3 py-1 text-xs font-medium transition-colors">Add</button>
                          </div>
                      )}
                  </div>
              </div>

               {/* Attachments */}
               <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm font-bold text-nexus-text uppercase tracking-wide">
                      <FileText size={16} className="text-nexus-cobalt" />
                      <h3>Anexos</h3>
                  </div>
                  <div className="grid grid-cols-2 gap-3 mb-2">
                    {formData.attachments?.map(att => (
                        <div key={att.id} className="flex items-center gap-3 p-3 bg-nexus-bg border border-nexus-border rounded hover:border-nexus-cobalt transition-colors group">
                        {att.type === 'image' ? (
                            <img 
                                src={att.url} 
                                alt="prev" 
                                onClick={() => handleImageClick(att.id)}
                                className="w-10 h-10 object-cover rounded bg-nexus-card cursor-pointer hover:opacity-80 transition-opacity" 
                            />
                        ) : (
                            <div className="w-10 h-10 bg-nexus-card flex items-center justify-center rounded text-nexus-text border border-nexus-border"><FileText size={16} /></div>
                        )}
                        <div className="flex-1 min-w-0">
                            <p 
                                className={`text-xs font-medium truncate text-nexus-text ${att.type === 'image' ? 'cursor-pointer hover:text-nexus-cobalt' : ''}`}
                                onClick={() => att.type === 'image' && handleImageClick(att.id)}
                            >
                                {att.name}
                            </p>
                            <a href={att.url} target="_blank" rel="noreferrer" className="text-[10px] text-nexus-cobalt hover:underline">Visualizar / Baixar</a>
                        </div>
                        {!isReadOnly && (
                            <button onClick={() => removeAttachment(att.id)} className="text-nexus-muted hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><X size={14} /></button>
                        )}
                        </div>
                    ))}
                  </div>
                   {!isReadOnly && (
                       <div className="relative group">
                        <input 
                            type="file" 
                            onChange={handleFileChange} 
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
                        />
                        <button className="flex items-center justify-center gap-2 text-sm text-nexus-muted bg-nexus-bg/50 hover:bg-nexus-bg px-3 py-3 rounded w-full border border-nexus-border border-dashed transition-all group-hover:border-nexus-cobalt group-hover:text-nexus-cobalt">
                            <Upload size={14} /> Adicionar anexo
                        </button>
                       </div>
                   )}
               </div>

               {/* Client Info (Backlog) */}
               {formData.status === 'backlog' && (
                   <div className="bg-gradient-to-br from-nexus-bg to-nexus-card border border-nexus-border rounded p-5 space-y-4">
                       <h4 className="text-xs font-bold uppercase text-nexus-text tracking-wider flex items-center gap-2 border-b border-nexus-border pb-2">
                           <Briefcase size={14} className="text-nexus-accent" /> Dados do Cliente
                       </h4>
                       <div className="grid grid-cols-2 gap-4">
                           <div className="space-y-1">
                               <label className="text-[10px] uppercase text-nexus-muted font-bold">Nome do Cliente</label>
                               <input 
                                    type="text" 
                                    value={formData.clientName} 
                                    onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                    placeholder="Empresa Ltda"
                                    readOnly={isReadOnly}
                                />
                           </div>

                            <div className="space-y-1">
                                <label className="text-[10px] uppercase text-nexus-muted font-bold">Segmento</label>
                                <div className="relative">
                                    <input 
                                        list="segment-options"
                                        type="text" 
                                        value={formData.clientSegment} 
                                        onChange={(e) => setFormData({...formData, clientSegment: e.target.value})}
                                        className="w-full bg-nexus-card border border-nexus-border rounded p-2 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                        placeholder="Selecione..."
                                        readOnly={isReadOnly}
                                    />
                                    <datalist id="segment-options">
                                        {PRESET_SEGMENTS.map(seg => (
                                            <option key={seg} value={seg} />
                                        ))}
                                    </datalist>
                                </div>
                            </div>
                       </div>

                       <div className="space-y-1">
                           <label className="text-[10px] uppercase text-nexus-muted font-bold">Website / Links</label>
                           <div className="relative">
                               <Globe size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                               <input 
                                    type="text" 
                                    value={formData.websiteUrl} 
                                    onChange={(e) => setFormData({...formData, websiteUrl: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 pl-8 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                    placeholder="https://..."
                                    readOnly={isReadOnly}
                                />
                           </div>
                       </div>

                       <div className="space-y-1">
                           <label className="text-[10px] uppercase text-nexus-muted font-bold">Objetivo Principal</label>
                           <div className="relative">
                               <Target size={14} className="absolute left-2.5 top-2.5 text-nexus-muted" />
                               <input 
                                    type="text" 
                                    value={formData.objective} 
                                    onChange={(e) => setFormData({...formData, objective: e.target.value})}
                                    className="w-full bg-nexus-card border border-nexus-border rounded p-2 pl-8 text-sm outline-none focus:border-nexus-cobalt transition-colors"
                                    placeholder="Ex: Aumentar leads em 20%..."
                                    readOnly={isReadOnly}
                                />
                           </div>
                       </div>
                   </div>
               )}

          </div>

          {/* RIGHT COLUMN (Metadata Sidebar) */}
          <div className="w-72 space-y-6 pt-1">

              {/* Properties Panel */}
              <div className="bg-nexus-bg/30 border border-nexus-border rounded-lg p-4 space-y-4">
                  <div className="text-xs font-bold text-nexus-muted uppercase tracking-wider mb-2">Propriedades</div>

                  {/* Status */}
                  <div className="space-y-1">
                    <label className="text-[10px] text-nexus-muted">Status</label>
                    <select 
                        value={formData.status} 
                        onChange={(e) => setFormData({...formData, status: e.target.value as Status})}
                        className="w-full bg-nexus-card border border-nexus-border rounded px-2 py-2 text-xs font-medium outline-none focus:border-nexus-cobalt disabled:opacity-70"
                        disabled={isReadOnly}
                    >
                        {STATUS_COLUMNS.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
                    </select>
                  </div>

                  {/* Priority */}
                  <div className="space-y-1">
                    <label className="text-[10px] text-nexus-muted">Prioridade</label>
                    <select 
                        value={formData.priority} 
                        onChange={(e) => setFormData({...formData, priority: e.target.value as Priority})}
                        className="w-full bg-nexus-card border border-nexus-border rounded px-2 py-2 text-xs font-medium outline-none focus:border-nexus-cobalt disabled:opacity-70"
                        disabled={isReadOnly}
                    >
                        <option value="Low">Baixa</option>
                        <option value="Medium">Média</option>
                        <option value="High">Alta</option>
                    </select>
                  </div>

                   {/* Assignee */}
                  <div className="space-y-1">
                      <label className="text-[10px] text-nexus-muted">Responsável</label>
                      <div className="relative">
                          <UserIcon size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                          <input 
                            type="text" 
                            value={formData.assignee}
                            onChange={(e) => setFormData({...formData, assignee: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded pl-7 py-2 text-xs outline-none focus:border-nexus-cobalt"
                            placeholder="Nome do usuário..."
                            readOnly={isReadOnly}
                          />
                      </div>
                  </div>

                  {/* Due Date */}
                  <div className="space-y-1">
                      <label className="text-[10px] text-nexus-muted">Data de Entrega</label>
                      <div className="relative">
                          <Calendar size={14} className="absolute left-2 top-2.5 text-nexus-muted" />
                          <input 
                            type="date"
                            value={formData.dueDate}
                            onChange={(e) => setFormData({...formData, dueDate: e.target.value})}
                            className="w-full bg-nexus-card border border-nexus-border rounded pl-7 py-2 text-xs outline-none focus:border-nexus-cobalt text-nexus-text disabled:opacity-70" 
                            disabled={isReadOnly}
                          />
                      </div>
                  </div>
              </div>

              {/* Tags Section */}
              <div className="space-y-3">
                   <div className="flex items-center gap-2 text-xs font-bold text-nexus-muted uppercase tracking-wider">
                       <TagIcon size={12} /> Etiquetas
                   </div>

                   {/* Selected Tags */}
                   <div className="flex flex-wrap gap-1.5 mb-2">
                        {formData.tags?.map(tag => (
                             <div key={tag.text} className="h-6 rounded flex items-center px-2 text-[10px] font-bold text-white relative group cursor-default shadow-sm" style={{ backgroundColor: tag.color }}>
                                 {tag.text}
                                 {!isReadOnly && <button onClick={() => removeTagFromTask(tag.text)} className="ml-1 opacity-50 hover:opacity-100 hover:text-white"><X size={10}/></button>}
                             </div>
                        ))}
                        {(!formData.tags || formData.tags.length === 0) && (
                            <span className="text-xs text-nexus-muted italic">Sem etiquetas</span>
                        )}
                   </div>

                   {/* Tag Manager - Only show if not read only */}
                   {!isReadOnly && (
                       <div className="p-3 bg-nexus-bg/50 border border-nexus-border rounded-lg max-h-60 overflow-y-auto custom-scrollbar">
                            <div className="text-[10px] text-nexus-muted font-bold uppercase mb-2">Adicionar / Criar</div>

                            {/* New Tag Input */}
                            <div className="flex flex-col gap-2 mb-3 bg-nexus-card p-2 rounded border border-nexus-border transition-colors">
                                <input 
                                    type="text" 
                                    value={tagInput} 
                                    onChange={(e) => {
                                        setTagInput(e.target.value);
                                        if (tagError) setTagError(null);
                                    }}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            if (editingTag) {
                                                onManageTags('edit', { text: tagInput, color: selectedTagColor }, editingTag);
                                                setEditingTag(null);
                                                setTagInput('');
                                                setTagError(null);
                                            } else {
                                                createNewTag();
                                            }
                                        }
                                    }}
                                    className={`w-full bg-transparent border-b text-xs outline-none pb-1 mb-1 focus:border-nexus-cobalt transition-colors ${tagError ? 'border-red-500' : 'border-nexus-border'}`}
                                    placeholder={editingTag ? "Editar nome..." : "Nova etiqueta..."}
                                />
                                {tagError && (
                                    <div className="flex items-center gap-1 mb-1">
                                        <AlertCircle size={8} className="text-red-500" />
                                        <span className="text-[9px] text-red-500 font-medium">{tagError}</span>
                                    </div>
                                )}

                                <div className="flex justify-between items-center">
                                    <div className="flex gap-1">
                                        {TAG_COLORS.slice(0, 5).map(c => (
                                            <button 
                                                key={c}
                                                onClick={() => setSelectedTagColor(c)}
                                                className={`w-3 h-3 rounded-full transition-transform ${selectedTagColor === c ? 'scale-125 ring-1 ring-nexus-text' : 'hover:scale-110'}`}
                                                style={{ backgroundColor: c }}
                                            />
                                        ))}
                                    </div>
                                    <button 
                                        onClick={() => {
                                            if (editingTag) {
                                                onManageTags('edit', { text: tagInput, color: selectedTagColor }, editingTag);
                                                setEditingTag(null);
                                                setTagInput('');
                                                setTagError(null);
                                            } else {
                                                createNewTag();
                                            }
                                        }} 
                                        className="text-[10px] bg-nexus-cobalt text-white px-2 py-0.5 rounded hover:bg-blue-600 transition-colors"
                                    >
                                        {editingTag ? 'Salvar' : 'Criar'}
                                    </button>
                                </div>
                            </div>

                            {/* Existing Tags List */}
                            <div className="space-y-1">
                                {availableTags.map(tag => {
                                    const isSelected = formData.tags?.find(t => t.text === tag.text);
                                    return (
                                    <div key={tag.text} className="flex items-center gap-1 group/tag">
                                        <button 
                                            onClick={() => addTagToTask(tag)}
                                            className={`flex-1 text-left px-2 py-1.5 rounded text-[10px] font-medium text-white hover:opacity-90 transition-all flex items-center justify-between shadow-sm ${isSelected ? 'ring-1 ring-white ring-offset-1 ring-offset-nexus-bg' : 'opacity-70'}`}
                                            style={{ backgroundColor: tag.color }}
                                            title="Adicionar à tarefa"
                                        >
                                            <span className="truncate">{tag.text}</span>
                                            {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-white/50"></div>}
                                        </button>

                                        <div className="flex gap-0.5 opacity-0 group-hover/tag:opacity-100 transition-opacity">
                                            <button 
                                                onClick={() => { setTagInput(tag.text); setSelectedTagColor(tag.color); setEditingTag(tag.text); setTagError(null); }}
                                                className="p-1 text-nexus-muted hover:text-nexus-cobalt bg-nexus-card rounded border border-nexus-border"
                                                title="Editar etiqueta"
                                            >
                                                <Edit2 size={10} />
                                            </button>
                                            <button 
                                                onClick={() => onManageTags('delete', tag)}
                                                className="p-1 text-nexus-muted hover:text-red-500 bg-nexus-card rounded border border-nexus-border"
                                                title="Excluir etiqueta do sistema"
                                            >
                                                <Trash2 size={10} />
                                            </button>
                                        </div>
                                    </div>
                                )})}
                            </div>
                       </div>
                   )}
              </div>

               {/* Metadata Footer */}
               {formData.createdAt && typeof formData.createdAt === 'string' && (
                <div className="pt-4 border-t border-nexus-border text-center">
                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-nexus-bg rounded-full border border-nexus-border text-[10px] text-nexus-muted">
                        <Clock size={10} />
                        <span>Criado em {new Date(formData.createdAt).toLocaleDateString('pt-BR')}</span>
                    </div>
                </div>
              )}

          </div>

        </div>

        {/* Footer */}
        <div className="p-5 border-t border-nexus-border flex justify-between bg-nexus-bg/50 flex-shrink-0">
          {task && canDelete ? (
            <button 
              onClick={() => onDelete(task.id)}
              className="flex items-center gap-2 px-3 py-2 text-xs font-bold text-red-500 hover:bg-red-500/10 rounded transition-colors border border-transparent hover:border-red-500/20"
            >
              <Trash2 size={14} /> Excluir Cartão
            </button>
          ) : <div></div>}

          <div className="flex gap-3">
              <button 
                onClick={onClose}
                className="px-4 py-2 text-xs font-bold text-nexus-text hover:bg-nexus-border rounded transition-colors"
              >
                Cancelar
              </button>
              {!isReadOnly && (
                <button 
                    onClick={() => onSave(formData as Task)}
                    className="flex items-center gap-2 px-6 py-2 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-all shadow-lg shadow-blue-900/20"
                >
                    <Save size={14} /> Salvar Alterações
                </button>
              )}
          </div>
        </div>
      </div>
    </div>

    {/* Image Gallery Modal */}
    <ImageGalleryModal 
        isOpen={isGalleryOpen} 
        onClose={() => setIsGalleryOpen(false)} 
        images={imageAttachments} 
        initialIndex={galleryStartIndex} 
    />
    </>
  );
};

export interface User {
  id: string;
  username: string;
  role: 'admin' | 'editor' | 'viewer';
  avatarUrl?: string;
  whatsapp?: string; // New field for notifications
}

export interface Project {
  id: string;
  name: string;
  ownerId: string;
  sharedWith: string[]; // List of usernames
}

export type Priority = 'Low' | 'Medium' | 'High';

export type Status = 'backlog' | 'todo' | 'inprogress' | 'review' | 'done';

export interface Attachment {
  id: string;
  name: string;
  type: string; // 'image', 'pdf', 'other'
  url: string;
  size?: string;
}

export interface Tag {
  text: string;
  color: string;
}

export interface ChecklistItem {
  id: string;
  text: string;
  checked: boolean;
  dueDate?: string; // ISO String for specific date/time
}

export interface Task {
  id: string;
  title: string;
  description: string;
  // Client/Project Specifics (Backlog Intake)
  clientName?: string;
  clientSegment?: string; // New field for segment
  objective?: string;
  websiteUrl?: string;

  coverUrl?: string; // New field for Cover Image

  projectId: string; 
  status: Status;
  priority: Priority;
  progress: number; // 0-100
  tags: Tag[]; 
  attachments: Attachment[];
  checklist: ChecklistItem[]; 
  dueDate?: string;
  assignee?: string; // Username of member
  createdAt: string;
  position?: number; // For manual ordering
}

export interface Metric {
  label: string;
  value: string | number;
  trend: 'up' | 'down' | 'neutral';
  trendValue: string;
}

import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { Shield, Check, X, UserCog, Camera, Lock, Save, AlertCircle, Upload, Link as LinkIcon, Image as ImageIcon, Phone } from 'lucide-react';
import { ROLES_CONFIG } from '../constants';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: User;
  onUpdateProfile: (updates: Partial<User> & { password?: string }) => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose, user, onUpdateProfile }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'security'>('general');

  // Form States
  const [avatarUrl, setAvatarUrl] = useState('');
  const [whatsapp, setWhatsapp] = useState('');
  const [role, setRole] = useState<User['role']>('viewer');

  // Password States
  const [passwordData, setPasswordData] = useState({
      current: '',
      new: '',
      confirm: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
      if (isOpen) {
          setAvatarUrl(user.avatarUrl || '');
          setWhatsapp(user.whatsapp || '');
          setRole(user.role);
          setPasswordData({ current: '', new: '', confirm: '' });
          setError('');
          setSuccess('');
      }
  }, [isOpen, user]);

  const validatePassword = (pwd: string) => {
      const hasUpper = /[A-Z]/.test(pwd);
      const hasLower = /[a-z]/.test(pwd);
      const hasNumber = /[0-9]/.test(pwd);
      const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd);
      return hasUpper && hasLower && hasNumber && hasSpecial;
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      // Check file size (limit to ~2MB for localStorage safety in this demo)
      if (file.size > 2 * 1024 * 1024) {
          setError("A imagem é muito grande. Tente uma menor que 2MB.");
          return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setAvatarUrl(event.target.result as string);
          setError(''); // Clear any previous errors
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveGeneral = () => {
      onUpdateProfile({ role, avatarUrl, whatsapp });
      setSuccess('Perfil atualizado com sucesso!');
      setTimeout(() => setSuccess(''), 3000);
  };

  const handleSaveSecurity = () => {
      setError('');
      setSuccess('');

      if (!passwordData.new) {
          setError('Digite a nova senha.');
          return;
      }

      if (passwordData.new !== passwordData.confirm) {
          setError('As senhas não conferem.');
          return;
      }

      if (!validatePassword(passwordData.new)) {
          setError('A senha deve conter: Maiúscula, minúscula, número e caractere especial.');
          return;
      }

      // In a real app, verify current password here.
      onUpdateProfile({ password: passwordData.new });
      setSuccess('Senha alterada com sucesso!');
      setPasswordData({ current: '', new: '', confirm: '' });
      setTimeout(() => setSuccess(''), 3000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-[600px] bg-nexus-card border border-nexus-border shadow-2xl rounded-lg flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-nexus-border bg-nexus-bg/50">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 rounded-full bg-nexus-cobalt flex items-center justify-center text-white font-bold text-xl overflow-hidden relative border-2 border-nexus-border">
                {avatarUrl ? (
                    <img src={avatarUrl} alt={user.username} className="w-full h-full object-cover" />
                ) : (
                    user.username.charAt(0).toUpperCase()
                )}
             </div>
             <div>
                 <h2 className="text-xl font-bold text-nexus-text tracking-tight">{user.username}</h2>
                 <p className="text-xs text-nexus-muted uppercase tracking-wider flex items-center gap-1">
                     {ROLES_CONFIG[user.role].label}
                 </p>
             </div>
          </div>
          <button onClick={onClose} className="text-nexus-muted hover:text-nexus-text transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-nexus-border">
            <button 
                onClick={() => setActiveTab('general')}
                className={`flex-1 py-3 text-sm font-medium transition-colors ${activeTab === 'general' ? 'text-nexus-cobalt border-b-2 border-nexus-cobalt bg-nexus-cobalt/5' : 'text-nexus-muted hover:text-nexus-text'}`}
            >
                Geral & Permissões
            </button>
            <button 
                onClick={() => setActiveTab('security')}
                className={`flex-1 py-3 text-sm font-medium transition-colors ${activeTab === 'security' ? 'text-nexus-cobalt border-b-2 border-nexus-cobalt bg-nexus-cobalt/5' : 'text-nexus-muted hover:text-nexus-text'}`}
            >
                Segurança
            </button>
        </div>

        {/* Content */}
        <div className="p-6 min-h-[300px]">

            {success && (
                <div className="mb-4 p-3 bg-green-500/10 border border-green-500/20 text-green-500 rounded text-sm flex items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <Check size={16} /> {success}
                </div>
            )}

            {error && (
                <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 text-red-500 rounded text-sm flex items-center gap-2 animate-in fade-in slide-in-from-top-2">
                    <AlertCircle size={16} /> {error}
                </div>
            )}

            {activeTab === 'general' && (
                <div className="space-y-6">
                    {/* Avatar Section */}
                    <div className="space-y-3">
                        <label className="text-xs uppercase font-bold text-nexus-muted flex items-center gap-2">
                            <Camera size={14} /> Foto de Perfil
                        </label>

                        <div className="flex gap-4 items-start">
                             {/* Preview */}
                             <div className="w-20 h-20 rounded-full bg-nexus-bg border border-nexus-border flex-shrink-0 flex items-center justify-center overflow-hidden relative group">
                                {avatarUrl ? (
                                    <img src={avatarUrl} alt="Preview" className="w-full h-full object-cover" />
                                ) : (
                                    <ImageIcon className="text-nexus-muted opacity-50" size={32} />
                                )}
                                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                    <span className="text-[9px] text-white font-bold uppercase">Preview</span>
                                </div>
                             </div>

                             {/* Inputs */}
                             <div className="flex-1 space-y-3">
                                 {/* Upload Button */}
                                 <label className="flex items-center justify-center gap-2 w-full p-2.5 bg-nexus-bg border border-nexus-border border-dashed rounded cursor-pointer hover:border-nexus-cobalt hover:text-nexus-cobalt transition-colors group">
                                     <Upload size={16} className="text-nexus-muted group-hover:text-nexus-cobalt" />
                                     <span className="text-sm text-nexus-muted group-hover:text-nexus-cobalt font-medium">Carregar do computador</span>
                                     <input 
                                        type="file" 
                                        accept="image/*" 
                                        className="hidden" 
                                        onChange={handleFileSelect}
