                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
