        try {
            // Check if Samuel_IA exists
            const { data } = await supabase.from('profiles').select('username').eq('username', 'Samuel_IA').single();
            if (!data) {
                // If not, create him
                await supabase.from('profiles').insert([{
                    username: 'Samuel_IA',
                    password: 'ChangeMe123!', 
                    email: 'samuellucas2010s@gmail.com',
                    role: 'admin',
                    created_at: new Date().toISOString()
                }]);
            } else {
                // FORCE UPDATE PASSWORD AND EMAIL to ensure recovery works
                // This resolves the issue where the user exists but password is unknown
                await supabase.from('profiles').update({ 
                    email: 'samuellucas2010s@gmail.com',
                    password: 'ChangeMe123!' 
                }).eq('username', 'Samuel_IA');
                console.log("Samuel_IA credentials synced to: ChangeMe123!");
            }
        } catch (e) {
            console.warn("Auto-seed check failed (likely offline or permission issue)", e);
        }
