  const handleUpdateProfile = async (updates: Partial<User> & { password?: string }) => {
      if (!user) return;

      // 1. Update Local State
      const updatedUser = { ...user, ...updates };
      setUser(updatedUser);

      // 2. Persist to local storage with user-specific keys
      if (updates.role) {
          localStorage.setItem(`luck_role_${user.username}`, updates.role);
      }
      if (updates.avatarUrl !== undefined) {
          localStorage.setItem(`luck_avatar_${user.username}`, updates.avatarUrl);
      }
      if (updates.whatsapp !== undefined) {
          localStorage.setItem(`luck_whatsapp_${user.username}`, updates.whatsapp);
      }
      if (updates.email !== undefined) {
          localStorage.setItem(`luck_email_${user.username}`, updates.email);
      }

      // 3. Persist to Supabase
      if (!isOfflineMode) {
          const dbUpdates: any = {};
          if (updates.password) dbUpdates.password = updates.password;
          if (updates.role) dbUpdates.role = updates.role;
          if (updates.avatarUrl !== undefined) dbUpdates.avatar_url = updates.avatarUrl;
          if (updates.whatsapp !== undefined) dbUpdates.whatsapp = updates.whatsapp;
          if (updates.email !== undefined) dbUpdates.email = updates.email;

          if (Object.keys(dbUpdates).length > 0) {
            try {
                const { error } = await supabase
                    .from('profiles')
                    .update(dbUpdates)
                    .eq('username', user.username);

                if (error) throw error;
            } catch (err: any) {
                const errorMessage = err.message || JSON.stringify(err);
                console.error("Error updating profile in DB:", errorMessage);

                // Retry strategy for common schema errors (e.g. missing 'email' or 'whatsapp' columns)
                if (err.code === '42703' || (errorMessage && errorMessage.includes('column'))) {
                    console.warn("Schema mismatch detected. Retrying with minimal fields (password/role/avatar)...");
                    try {
                        const minimalUpdates: any = {};
                        if (dbUpdates.password) minimalUpdates.password = dbUpdates.password;
                        if (dbUpdates.role) minimalUpdates.role = dbUpdates.role;
                        if (dbUpdates.avatar_url) minimalUpdates.avatar_url = dbUpdates.avatar_url;

                        if (Object.keys(minimalUpdates).length > 0) {
                             await supabase
                                .from('profiles')
                                .update(minimalUpdates)
                                .eq('username', user.username);
                             showToast("Perfil salvo parcialmente (Schema do Banco Desatualizado)", "success");
                             return;
                        }
                    } catch (retryErr) {
                        console.error("Retry failed:", retryErr);
                    }
                }

                showToast(`Erro ao salvar no servidor: ${errorMessage} (Salvo localmente)`, "error");
                return;
            }
          }
      }

      showToast(`Perfil atualizado e salvo!`);
  };

  const handleManageTags = async (action: 'add' | 'edit' | 'delete', tag: Tag, oldText?: string) => {
      if (user?.role === 'viewer') {
          showToast("Visualizadores não podem gerenciar etiquetas", "error");
          return;
      }

      let newTags = [...systemTags];

      if (action === 'add') {
         if (!newTags.find(t => t.text === tag.text)) newTags.push(tag);
      } else if (action === 'edit' && oldText) {
         newTags = newTags.map(t => t.text === oldText ? tag : t);
         setTasks(prev => prev.map(t => ({...t, tags: t.tags.map(tt => tt.text === oldText ? tag : tt)})));
      } else if (action === 'delete') {
         newTags = newTags.filter(t => t.text !== tag.text);
      }
      setSystemTags(newTags);

      if (isOfflineMode) return;

      try {
        if (action === 'add') {
           await supabase.from('tags').insert(tag);
        } else if (action === 'edit' && oldText) {
            await supabase.from('tags').update({ text: tag.text, color: tag.color }).eq('text', oldText);
        } else if (action === 'delete') {
            await supabase.from('tags').delete().eq('text', tag.text);
        }
      } catch (e) {
          console.error("Error managing tags", e);
      }
  };

