        localStorage.setItem(`luck_whatsapp_${userWithRole.username}`, userWithRole.whatsapp);
    }
    if (userWithRole.avatarUrl) {
        localStorage.setItem(`luck_avatar_${userWithRole.username}`, userWithRole.avatarUrl);
