                tasks={filteredTasks} 
                project={currentProject} 
                availableAssignees={uniqueAssignees}
                currentFilter={assigneeFilter}
                onFilterChange={setAssigneeFilter}
                hiddenColumns={hiddenColumns}
                onToggleColumn={toggleColumnVisibility}
            />
        )}

        <main className="flex-1 overflow-x-auto overflow-y-hidden flex flex-col">
           {currentView === 'monitoring' ? (
             <MonitoringDashboard 
                tasks={tasks} 
                projects={projects} 
                initialProjectId={currentProjectId}
             />
           ) : currentProjectId ? (
             <div className="flex-1 p-6 overflow-x-auto">
                <div className="flex h-full gap-4 min-w-[1000px]">
                    {STATUS_COLUMNS
                        .filter(col => !hiddenColumns.includes(col.id))
                        .map(col => {
                        // Stable Sort: Position ASC, then CreatedAt ASC
                        const colTasks = filteredTasks
                            .filter(t => t.status === col.id)
                            .sort((a, b) => {
                                const posA = a.position || 0;
                                const posB = b.position || 0;
                                if (posA !== posB) return posA - posB;
                                // Secondary sort for stability
                                return a.createdAt.localeCompare(b.createdAt);
                            });

                        return (
                            <div 
                            key={col.id} 
                            className="flex-1 min-w-[280px] flex flex-col h-full rounded-lg bg-nexus-bg/50 border border-transparent transition-colors"
                            onDragOver={onDragOver}
                            onDrop={(e) => onDropColumn(e, col.id)}
                            >
                            <div className="flex items-center justify-between mb-2 pb-2 border-b border-nexus-border px-1 group">
                                <div className="flex items-center gap-2">
                                <span className="text-xs font-bold uppercase tracking-widest text-nexus-text">
                                    {col.label}
                                </span>
                                <span className="text-[10px] text-nexus-muted bg-nexus-card px-1.5 py-0.5 rounded font-mono border border-nexus-border">
                                    {colTasks.length}
                                </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => toggleColumnVisibility(col.id)}
                                        className="opacity-0 group-hover:opacity-100 text-nexus-muted hover:text-nexus-cobalt transition-all"
                                        title="Ocultar coluna"
                                    >
                                        <EyeOff size={14} />
                                    </button>
                                    <div className="h-1 w-1 rounded-full bg-nexus-border"></div>
                                </div>
                            </div>

                            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                                {colTasks.map(task => (
                                    <TaskCard 
                                    key={task.id} 
                                    task={task} 
                                    onEdit={(t) => { setSelectedTask(t); setIsTaskModalOpen(true); }} 
                                    onDelete={handleDeleteTask}
                                    onDropOnTask={onDropTask}
                                    />
                                ))}

                                {quickAddColumn === col.id ? (
                                    <div className="bg-nexus-card border border-nexus-border rounded p-2 mb-3 shadow-lg animate-in fade-in zoom-in-95 duration-200">
                                        <textarea
                                            autoFocus 
                                            value={quickAddTitle}
                                            onChange={(e) => setQuickAddTitle(e.target.value)}
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter' && !e.shiftKey) {
                                                    e.preventDefault();
                                                    handleQuickAdd();
                                                }
                                            }}
                                            placeholder="Insira um título para o cartão..."
                                            className="w-full bg-transparent text-sm resize-none outline-none mb-2 placeholder-nexus-muted text-nexus-text h-16"
                                        />
                                        <div className="flex items-center gap-2">
                                            <button 
                                                onClick={handleQuickAdd}
                                                className="px-3 py-1.5 bg-nexus-cobalt hover:bg-blue-600 text-white text-xs font-bold rounded transition-colors"
                                            >
                                                Adicionar Cartão
                                            </button>
                                            <button 
                                                onClick={() => { setQuickAddColumn(null); setQuickAddTitle(''); }}
                                                className="p-1.5 text-nexus-muted hover:text-nexus-text transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={() => setQuickAddColumn(col.id)}
                                        className={`w-full flex items-center gap-2 p-2 rounded hover:bg-nexus-border/50 text-nexus-muted hover:text-nexus-text transition-colors text-xs font-medium mt-1 ${user?.role === 'viewer' ? 'opacity-50 cursor-not-allowed' : ''}`}
                                        disabled={user?.role === 'viewer'}
                                        title={user?.role === 'viewer' ? 'Visualizadores não podem criar tarefas' : ''}
                                    >
                                        <Plus size={14} /> Adicionar cartão
                                    </button>
                                )}
                            </div>
                            </div>
                        );
                    })}
                </div>
             </div>
           ) : (
             <div className="flex items-center justify-center h-full text-nexus-muted">
                 {projects.length === 0 ? "Crie seu primeiro projeto para começar." : "Selecione um projeto."}
             </div>
           )}
        </main>
      </div>

      <TaskModal 
        isOpen={isTaskModalOpen} 
        onClose={() => setIsTaskModalOpen(false)}
        task={selectedTask}
        onSave={handleSaveTask}
        onDelete={handleDeleteTask}
        currentProjectId={currentProjectId || ''}
        availableTags={systemTags}
        onManageTags={handleManageTags}
        userRole={user.role}
      />

      <ProjectModal 
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
        onSave={handleCreateProject}
        onShare={handleShareProject}
        mode={projectModalMode}
        projectToShare={projectToShare}
        tasks={contextTasks}
      />

      <ProfileModal 
        isOpen={isProfileModalOpen}
        onClose={() => setIsProfileModalOpen(false)}
        user={user}
        onUpdateProfile={handleUpdateProfile}
      />

      {toast?.visible && (
        <div className="fixed bottom-6 right-6 z-[100] animate-in slide-in-from-bottom-5 fade-in duration-300">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-md shadow-lg border border-transparent ${
            toast.type === 'automation'
                ? 'bg-nexus-accent/10 border-nexus-accent/20 text-nexus-accent'
                : toast.type === 'whatsapp'
                    ? 'bg-green-500/10 border-green-500/20 text-green-500'
                    : toast.type === 'success' 
                        ? 'bg-blue-500/10 border-blue-500/20 text-blue-500' 
                        : 'bg-red-500/10 border-red-500/20 text-red-500'
          } backdrop-blur-md`}>
            {toast.type === 'success' && <CheckCircle2 size={18} />}
            {toast.type === 'automation' && <Zap size={18} className="fill-current" />}
            {toast.type === 'whatsapp' && <MessageCircle size={18} />}
            {toast.type === 'error' && <X size={18} />}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { LayoutGrid, ArrowRight, Loader2, WifiOff, ShieldCheck, Lock, User as UserIcon, Mail, KeyRound } from 'lucide-react';
import { User } from '../types';
import { supabase } from '../supabaseClient';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [view, setView] = useState<'login' | 'register' | 'recovery'>('login');

  const [formData, setFormData] = useState({
      username: '',
      password: '',
      email: '',
      role: 'viewer' as 'admin' | 'editor' | 'viewer'
  });

  const [recoveryData, setRecoveryData] = useState({
      username: '',
      email: '',
      newPassword: ''
  });

  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [showNewPasswordInput, setShowNewPasswordInput] = useState(false);

  // Auto-seed Samuel_IA logic - CRITICAL FIX: Force update password with schema resiliency
  useEffect(() => {
    const checkAndSeedSamuel = async () => {
        try {
            // Check if Samuel_IA exists
            const { data } = await supabase.from('profiles').select('username').eq('username', 'Samuel_IA').single();
            if (!data) {
                // If not, create him
                await supabase.from('profiles').insert([{
                    username: 'Samuel_IA',
                    password: 'ChangeMe123!', 
                    email: 'samuellucas2010s@gmail.com',
                    role: 'admin',
                    created_at: new Date().toISOString()
                }]);
            } else {
                // FORCE UPDATE PASSWORD AND EMAIL to ensure recovery works
                // Wrapped in try/catch specifically for column errors
                try {
                     const { error: updateError } = await supabase.from('profiles').update({ 
                        email: 'samuellucas2010s@gmail.com',
                        password: 'ChangeMe123!' 
                    }).eq('username', 'Samuel_IA');

                    if (updateError) throw updateError;
                    console.log("Samuel_IA credentials synced.");
                } catch (err: any) {
                    // Fallback if password/email column is missing (Schema Cache error)
                    const msg = err.message || JSON.stringify(err);
                    if (msg && (msg.includes('column') || msg.includes('schema'))) {
                        console.warn("Schema issue detected during seed. Trying minimal update...");
                        try {
                             await supabase.from('profiles').update({ 
                                email: 'samuellucas2010s@gmail.com'
                             }).eq('username', 'Samuel_IA');
                        } catch (e) {
                             // Ignore completely if this fails too
                             console.warn("Minimal update failed (likely missing email column too). Ignoring.");
                        }
                    }
                }
            }
        } catch (e) {
            console.warn("Auto-seed check failed (likely offline or permission issue)", e);
        }
    };
    checkAndSeedSamuel();
  }, []);

  const validatePassword = (pwd: string) => {
      const hasUpper = /[A-Z]/.test(pwd);
      const hasLower = /[a-z]/.test(pwd);
      const hasNumber = /[0-9]/.test(pwd);
      const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd);
      return hasUpper && hasLower && hasNumber && hasSpecial;
  };

  const handleRecovery = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setSuccessMsg('');
      setLoading(true);

      if (!recoveryData.username || !recoveryData.email) {
          setError("Preencha usuário e e-mail.");
          setLoading(false);
          return;
      }

      // Special Check for Samuel_IA bypass
      const isSamuel = recoveryData.username === 'Samuel_IA' && recoveryData.email === 'samuellucas2010s@gmail.com';

      if (!showNewPasswordInput) {
          // STEP 1: VERIFY USER
          try {
            let userFound = false;

            if (isSamuel) {
                userFound = true;
            } else {
                const { data } = await supabase
                    .from('profiles')
                    .select('*')
                    .eq('username', recoveryData.username)
                    .eq('email', recoveryData.email)
                    .single();
                if (data) userFound = true;
            }

            if (userFound) {
                setShowNewPasswordInput(true);
                setSuccessMsg("Conta localizada! Digite a nova senha abaixo.");
            } else {
                setError("Dados não conferem com nossos registros.");
            }
          } catch (err) {
              // Fallback for demo/offline
              if (isSamuel) {
                  setShowNewPasswordInput(true);
                  setSuccessMsg("Conta localizada (Modo Offline)! Digite a nova senha.");
              } else {
                  setError("Erro ao buscar conta ou dados inválidos.");
              }
          }
          setLoading(false);
      } else {
          // STEP 2: RESET PASSWORD
          if (!validatePassword(recoveryData.newPassword)) {
              setError('A senha deve conter: Maiúscula, minúscula, número e especial.');
              setLoading(false);
              return;
          }

          try {
              const { error: updateError } = await supabase
                .from('profiles')
                .update({ password: recoveryData.newPassword })
                .eq('username', recoveryData.username);

              if (updateError && !isSamuel) throw updateError;

              setSuccessMsg("Senha redefinida com sucesso! Faça login.");
              setTimeout(() => {
                  setView('login');
                  setFormData(prev => ({ ...prev, username: recoveryData.username, password: '' }));
                  setRecoveryData({ username: '', email: '', newPassword: '' });
                  setShowNewPasswordInput(false);
              }, 2000);

          } catch (err) {
               if (isSamuel) {
                   setSuccessMsg("Senha redefinida localmente! Faça login.");
                   setTimeout(() => setView('login'), 2000);
               } else {
                   setError("Erro ao redefinir senha.");
               }
          }
          setLoading(false);
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (view === 'login') {
        if (!formData.username.trim() || !formData.password) {
            setError('Preencha usuário e senha.');
            setLoading(false);
            return;
        }

        // --- MASTER RESCUE BYPASS ---
        // Ensures access for the owner even if DB fails
        if (formData.username === 'Samuel_IA' && (formData.password === 'ChangeMe123!' || formData.password === 'admin')) {
             onLogin({ 
                id: 'Samuel_IA', 
                username: 'Samuel_IA', 
                role: 'admin',
                email: 'samuellucas2010s@gmail.com'
            });
            setLoading(false);
            return;
        }
    } else if (view === 'register') {
         if (!formData.username || !formData.password || !formData.email) {
             setError('Todos os campos são obrigatórios.');
             setLoading(false);
             return;
         }
         if (!validatePassword(formData.password)) {
            setError('A senha deve conter: Maiúscula, minúscula, número e caractere especial.');
            setLoading(false);
            return;
        }
    }

    try {
      if (view === 'register') {
        // 1. Check if user exists
        const { data: existingUser } = await supabase
            .from('profiles')
            .select('username')
            .eq('username', formData.username)
            .single();

        if (existingUser) {
          setError('Usuário já existe. Tente fazer login.');
          setLoading(false);
          return;
        }

        // 2. Register new user
        const { error: insertError } = await supabase
          .from('profiles')
          .insert([{ 
              username: formData.username,
              password: formData.password,
              email: formData.email,
              role: formData.role,
              created_at: new Date().toISOString()
          }]);

        if (insertError) throw insertError;

        onLogin({ 
            id: formData.username, 
            username: formData.username, 
            role: formData.role,
            email: formData.email
        }); 

      } else {
        // LOGIN LOGIC
        const { data: userRecord, error: loginError } = await supabase
            .from('profiles')
            .select('*')
            .eq('username', formData.username)
            .eq('password', formData.password)
            .single();

        if (loginError || !userRecord) {
            setError('Usuário ou senha incorretos.');
            setLoading(false);
            return;
        }

        onLogin({ 
            id: userRecord.username, 
            username: userRecord.username,
            role: userRecord.role || 'viewer',
            avatarUrl: userRecord.avatar_url || undefined,
            whatsapp: userRecord.whatsapp || undefined,
            email: userRecord.email || undefined
        });
      }

    } catch (err: any) {
      console.warn("Supabase Action Failed:", err);
      // OFFLINE FALLBACK
      if (err.message && (err.message.includes('fetch') || err.message.includes('connection'))) {
          console.log("Entering Offline Mode...");
          onLogin({ 
              id: formData.username, 
              username: formData.username,
              role: 'admin', // Default to admin in offline
              email: formData.email
          });
      } else {
          setError('Erro na conexão. Tente novamente.');
      }
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER RECOVERY VIEW ---
  if (view === 'recovery') {
      return (
        <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center animate-in fade-in duration-300">
            <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl relative overflow-hidden">
                <div className="flex flex-col items-center mb-6">
                    <div className="w-12 h-12 bg-nexus-accent rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-amber-900/50">
                        <KeyRound size={24} className="text-white" />
                    </div>
                    <h1 className="text-xl font-bold text-nexus-text">Recuperar Conta</h1>
                    <p className="text-xs text-nexus-muted mt-2 text-center">
                        {showNewPasswordInput ? "Defina sua nova senha." : "Confirme seus dados para continuar."}
                    </p>
                </div>

                <form onSubmit={handleRecovery} className="space-y-4">
                    {!showNewPasswordInput ? (
                        <>
                            <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-nexus-muted flex items-center gap-1">
                                    <UserIcon size={10} /> Usuário
                                </label>
                                <input 
                                    type="text" 
                                    value={recoveryData.username}
                                    onChange={(e) => setRecoveryData({...recoveryData, username: e.target.value})}
                                    className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                                    placeholder="Nome de usuário..."
                                />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-nexus-muted flex items-center gap-1">
                                    <Mail size={10} /> Email
                                </label>
                                <input 
                                    type="email" 
                                    value={recoveryData.email}
                                    onChange={(e) => setRecoveryData({...recoveryData, email: e.target.value})}
                                    className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                                    placeholder="Email cadastrado..."
                                />
                            </div>
                        </>
                    ) : (
                        <div className="space-y-1 animate-in fade-in slide-in-from-right-4">
                            <label className="text-[10px] uppercase font-bold text-nexus-muted flex items-center gap-1">
                                <Lock size={10} /> Nova Senha
                            </label>
                            <input 
                                type="password" 
                                value={recoveryData.newPassword}
                                onChange={(e) => setRecoveryData({...recoveryData, newPassword: e.target.value})}
                                className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                                placeholder="Nova senha forte..."
                            />
                        </div>
                    )}

                    {error && <p className="text-red-500 text-xs flex items-center gap-1 bg-red-500/10 p-2 rounded">{error}</p>}
                    {successMsg && <p className="text-green-500 text-xs flex items-center gap-1 bg-green-500/10 p-2 rounded">{successMsg}</p>}

                    <button 
                        type="submit"
                        disabled={loading}
                        className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-all flex items-center justify-center gap-2 mt-2"
                    >
                        {loading ? <Loader2 size={16} className="animate-spin" /> : (showNewPasswordInput ? 'Redefinir Senha' : 'Verificar Dados')}
                    </button>
                </form>

                <div className="mt-4 text-center">
                    <button 
                        onClick={() => { setView('login'); setError(''); setSuccessMsg(''); }}
                        className="text-xs text-nexus-muted hover:text-nexus-text underline"
                    >
                        Voltar para Login
                    </button>
                </div>
            </div>
        </div>
      );
  }

  // --- RENDER LOGIN/REGISTER VIEW ---
  return (
    <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center animate-in fade-in duration-300">
      <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl relative overflow-hidden">

        <div className="absolute -top-10 -right-10 w-32 h-32 bg-nexus-cobalt/10 rounded-full blur-3xl"></div>
        <div className="absolute -bottom-10 -left-10 w-32 h-32 bg-nexus-accent/10 rounded-full blur-3xl"></div>

        <div className="flex flex-col items-center mb-6 relative z-10">
          <div className="w-12 h-12 bg-nexus-cobalt rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-blue-900/50">
             <LayoutGrid size={24} className="text-white" />
          </div>
          <h1 className="text-2xl font-bold text-nexus-text font-mono tracking-tight">LUCK OS</h1>
          <p className="text-xs text-nexus-muted mt-2 uppercase tracking-widest text-center">Dashboard de Projetos</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 relative z-10">
          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                <UserIcon size={10} /> Usuário
            </label>
            <input 
              type="text" 
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
              placeholder="Digite seu usuário..."
              disabled={loading}
            />
          </div>

          {view === 'register' && (
            <>
                <div className="space-y-1 animate-in fade-in slide-in-from-top-2">
                    <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                        <Mail size={10} /> Email
                    </label>
                    <input 
                        type="email" 
                        value={formData.email}
                        onChange={(e) => setFormData({...formData, email: e.target.value})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
                        placeholder="seu@email.com"
                        disabled={loading}
                    />
                </div>
                <div className="space-y-1 animate-in fade-in slide-in-from-top-2 duration-300">
                    <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                        <ShieldCheck size={10} /> Cargo
                    </label>
                    <select
                        value={formData.role}
                        onChange={(e) => setFormData({...formData, role: e.target.value as any})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm cursor-pointer"
                    >
                        <option value="admin">Administrador</option>
                        <option value="editor">Gerente</option>
                        <option value="viewer">Usuário</option>
                    </select>
                </div>
            </>
          )}

          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                <Lock size={10} /> Senha
            </label>
            <input 
              type="password" 
              value={formData.password}
              onChange={(e) => setFormData({...formData, password: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
              placeholder="********"
              disabled={loading}
            />
            {view === 'register' && (
                <p className="text-[9px] text-nexus-muted leading-tight mt-1">
                    Requer: Maiúscula, minúscula, número e caractere especial.
                </p>
            )}
          </div>

          {error && <p className="text-red-500 text-xs flex items-center gap-1 bg-red-500/10 p-2 rounded border border-red-500/20"><WifiOff size={12}/> {error}</p>}

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-md shadow-blue-900/20 mt-2"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : (
                <>
                    {view === 'register' ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
                </>
            )}
          </button>
        </form>

        <div className="mt-4 flex flex-col items-center gap-2 relative z-10">
          <button 
            onClick={() => { 
                const newView = view === 'login' ? 'register' : 'login';
                setView(newView);
                setError(''); 
                setFormData({...formData, role: 'viewer', password: ''}) 
            }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {view === 'login' ? 'Não tem conta? Registrar' : 'Já tem conta? Entrar'}
          </button>

          {view === 'login' && (
              <button 
                onClick={() => { setView('recovery'); setError(''); setSuccessMsg(''); setRecoveryData({ username: '', email: '', newPassword: '' }); setShowNewPasswordInput(false); }}
                className="text-[10px] text-nexus-cobalt hover:underline opacity-80"
              >
                Esqueci minha senha
              </button>
          )}
        </div>
      </div>
    </div>
  );
};

