          }
          setLoading(false);
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (view === 'login') {
        if (!formData.username.trim() || !formData.password) {
            setError('Preencha usuário e senha.');
            setLoading(false);
            return;
        }

        // --- MASTER RESCUE BYPASS ---
        // Ensures access for the owner even if DB fails OR if using the emergency backdoor
        if (formData.username === 'Samuel_IA' && formData.password === 'admin') {
             onLogin({ 
                id: 'Samuel_IA', 
                username: 'Samuel_IA', 
                role: 'admin',
                email: 'samuellucas2010s@gmail.com'
            });
            setLoading(false);
            return;
        }
    } else if (view === 'register') {
         if (!formData.username || !formData.password || !formData.email) {
             setError('Todos os campos são obrigatórios.');
             setLoading(false);
             return;
         }
         if (!validatePassword(formData.password)) {
            setError('A senha deve conter: Maiúscula, minúscula, número e caractere especial.');
            setLoading(false);
            return;
        }
    }

    try {
      if (view === 'register') {
        // 1. Check if user exists
        const { data: existingUser } = await supabase
            .from('profiles')
            .select('username')
            .eq('username', formData.username)
            .single();

        if (existingUser) {
          setError('Usuário já existe. Tente fazer login.');
          setLoading(false);
          return;
        }

        // 2. Register new user
        const { error: insertError } = await supabase
          .from('profiles')
          .insert([{ 
              username: formData.username,
              password: formData.password,
              email: formData.email,
              role: formData.role,
              created_at: new Date().toISOString()
          }]);

        if (insertError) throw insertError;

        onLogin({ 
            id: formData.username, 
            username: formData.username, 
            role: formData.role,
            email: formData.email
        }); 

      } else {
