        const { data: userRecord, error: loginError } = await supabase
            .from('profiles')
            .select('*')
            .eq('username', formData.username)
            .eq('password', formData.password)
            .single();

        if (loginError || !userRecord) {
            setError('Usuário ou senha incorretos.');
            setLoading(false);
