import React, { useMemo, useState } from 'react';
import { Task, Project, Status, ViewMode } from '../types';
import { TrendingUp, Clock, CheckCircle2, Filter, Eye, Layout, PlusCircle, Kanban, List, Table2 } from 'lucide-react';
import { STATUS_COLUMNS } from '../constants';

interface MetricsHeaderProps {
  tasks: Task[];
  project?: Project;
  availableAssignees?: string[];
  currentFilter?: string | null;
  onFilterChange?: (assignee: string | null) => void;
  hiddenColumns: Status[];
  onToggleColumn: (status: Status) => void;
  currentView: ViewMode;
  onViewChange: (view: ViewMode) => void;
}

export const MetricsHeader: React.FC<MetricsHeaderProps> = ({ 
  tasks, 
  project, 
  availableAssignees = [], 
  currentFilter, 
  onFilterChange,
  hiddenColumns,
  onToggleColumn,
  currentView,
  onViewChange
}) => {
  const [showColumnMenu, setShowColumnMenu] = useState(false);

  const metrics = useMemo(() => {
    const total = tasks.length;
    const done = tasks.filter(t => t.status === 'done').length;

    // Calculate simple completion rate
    const completionRate = total === 0 ? 0 : Math.round((done / total) * 100);

    // Calculate "velocity" (mocked based on progress of active tasks)
    const activeTasks = tasks.filter(t => t.status === 'inprogress' || t.status === 'review');
    const velocity = activeTasks.reduce((acc, curr) => acc + curr.progress, 0) / (activeTasks.length || 1);

    return [
      { label: 'Tarefas Ativas', value: total - done, icon: Clock, color: 'text-nexus-text' },
      { label: 'Conclusão', value: `${completionRate}%`, icon: CheckCircle2, color: 'text-nexus-cobalt' },
      { label: 'Velocidade', value: Math.round(velocity), icon: TrendingUp, color: 'text-nexus-accent' },
    ];
  }, [tasks]);

  return (
    <header className="h-20 border-b border-nexus-border bg-nexus-bg/80 backdrop-blur-md sticky top-0 z-10 flex items-center justify-between px-8">
      <div>
        <h1 className="text-xl font-bold text-nexus-text tracking-tight flex items-center gap-2">
          {project ? project.name : 'Dashboard'} <span className="text-nexus-muted font-light hidden sm:inline-block">Overview</span>
        </h1>
        <p className="text-xs text-nexus-muted font-mono mt-0.5">
           {project ? (project.sharedWith.length > 0 ? `Compartilhado com ${project.sharedWith.length} usuários` : 'Privado') : 'Selecione um projeto'}
        </p>
      </div>

      <div className="flex items-center gap-6">

        {/* Actions Group */}
        <div className="flex items-center gap-3 border-r border-nexus-border pr-6">

            {/* View Switcher */}
            <div className="flex bg-nexus-card border border-nexus-border rounded-md p-0.5">
                <button 
                    onClick={() => onViewChange('board')}
                    className={`p-1.5 rounded transition-all ${currentView === 'board' ? 'bg-nexus-cobalt text-white shadow-sm' : 'text-nexus-muted hover:text-nexus-text'}`}
                    title="Modo Board (Kanban)"
                >
                    <Kanban size={14} />
                </button>
                <button 
                    onClick={() => onViewChange('list')}
                    className={`p-1.5 rounded transition-all ${currentView === 'list' ? 'bg-nexus-cobalt text-white shadow-sm' : 'text-nexus-muted hover:text-nexus-text'}`}
                    title="Modo Lista"
                >
                    <List size={14} />
                </button>
                <button 
                    onClick={() => onViewChange('table')}
                    className={`p-1.5 rounded transition-all ${currentView === 'table' ? 'bg-nexus-cobalt text-white shadow-sm' : 'text-nexus-muted hover:text-nexus-text'}`}
                    title="Modo Tabela"
                >
                    <Table2 size={14} />
                </button>
            </div>

            <div className="h-4 w-px bg-nexus-border"></div>

            {/* Restore Columns Button (Only in Board Mode) */}
            {currentView === 'board' && hiddenColumns.length > 0 && (
                <div className="relative">
                    <button 
                        onClick={() => setShowColumnMenu(!showColumnMenu)}
                        className="flex items-center gap-2 px-3 py-1.5 bg-nexus-card border border-nexus-border rounded-md shadow-sm hover:border-nexus-cobalt transition-colors text-xs font-medium text-nexus-text"
                    >
                        <Eye size={14} className="text-nexus-cobalt" />
                        <span className="hidden sm:inline">Colunas ({hiddenColumns.length})</span>
                    </button>

                    {showColumnMenu && (
                        <div className="absolute top-full mt-2 right-0 w-48 bg-nexus-card border border-nexus-border rounded-lg shadow-xl p-2 z-50 animate-in fade-in zoom-in-95 duration-200">
                            <div className="text-[10px] uppercase font-bold text-nexus-muted mb-2 px-2">Restaurar Colunas</div>
                            {STATUS_COLUMNS.filter(col => hiddenColumns.includes(col.id)).map(col => (
                                <button
                                    key={col.id}
                                    onClick={() => { onToggleColumn(col.id); if(hiddenColumns.length === 1) setShowColumnMenu(false); }}
                                    className="w-full text-left flex items-center gap-2 px-2 py-1.5 hover:bg-nexus-bg rounded text-xs text-nexus-text"
                                >
                                    <PlusCircle size={12} className="text-nexus-cobalt" />
                                    {col.label}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            )}

            {/* Assignee Filter */}
            {onFilterChange && availableAssignees.length > 0 && (
                <div className="flex items-center gap-2 px-3 py-1.5 bg-nexus-card border border-nexus-border rounded-md shadow-sm group hover:border-nexus-cobalt transition-colors">
                    <Filter size={14} className={`text-nexus-muted ${currentFilter ? 'text-nexus-cobalt' : ''}`} />
                    <select 
                        value={currentFilter || ''} 
                        onChange={(e) => onFilterChange(e.target.value || null)}
                        className="bg-transparent text-xs font-medium text-nexus-text outline-none cursor-pointer min-w-[100px]"
                    >
                        <option value="">Membros</option>
                        {availableAssignees.map(user => (
                            <option key={String(user)} value={String(user)}>
                                {String(user)}
                            </option>
                        ))}
                    </select>
                </div>
            )}
        </div>

        {/* Metrics */}
        <div className="flex items-center gap-8 hidden lg:flex">
            {metrics.map((metric, idx) => (
            <div key={idx} className="flex flex-col items-end">
                <div className="flex items-center gap-2">
                    <span className="text-[10px] uppercase tracking-wider font-mono text-nexus-muted">{metric.label}</span>
                    <metric.icon size={12} className={metric.color} />
                </div>
                <span className={`text-xl font-bold font-mono ${metric.color}`}>{metric.value}</span>
            </div>
            ))}
        </div>
      </div>

      {/* Click outside closer for menu (simple implementation) */}
      {showColumnMenu && (
          <div className="fixed inset-0 z-40" onClick={() => setShowColumnMenu(false)}></div>
      )}
    </header>
  );
};

import React, { useState } from 'react';
import { LayoutGrid, Folder, Plus, Activity, Sun, Moon, LogOut, Share2, GripVertical, User as UserIcon, Users, Settings } from 'lucide-react';
import { Project, User, ViewMode } from '../types';
import { ROLES_CONFIG } from '../constants';

interface SidebarProps {
  projects: Project[];
  currentProjectId: string | null;
  setProjectId: (id: string) => void;
  onNewProject: () => void;
  onShareProject: (project: Project) => void;
  onReorderProjects: (projects: Project[]) => void;
  user: User;
  onLogout: () => void;
  isDark: boolean;
  toggleTheme: () => void;
  currentView: ViewMode;
  setView: (view: ViewMode) => void;
  onOpenProfile: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  projects, 
  currentProjectId, 
  setProjectId, 
  onNewProject,
  onShareProject,
  onReorderProjects,
  user,
  onLogout,
  isDark,
  toggleTheme,
  currentView,
  setView,
  onOpenProfile
}) => {
  const [draggedProject, setDraggedProject] = useState<Project | null>(null);

  // Group Projects
  const myProjects = projects.filter(p => p.ownerId === user.id);
  const sharedProjects = projects.filter(p => p.ownerId !== user.id);

  // Find current project object
  const selectedProject = projects.find(p => p.id === currentProjectId);

  const handleDragStart = (e: React.DragEvent, project: Project) => {
    setDraggedProject(project);
    e.dataTransfer.effectAllowed = 'move';
    // Only allow reordering within "My Projects" for now to simplify
    if (project.ownerId !== user.id) {
       e.preventDefault();
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, targetProject: Project) => {
    e.preventDefault();
    if (!draggedProject || draggedProject.id === targetProject.id) return;

    // Simple reorder logic for "My Projects"
    if (draggedProject.ownerId === user.id && targetProject.ownerId === user.id) {
        const newOrder = [...projects];
        const draggedIdx = newOrder.findIndex(p => p.id === draggedProject.id);
        const targetIdx = newOrder.findIndex(p => p.id === targetProject.id);

        // Remove and insert
        newOrder.splice(draggedIdx, 1);
        newOrder.splice(targetIdx, 0, draggedProject);

        onReorderProjects(newOrder);
    }
    setDraggedProject(null);
  };

  const renderProjectItem = (item: Project, isShared: boolean) => (
    <div 
        key={item.id} 
        className={`group relative flex items-center ${!isShared ? 'cursor-grab active:cursor-grabbing' : ''}`}
        draggable={!isShared}
        onDragStart={(e) => handleDragStart(e, item)}
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, item)}
    >
      {!isShared && (
        <div className="absolute left-1 opacity-0 group-hover:opacity-100 text-nexus-muted cursor-grab">
            <GripVertical size={12} />
        </div>
      )}
      <button
        onClick={() => { setProjectId(item.id); setView('board'); }}
        className={`flex-1 flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all duration-200 ml-2 ${
          currentProjectId === item.id && currentView !== 'monitoring'
            ? 'bg-nexus-card text-nexus-cobalt border-l-2 border-nexus-cobalt shadow-sm'
            : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
        }`}
      >
        <Folder size={16} className={`${currentProjectId === item.id && currentView !== 'monitoring' ? 'text-nexus-cobalt' : 'text-nexus-muted'}`} />
        <span className="truncate max-w-[140px]">{item.name}</span>
        {isShared && (
            <span className="text-[9px] bg-nexus-border px-1 rounded text-nexus-muted ml-auto">
                Shared
            </span>
        )}
      </button>
    </div>
  );

  return (
    <aside className="w-64 h-screen bg-nexus-bg border-r border-nexus-border flex flex-col flex-shrink-0 z-20 transition-colors duration-300">
      <div className="h-16 flex items-center px-6 border-b border-nexus-border">
        <div 
            onClick={() => setView('board')}
            className="flex items-center gap-3 text-nexus-text font-bold tracking-tight cursor-pointer hover:opacity-80 transition-opacity"
        >
          <div className="w-8 h-8 bg-nexus-cobalt rounded-sm flex items-center justify-center flex-shrink-0">
             <LayoutGrid size={16} className="text-white" />
          </div>
          <span className="font-mono text-[10px] leading-tight font-bold">PAINEL DE<br/>ACOMPANHAMENTO</span>
        </div>
      </div>

      <div className="flex-1 py-6 px-3 space-y-4 overflow-y-auto">

        <div className="space-y-2">
            {/* New Project Button - Only for Admin/Editors ideally, but let's keep unrestricted for structure, controlled by logic */}
            <button 
                onClick={onNewProject} 
                className="w-full flex items-center justify-center gap-2 py-2 border border-dashed border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors"
            >
                <Plus size={14} /> Novo Projeto
            </button>

            {/* Share Current Project Button (Contextual) */}
            {selectedProject && selectedProject.ownerId === user.id && (
                <button 
                    onClick={() => onShareProject(selectedProject)}
                    className="w-full flex items-center justify-center gap-2 py-2 bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors shadow-sm"
                >
                    <Share2 size={14} /> Compartilhar Projeto
                </button>
            )}
        </div>

        {/* My Projects Section */}
        <div>
            <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                <UserIcon size={12} />
                <span>Meus Projetos</span>
            </div>
            <div className="space-y-0.5">
                {myProjects.length > 0 ? (
                    myProjects.map(p => renderProjectItem(p, false))
                ) : (
                    <div className="px-5 py-2 text-xs text-nexus-muted italic opacity-50">Vazio</div>
                )}
            </div>
        </div>

        {/* Shared Projects Section */}
        {sharedProjects.length > 0 && (
            <div>
                <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                    <Users size={12} />
                    <span>Compartilhados</span>
                </div>
                <div className="space-y-0.5">
                    {sharedProjects.map(p => renderProjectItem(p, true))}
                </div>
            </div>
        )}

        <div className="pt-4 mt-4 border-t border-nexus-border/50">
            <div className="px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">SISTEMA</div>
            <button 
                onClick={() => setView('monitoring')}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${
                    currentView === 'monitoring' 
                    ? 'bg-nexus-card text-nexus-accent border-l-2 border-nexus-accent' 
                    : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
                }`}
            >
            <Activity size={18} />
            <span>Monitoramento</span>
            </button>
        </div>
      </div>

      <div className="p-4 border-t border-nexus-border space-y-4">
        <div className="flex items-center justify-between px-2">
           <span className="text-xs text-nexus-muted font-medium">Tema</span>
           <button 
             onClick={toggleTheme}
             className="p-2 rounded-full bg-nexus-card hover:bg-nexus-hover text-nexus-text border border-nexus-border transition-colors"
           >
             {isDark ? <Sun size={14} /> : <Moon size={14} />}
           </button>
        </div>

        <div 
            onClick={onOpenProfile}
            className="flex items-center gap-3 px-2 pt-2 border-t border-nexus-border cursor-pointer group hover:bg-nexus-card/50 rounded-md p-2 transition-colors"
        >
          <div className="w-8 h-8 rounded bg-gradient-to-br from-nexus-cobalt to-purple-600 flex items-center justify-center text-xs font-bold text-white uppercase relative overflow-hidden">
             {user.avatarUrl ? (
                 <img src={user.avatarUrl} alt={user.username} className="w-full h-full object-cover" />
             ) : (
                 <>
                    {String(user.username || '').substring(0, 2)}
                    <div className="absolute -bottom-1 -right-1 bg-nexus-card rounded-full p-0.5 border border-nexus-border">
                        <Settings size={8} className="text-nexus-muted" />
                    </div>
                 </>
             )}
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            <span className="text-xs font-medium text-nexus-text truncate">{String(user.username)}</span>
            <span className="text-[9px] text-nexus-muted font-mono flex items-center gap-1">
                {ROLES_CONFIG[user.role].label}
            </span>
          </div>
          <button onClick={(e) => { e.stopPropagation(); onLogout(); }} className="text-nexus-muted hover:text-red-500 transition-colors" title="Sair">
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </aside>
  );
};

import React, { useState, useEffect } from 'react';
