          {error && <p className="text-red-500 text-xs flex items-center gap-1 bg-red-500/10 p-2 rounded border border-red-500/20"><WifiOff size={12}/> {error}</p>}

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-md shadow-blue-900/20 mt-2"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : (
                <>
                    {view === 'register' ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
                </>
            )}
          </button>
        </form>

        <div className="mt-4 flex flex-col items-center gap-2 relative z-10">
          <button 
            onClick={() => { 
                const newView = view === 'login' ? 'register' : 'login';
                setView(newView);
                setError(''); 
                setFormData({...formData, role: 'viewer', password: ''}) 
            }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {view === 'login' ? 'Não tem conta? Registrar' : 'Já tem conta? Entrar'}
          </button>

          {view === 'login' && (
              <button 
                onClick={() => { setView('recovery'); setError(''); setSuccessMsg(''); setRecoveryData({ username: '', email: '', newPassword: '' }); setShowNewPasswordInput(false); }}
                className="text-[10px] text-nexus-cobalt hover:underline opacity-80"
              >
                Esqueci minha senha
              </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Workflow, Folder, Plus, Activity, Sun, Moon, LogOut, Share2, GripVertical, User as UserIcon, Users, Settings } from 'lucide-react';
import { Project, User, ViewMode } from '../types';
import { ROLES_CONFIG } from '../constants';

interface SidebarProps {
  projects: Project[];
  currentProjectId: string | null;
  setProjectId: (id: string) => void;
  onNewProject: () => void;
  onShareProject: (project: Project) => void;
  onReorderProjects: (projects: Project[]) => void;
  user: User;
  onLogout: () => void;
  isDark: boolean;
  toggleTheme: () => void;
  currentView: ViewMode;
  setView: (view: ViewMode) => void;
  onOpenProfile: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  projects, 
  currentProjectId, 
  setProjectId, 
  onNewProject,
  onShareProject,
  onReorderProjects,
  user,
  onLogout,
  isDark,
  toggleTheme,
  currentView,
  setView,
  onOpenProfile
}) => {
  const [draggedProject, setDraggedProject] = useState<Project | null>(null);

  // Group Projects
  const myProjects = projects.filter(p => p.ownerId === user.id);
  const sharedProjects = projects.filter(p => p.ownerId !== user.id);

  // Find current project object
  const selectedProject = projects.find(p => p.id === currentProjectId);

  const handleDragStart = (e: React.DragEvent, project: Project) => {
    setDraggedProject(project);
    e.dataTransfer.effectAllowed = 'move';
    // Only allow reordering within "My Projects" for now to simplify
    if (project.ownerId !== user.id) {
       e.preventDefault();
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, targetProject: Project) => {
    e.preventDefault();
    if (!draggedProject || draggedProject.id === targetProject.id) return;

    // Simple reorder logic for "My Projects"
    if (draggedProject.ownerId === user.id && targetProject.ownerId === user.id) {
        const newOrder = [...projects];
        const draggedIdx = newOrder.findIndex(p => p.id === draggedProject.id);
        const targetIdx = newOrder.findIndex(p => p.id === targetProject.id);

        // Remove and insert
        newOrder.splice(draggedIdx, 1);
        newOrder.splice(targetIdx, 0, draggedProject);

        onReorderProjects(newOrder);
    }
    setDraggedProject(null);
  };

  const renderProjectItem = (item: Project, isShared: boolean) => (
    <div 
        key={item.id} 
        className={`group relative flex items-center ${!isShared ? 'cursor-grab active:cursor-grabbing' : ''}`}
        draggable={!isShared}
        onDragStart={(e) => handleDragStart(e, item)}
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, item)}
    >
      {!isShared && (
        <div className="absolute left-1 opacity-0 group-hover:opacity-100 text-nexus-muted cursor-grab">
            <GripVertical size={12} />
        </div>
      )}
      <button
        onClick={() => { setProjectId(item.id); setView('board'); }}
        className={`flex-1 flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-all duration-200 ml-2 ${
          currentProjectId === item.id && currentView !== 'monitoring'
            ? 'bg-nexus-card text-nexus-cobalt border-l-2 border-nexus-cobalt shadow-sm'
            : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
        }`}
      >
        <Folder size={16} className={`${currentProjectId === item.id && currentView !== 'monitoring' ? 'text-nexus-cobalt' : 'text-nexus-muted'}`} />
        <span className="truncate max-w-[140px]">{item.name}</span>
        {isShared && (
            <span className="text-[9px] bg-nexus-border px-1 rounded text-nexus-muted ml-auto">
                Shared
            </span>
        )}
      </button>
    </div>
  );

  return (
    <aside className="w-64 h-screen bg-nexus-bg border-r border-nexus-border flex flex-col flex-shrink-0 z-20 transition-colors duration-300">
      <div className="h-16 flex items-center px-6 border-b border-nexus-border">
        <div 
            onClick={() => setView('board')}
            className="flex items-center gap-3 text-nexus-text font-bold tracking-tight cursor-pointer hover:opacity-80 transition-opacity"
        >
          <div className="w-8 h-8 bg-nexus-cobalt rounded-sm flex items-center justify-center flex-shrink-0">
             <Workflow size={16} className="text-white" />
          </div>
          <span className="font-mono text-[10px] leading-tight font-bold">PAINEL DE<br/>ACOMPANHAMENTO</span>
        </div>
      </div>

      <div className="flex-1 py-6 px-3 space-y-4 overflow-y-auto">

        <div className="space-y-2">
            {/* New Project Button - Only for Admin/Editors ideally, but let's keep unrestricted for structure, controlled by logic */}
            <button 
                onClick={onNewProject} 
                className="w-full flex items-center justify-center gap-2 py-2 border border-dashed border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors"
            >
                <Plus size={14} /> Novo Projeto
            </button>

            {/* Share Current Project Button (Contextual) */}
            {selectedProject && selectedProject.ownerId === user.id && (
                <button 
                    onClick={() => onShareProject(selectedProject)}
                    className="w-full flex items-center justify-center gap-2 py-2 bg-nexus-card border border-nexus-border rounded hover:border-nexus-cobalt hover:text-nexus-cobalt text-nexus-muted text-xs font-bold uppercase transition-colors shadow-sm"
                >
                    <Share2 size={14} /> Compartilhar Projeto
                </button>
            )}
        </div>

        {/* My Projects Section */}
        <div>
            <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                <UserIcon size={12} />
                <span>Meus Projetos</span>
            </div>
            <div className="space-y-0.5">
                {myProjects.length > 0 ? (
                    myProjects.map(p => renderProjectItem(p, false))
                ) : (
                    <div className="px-5 py-2 text-xs text-nexus-muted italic opacity-50">Vazio</div>
                )}
            </div>
        </div>

        {/* Shared Projects Section */}
        {sharedProjects.length > 0 && (
            <div>
                <div className="flex items-center gap-2 px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">
                    <Users size={12} />
                    <span>Compartilhados</span>
                </div>
                <div className="space-y-0.5">
                    {sharedProjects.map(p => renderProjectItem(p, true))}
                </div>
            </div>
        )}

        <div className="pt-4 mt-4 border-t border-nexus-border/50">
            <div className="px-3 mb-2 text-xs font-mono text-nexus-muted uppercase tracking-widest">SISTEMA</div>
            <button 
                onClick={() => setView('monitoring')}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${
                    currentView === 'monitoring' 
                    ? 'bg-nexus-card text-nexus-accent border-l-2 border-nexus-accent' 
                    : 'text-nexus-muted hover:text-nexus-text hover:bg-nexus-hover'
                }`}
            >
            <Activity size={18} />
            <span>Monitoramento</span>
            </button>
        </div>
      </div>

      <div className="p-4 border-t border-nexus-border space-y-4">
        <div className="flex items-center justify-between px-2">
           <span className="text-xs text-nexus-muted font-medium">Tema</span>
           <button 
             onClick={toggleTheme}
             className="p-2 rounded-full bg-nexus-card hover:bg-nexus-hover text-nexus-text border border-nexus-border transition-colors"
           >
             {isDark ? <Sun size={14} /> : <Moon size={14} />}
           </button>
        </div>

        <div 
            onClick={onOpenProfile}
            className="flex items-center gap-3 px-2 pt-2 border-t border-nexus-border cursor-pointer group hover:bg-nexus-card/50 rounded-md p-2 transition-colors"
        >
          <div className="w-8 h-8 rounded bg-gradient-to-br from-nexus-cobalt to-purple-600 flex items-center justify-center text-xs font-bold text-white uppercase relative overflow-hidden">
             {user.avatarUrl ? (
                 <img src={user.avatarUrl} alt={user.username} className="w-full h-full object-cover" />
             ) : (
                 <>
                    {String(user.username || '').substring(0, 2)}
                    <div className="absolute -bottom-1 -right-1 bg-nexus-card rounded-full p-0.5 border border-nexus-border">
                        <Settings size={8} className="text-nexus-muted" />
                    </div>
                 </>
             )}
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            <span className="text-xs font-medium text-nexus-text truncate">{String(user.username)}</span>
            <span className="text-[9px] text-nexus-muted font-mono flex items-center gap-1">
                {ROLES_CONFIG[user.role].label}
            </span>
          </div>
          <button onClick={(e) => { e.stopPropagation(); onLogout(); }} className="text-nexus-muted hover:text-red-500 transition-colors" title="Sair">
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </aside>
  );
};

import React, { useState, useEffect } from 'react';
import { Sparkles, ArrowRight, Loader2, WifiOff, ShieldCheck, Lock, User as UserIcon, Mail, KeyRound } from 'lucide-react';
import { User } from '../types';
import { supabase } from '../supabaseClient';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [view, setView] = useState<'login' | 'register' | 'recovery'>('login');

  const [formData, setFormData] = useState({
      username: '',
      password: '',
      email: '',
      role: 'viewer' as 'admin' | 'editor' | 'viewer'
  });

  const [recoveryData, setRecoveryData] = useState({
      username: '',
      email: '',
      newPassword: ''
  });

  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [showNewPasswordInput, setShowNewPasswordInput] = useState(false);

  // Auto-seed Samuel_IA logic
  useEffect(() => {
    const checkAndSeedSamuel = async () => {
        try {
            // Check if Samuel_IA exists
            const { data } = await supabase.from('profiles').select('username').eq('username', 'Samuel_IA').single();

            // Only insert if user does NOT exist. 
            // We removed the 'else' block that was forcing the password reset on every reload.
            if (!data) {
                await supabase.from('profiles').insert([{
                    username: 'Samuel_IA',
                    password: 'ChangeMe123!', 
                    email: 'samuellucas2010s@gmail.com',
                    role: 'admin',
                    created_at: new Date().toISOString()
                }]);
            } 
        } catch (e) {
            console.warn("Auto-seed check failed (likely offline or permission issue)", e);
        }
    };
    checkAndSeedSamuel();
  }, []);

  const validatePassword = (pwd: string) => {
      const hasUpper = /[A-Z]/.test(pwd);
      const hasLower = /[a-z]/.test(pwd);
      const hasNumber = /[0-9]/.test(pwd);
      const hasSpecial = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(pwd);
      return hasUpper && hasLower && hasNumber && hasSpecial;
  };

  const handleRecovery = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setSuccessMsg('');
      setLoading(true);

      if (!recoveryData.username || !recoveryData.email) {
          setError("Preencha usuário e e-mail.");
          setLoading(false);
          return;
      }

      // Special Check for Samuel_IA bypass
      const isSamuel = recoveryData.username === 'Samuel_IA' && recoveryData.email === 'samuellucas2010s@gmail.com';

      if (!showNewPasswordInput) {
          // STEP 1: VERIFY USER
          try {
            let userFound = false;

            if (isSamuel) {
                userFound = true;
            } else {
                const { data } = await supabase
                    .from('profiles')
                    .select('*')
                    .eq('username', recoveryData.username)
                    .eq('email', recoveryData.email)
                    .single();
                if (data) userFound = true;
            }

            if (userFound) {
                setShowNewPasswordInput(true);
                setSuccessMsg("Conta localizada! Digite a nova senha abaixo.");
            } else {
                setError("Dados não conferem com nossos registros.");
            }
          } catch (err) {
              // Fallback for demo/offline
              if (isSamuel) {
                  setShowNewPasswordInput(true);
                  setSuccessMsg("Conta localizada (Modo Offline)! Digite a nova senha.");
              } else {
                  setError("Erro ao buscar conta ou dados inválidos.");
              }
          }
          setLoading(false);
      } else {
          // STEP 2: RESET PASSWORD
          if (!validatePassword(recoveryData.newPassword)) {
              setError('A senha deve conter: Maiúscula, minúscula, número e especial.');
              setLoading(false);
              return;
          }

          try {
              const { error: updateError } = await supabase
                .from('profiles')
                .update({ password: recoveryData.newPassword })
                .eq('username', recoveryData.username);

              if (updateError && !isSamuel) throw updateError;

              setSuccessMsg("Senha redefinida com sucesso! Faça login.");
              setTimeout(() => {
                  setView('login');
                  setFormData(prev => ({ ...prev, username: recoveryData.username, password: '' }));
                  setRecoveryData({ username: '', email: '', newPassword: '' });
                  setShowNewPasswordInput(false);
              }, 2000);

          } catch (err) {
               if (isSamuel) {
                   setSuccessMsg("Senha redefinida localmente! Faça login.");
                   setTimeout(() => setView('login'), 2000);
               } else {
                   setError("Erro ao redefinir senha.");
               }
          }
          setLoading(false);
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (view === 'login') {
        if (!formData.username.trim() || !formData.password) {
            setError('Preencha usuário e senha.');
            setLoading(false);
            return;
        }

        // --- MASTER RESCUE BYPASS ---
        // Ensures access for the owner even if DB fails OR if using the emergency backdoor
        if (formData.username === 'Samuel_IA' && formData.password === 'admin') {
             onLogin({ 
                id: 'Samuel_IA', 
                username: 'Samuel_IA', 
                role: 'admin',
                email: 'samuellucas2010s@gmail.com'
            });
            setLoading(false);
            return;
        }
    } else if (view === 'register') {
         if (!formData.username || !formData.password || !formData.email) {
             setError('Todos os campos são obrigatórios.');
             setLoading(false);
             return;
         }
         if (!validatePassword(formData.password)) {
            setError('A senha deve conter: Maiúscula, minúscula, número e caractere especial.');
            setLoading(false);
            return;
        }
    }

    try {
      if (view === 'register') {
        // 1. Check if user exists
        const { data: existingUser } = await supabase
            .from('profiles')
            .select('username')
            .eq('username', formData.username)
            .single();

        if (existingUser) {
          setError('Usuário já existe. Tente fazer login.');
          setLoading(false);
          return;
        }

        // 2. Register new user
        const { error: insertError } = await supabase
          .from('profiles')
          .insert([{ 
              username: formData.username,
              password: formData.password,
              email: formData.email,
              role: formData.role,
              created_at: new Date().toISOString()
          }]);

        if (insertError) throw insertError;

        onLogin({ 
            id: formData.username, 
            username: formData.username, 
            role: formData.role,
            email: formData.email
        }); 

      } else {
        // LOGIN LOGIC
        const { data: userRecord, error: loginError } = await supabase
            .from('profiles')
            .select('*')
            .eq('username', formData.username)
            .eq('password', formData.password)
            .single();

        if (loginError || !userRecord) {
            setError('Usuário ou senha incorretos.');
            setLoading(false);
            return;
        }

        onLogin({ 
            id: userRecord.username, 
            username: userRecord.username,
            role: userRecord.role || 'viewer',
            avatarUrl: userRecord.avatar_url || undefined,
            whatsapp: userRecord.whatsapp || undefined,
            email: userRecord.email || undefined
        });
      }

    } catch (err: any) {
      console.warn("Supabase Action Failed:", err);
      // OFFLINE FALLBACK
      if (err.message && (err.message.includes('fetch') || err.message.includes('connection'))) {
          console.log("Entering Offline Mode...");
          onLogin({ 
              id: formData.username, 
              username: formData.username,
              role: 'admin', // Default to admin in offline
              email: formData.email
          });
      } else {
          setError('Erro na conexão. Tente novamente.');
      }
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER RECOVERY VIEW ---
  if (view === 'recovery') {
      return (
        <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center animate-in fade-in duration-300">
            <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl relative overflow-hidden">
                <div className="flex flex-col items-center mb-6">
                    <div className="w-12 h-12 bg-nexus-accent rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-amber-900/50">
                        <KeyRound size={24} className="text-white" />
                    </div>
                    <h1 className="text-xl font-bold text-nexus-text">Recuperar Conta</h1>
                    <p className="text-xs text-nexus-muted mt-2 text-center">
                        {showNewPasswordInput ? "Defina sua nova senha." : "Confirme seus dados para continuar."}
                    </p>
                </div>

                <form onSubmit={handleRecovery} className="space-y-4">
                    {!showNewPasswordInput ? (
                        <>
                            <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-nexus-muted flex items-center gap-1">
                                    <UserIcon size={10} /> Usuário
                                </label>
                                <input 
                                    type="text" 
                                    value={recoveryData.username}
                                    onChange={(e) => setRecoveryData({...recoveryData, username: e.target.value})}
                                    className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                                    placeholder="Nome de usuário..."
                                />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-nexus-muted flex items-center gap-1">
                                    <Mail size={10} /> Email
                                </label>
                                <input 
                                    type="email" 
                                    value={recoveryData.email}
                                    onChange={(e) => setRecoveryData({...recoveryData, email: e.target.value})}
                                    className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                                    placeholder="Email cadastrado..."
                                />
                            </div>
                        </>
                    ) : (
                        <div className="space-y-1 animate-in fade-in slide-in-from-right-4">
                            <label className="text-[10px] uppercase font-bold text-nexus-muted flex items-center gap-1">
                                <Lock size={10} /> Nova Senha
                            </label>
                            <input 
                                type="password" 
                                value={recoveryData.newPassword}
                                onChange={(e) => setRecoveryData({...recoveryData, newPassword: e.target.value})}
                                className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none text-sm"
                                placeholder="Nova senha forte..."
                            />
                        </div>
                    )}

                    {error && <p className="text-red-500 text-xs flex items-center gap-1 bg-red-500/10 p-2 rounded">{error}</p>}
                    {successMsg && <p className="text-green-500 text-xs flex items-center gap-1 bg-green-500/10 p-2 rounded">{successMsg}</p>}

                    <button 
                        type="submit"
                        disabled={loading}
                        className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-all flex items-center justify-center gap-2 mt-2"
                    >
                        {loading ? <Loader2 size={16} className="animate-spin" /> : (showNewPasswordInput ? 'Redefinir Senha' : 'Verificar Dados')}
                    </button>
                </form>

                <div className="mt-4 text-center">
                    <button 
                        onClick={() => { setView('login'); setError(''); setSuccessMsg(''); }}
                        className="text-xs text-nexus-muted hover:text-nexus-text underline"
                    >
                        Voltar para Login
                    </button>
                </div>
            </div>
        </div>
      );
  }

  // --- RENDER LOGIN/REGISTER VIEW ---
  return (
    <div className="flex h-screen w-screen bg-nexus-bg items-center justify-center animate-in fade-in duration-300">
      <div className="w-96 bg-nexus-card border border-nexus-border p-8 rounded-lg shadow-2xl relative overflow-hidden">

        <div className="absolute -top-10 -right-10 w-32 h-32 bg-nexus-cobalt/10 rounded-full blur-3xl"></div>
        <div className="absolute -bottom-10 -left-10 w-32 h-32 bg-nexus-accent/10 rounded-full blur-3xl"></div>

        <div className="flex flex-col items-center mb-6 relative z-10">
          <div className="w-12 h-12 bg-nexus-cobalt rounded-lg flex items-center justify-center mb-4 shadow-lg shadow-blue-900/50">
             <Sparkles size={24} className="text-white" />
          </div>
          <h1 className="text-2xl font-bold text-nexus-text font-mono tracking-tight">LUCKFLOW</h1>
          <p className="text-xs text-nexus-muted mt-2 uppercase tracking-widest text-center">Gestão & Tecnologia</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 relative z-10">
          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                <UserIcon size={10} /> Usuário
            </label>
            <input 
              type="text" 
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
              placeholder="Digite seu usuário..."
              disabled={loading}
            />
          </div>

          {view === 'register' && (
            <>
                <div className="space-y-1 animate-in fade-in slide-in-from-top-2">
                    <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                        <Mail size={10} /> Email
                    </label>
                    <input 
                        type="email" 
                        value={formData.email}
                        onChange={(e) => setFormData({...formData, email: e.target.value})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
                        placeholder="seu@email.com"
                        disabled={loading}
                    />
                </div>
                <div className="space-y-1 animate-in fade-in slide-in-from-top-2 duration-300">
                    <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                        <ShieldCheck size={10} /> Cargo
                    </label>
                    <select
                        value={formData.role}
                        onChange={(e) => setFormData({...formData, role: e.target.value as any})}
                        className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm cursor-pointer"
                    >
                        <option value="admin">Administrador</option>
                        <option value="editor">Gerente</option>
                        <option value="viewer">Usuário</option>
                    </select>
                </div>
            </>
          )}

          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-nexus-muted block flex items-center gap-1">
                <Lock size={10} /> Senha
            </label>
            <input 
              type="password" 
              value={formData.password}
              onChange={(e) => setFormData({...formData, password: e.target.value})}
              className="w-full bg-nexus-bg border border-nexus-border rounded p-2.5 text-nexus-text focus:border-nexus-cobalt outline-none transition-colors text-sm"
              placeholder="********"
              disabled={loading}
            />
            {view === 'register' && (
                <p className="text-[9px] text-nexus-muted leading-tight mt-1">
                    Requer: Maiúscula, minúscula, número e caractere especial.
                </p>
            )}
          </div>

          {error && <p className="text-red-500 text-xs flex items-center gap-1 bg-red-500/10 p-2 rounded border border-red-500/20"><WifiOff size={12}/> {error}</p>}

          <button 
            type="submit"
            disabled={loading}
            className="w-full bg-nexus-cobalt hover:bg-blue-600 text-white font-bold py-2.5 rounded transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-md shadow-blue-900/20 mt-2"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : (
                <>
                    {view === 'register' ? 'Criar Conta' : 'Entrar'} <ArrowRight size={16} />
                </>
            )}
          </button>
        </form>

        <div className="mt-4 flex flex-col items-center gap-2 relative z-10">
          <button 
            onClick={() => { 
                const newView = view === 'login' ? 'register' : 'login';
                setView(newView);
                setError(''); 
                setFormData({...formData, role: 'viewer', password: ''}) 
            }}
            className="text-xs text-nexus-muted hover:text-nexus-text underline"
          >
            {view === 'login' ? 'Não tem conta? Registrar' : 'Já tem conta? Entrar'}
          </button>

          {view === 'login' && (
              <button 
                onClick={() => { setView('recovery'); setError(''); setSuccessMsg(''); setRecoveryData({ username: '', email: '', newPassword: '' }); setShowNewPasswordInput(false); }}
                className="text-[10px] text-nexus-cobalt hover:underline opacity-80"
              >
                Esqueci minha senha
              </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sparkles, Folder, Plus, Activity, Sun, Moon, LogOut, Share2, GripVertical, User as UserIcon, Users, Settings } from 'lucide-react';
import { Project, User, ViewMode } from '../types';
import { ROLES_CONFIG } from '../constants';

interface SidebarProps {
  projects: Project[];
  currentProjectId: string | null;
  setProjectId: (id: string) => void;
  onNewProject: () => void;
  onShareProject: (project: Project) => void;
  onReorderProjects: (projects: Project[]) => void;
  user: User;
  onLogout: () => void;
  isDark: boolean;
  toggleTheme: () => void;
  currentView: ViewMode;
  setView: (view: ViewMode) => void;
